insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('CHC384H1', 'Music and Liturgy', '24L', 'An exploration of the place of music in Christian worship, with a focus on contemporary Eucharist. Examination of the development of liturgico-musical principles and their practical implementation. Topics may include styles and repertoires, singing liturgical texts, hymnody and other forms of congregational singing, choirs and cantors, the use of instruments.', 'SMC363H1,  SMC384H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC390Y1', 'Independent Studies in Christianity and Culture', null, 'An independent research project to be proposed by the student and supervised by a Christianity and Culture faculty member. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Not eligible for CR/NCR option.', 'CHC391H1', null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 1.0, "department": "CHC"}]}'::jsonb),
    ('CHC391H1', 'Independent Studies in Christianity and Culture', null, 'An independent research project to be proposed by the student and supervised by a Christianity and Culture faculty member. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Not eligible for CR/NCR option.', 'CHC390Y1', null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 1.0, "department": "CHC"}]}'::jsonb),
    ('CHC400H1', 'Advanced Topics in Christianity and Culture I', '24L', 'An advanced seminar in Christianity and Culture as determined by the instructor.', null, 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('CHC433Y1', 'Independent Studies in Christianity and Culture', null, 'An independent research project to be proposed by the student and supervised by a Christianity and Culture faculty member. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Not eligible for CR/NCR option.', 'CHC434H1', null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "CHC"}]}'::jsonb),
    ('CHC434H1', 'Independent Studies in Christianity and Culture', null, 'An independent research project to be proposed by the student and supervised by a Christianity and Culture faculty member. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Not eligible for CR/NCR option.', 'CHC433Y1', null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "CHC"}]}'::jsonb),
    ('CHC456H1', 'Indian Christianity', '24S', 'An advanced study of the historical development, major theological writings and contemporary ethnographic studies of diverse Christian traditions in South Asia. Topics to be covered include the legacy of Thomas Christianity, Hindu-Christian dialogue, the Christian ashram movement, liturgical inculturation and religious hybridity.', 'SMC456H1', 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('CHC471H1', 'Internship', null, 'Arranged by each student in consultation with faculty, the internship enables teacher candidates to integrate, extend and deepen their learning experiences in a way not otherwise available in the program. A description of the internship, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information is available from the SMC Principal''s Office, smc.programs@utoronto.ca. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CHC472H1', 'Research Seminar in Christianity and Culture', '24S', 'The seminar provides majors in their final year of study with the opportunity to pursue advanced research projects in Christianity and Culture.', null, 2, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('CHM101H1', 'The Chemistry and Biology of Organic Molecules: Sex, Drugs and Rock and Roll!', '30L/6T', 'An introduction to chemistry and chemical principles for non-scientists, with a focus on the chemistry and biology of organic molecules. The myriad roles these compounds play in our lives are discussed, including their use of pheromones, medicines and weapons, and their effect on colour, taste and smell.', null, 5, null::jsonb),
    ('CHM135H1', 'Chemistry: Physical Principles', '36L/12T/18P', 'CHM135H1 and  CHM136H1 cannot be taken in the same session. Structure of matter, gases, liquids and solids; phase equilibria and phase diagrams; colligative properties; chemical equilibria; electrolyte solutions and electrochemistry; reaction kinetics; introduction to thermodynamics. Recommended for students in life and health science programs that involve a small amount of chemistry. (Lab Materials Fee: $26).', 'CHM151Y1,  CHMA11H3,  CHM110H5', 5, null::jsonb),
    ('CHM136H1', 'Introductory Organic Chemistry I', '36L/12T/18P', 'CHM135H1 and  CHM136H1 cannot be taken in the same session. An introduction to principles of structure and their relation to reactivity of organic molecules: molecular structure, stereochemistry, functional groups, reactions, and mechanisms. Recommended for students in life and health science programs that involve a small amount of chemistry. (Lab Materials Fee: $26).', 'CHM151Y1,  CHM242H5,  CHMB41H3', 5, '{"operator": "AND", "items": ["CHM135H1"]}'::jsonb),
    ('CHM151Y1', 'Chemistry: The Molecular Science', '72L/24T/35P', 'An introduction to the major areas of modern chemistry, including organic and biological chemistry; inorganic/materials chemistry and spectroscopy; and physical chemistry/chemical physics. The course is highly recommended for students who plan to enrol in one of the chemistry specialist programs, or who will be including a substantial amount of chemistry in their degree (such as those following a chemistry major or minor program). The combination of  CHM151Y1 and  CHM249H1 serves as a full year introductory course in organic chemistry with laboratory. (Lab Materials Fee: $39). Note:  CHM151Y1 has a unique Course Community where the undergraduate experience in chemistry is greatly enhanced through a series of workshops, research seminars, tours, outreach opportunities and social activities. 90-minute biweekly Course Community meetings are held during laboratory class hours during alternate weeks to the laboratory sessions. The lab time is reserved for  CHM151Y1 activities every week of each semester.', 'CHM135H1,  CHM136H1,  CHMA10H3,  CHMA11H3,  CHMB41H3,  CHM110H5,  CHM120H5', 5, null::jsonb),
    ('CHM193H1', 'Chemicals in the Environment: The Good, the Bad, and the Ugly', '24S', 'The world is made up of chemicals: some are natural and some are invented and manufactured by humans. New chemicals are often intended to make our lives safer and easier (e.g., plastics, pesticides, personal care products) but may have unanticipated consequences once they are released into the world. In this seminar course, students will discover what properties of chemicals can lead to risks for the environment and for human health. Through discussion of how chemicals in the environment are understood by scientists, and described in popular media, students will develop improved scientific literacy to better evaluate risk in their own lives. Restricted to first-year students. Not eligible for CR/NCR option.', 'CHM211H1', 5, null::jsonb),
    ('CHM194H1', 'Science and Human Values', '24S', 'There is a tension between creativity and the search for truth, which in science can be looking for patterns in nature. With examples drawn particularly from reports of scientific discoveries that have generated controversy, this seminar course will introduce the underlying principles and history of science, as well as how science and its boundaries are evolving, and how these influence human values. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('CHM196H1', 'The Quantum World and Its Classical Limit', '24S', 'This course seeks to demystify quantum mechanics and equip students to critically analyze popular depictions of quantum phenomena. While quantum mechanics provides a reliable description of the behavior of atoms, molecules and photons, most people are uncomfortable with some of its predictions, such as "quantum entanglement" between distant particles. In this course we will delve into key aspects of quantum mechanics and its more comfortable classical limit, focusing first on its manifestations in nature and then on fundamental issues such as uncertainty, interference, entanglement, and decoherence. This course will appeal to students with enthusiasm for physics. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('CHM197H1', 'Environmental Chemistry in a Sustainable World', '24S', 'Rapid and widespread industrialization is changing the chemical nature of the planet. In order to have a sustainable future, we need to manage chemicals released by humankind and understand their effects on the environment and on us. Each year, this seminar course designed for non-science students will address the fundamental science behind a specific topic in this field, such as the interactions of our energy choices and the environment, or changes in water and air quality. Emphasis is given to reading from both the popular media and scientific literature. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('CHM198H1', 'Biosensor Technology and Applications for the Non-Scientist', '24S', 'This breadth course introduces uses of and key ideas behind biosensor technology. Sensors will be familiar to all, playing key roles in our everyday lives, for example in touch screens or in automotive technology. Biosensor devices are fabricated from an electrical transducer which is intimately connected to a biochemical probe such as an enzyme or antibody. The idea is that a detectable electrical signal can be obtained when a target molecule or ion binds to the probe. Such a device offers many applications. These range from the detection of biological markers in blood and serum to test for genetic and infectious disease, to the selective monitoring of biomolecules for public safety, or in biotechnology or other industrial processes. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('CHM199H1', 'The Context of Chemistry: Origins, Concepts, Tools, and Challenges', '24S', 'Chemistry is a practical as well as a conceptual science that serves as the basis for applications in many other fields. The ideas and methods have evolved from diverse inputs leading to widely accepted sets of standard of facts. This collective knowledge has led to progress in the quality and understanding of life at a molecular level. While the facts of chemistry are taught in established courses, the context of what we know, the limitations and challenges of what chemistry can do and how we got to this point will be the targets for discovery by students in this course. The course will operate in a seminar model, combining presentations, readings, reports and discussions of current and historical issues. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('CHM209H1', 'Science of the Modern Kitchen', '24L', 'The properties of different food types will be discussed, as well as how they can be manipulated in the kitchen to transform taste and texture. Concepts will be considered through the lens of the scientific method, and many of the ingredients and practices of modernist cuisine will be examined. This course is intended for students with no science background.', 'CHM135H1/ CHM136H1/ CHM138H1/ CHM139H1/ CHM151Y1', 5, null::jsonb),
    ('CHM210H1', 'Chemistry of Environmental Change', '24L/12T', 'This course examines the fundamental chemical processes of the Earth''s natural environment, and changes induced by human activity. Topics covered are related to the atmosphere and the hydrosphere: urban air pollution, stratospheric ozone depletion, acid rain, climate change, water resources and pollution, wastewater analysis, biogeochemistry, and inorganic metals in the environment. Skills in data analysis and visualization will be developed through an introduction to the R programming language and its use in several assignments.', 'ENV235Y1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM135H1", "CHM151Y1"]}, {"operator": "OR", "items": ["MAT135H1", "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('CHM217H1', 'Introduction to Analytical Chemistry', '30L/6T/52P', 'Introduction to the science of chemical measurement, from sampling through analysis to the interpretation of results, including how water, food products, pharmaceuticals, and dietary supplements are analysed for content, quality, and potential contaminants. Also how to interpret experimental measurements, compare results and procedures, and calibrate analytical instrumentation. Through closely integrated classes, laboratories, and tutorials, this highly practical course introduces a variety of analytical techniques including volumetric methods, potentiometry, uv/visible and infrared spectrophotometry, flame atomic absorption spectrometry, and chromatography. Additional information can be found at http://www.chem.utoronto.ca/coursenotes/CHM217/. (Lab Materials Fee: $39).', 'CHM211H5,  CHMB16H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('CHM220H1', 'Physical Chemistry for Life Sciences', '36L/12T', 'Introduction to thermodynamics; kinetics; phase equilibrium, properties of mixtures, chemical equilibrium, electrochemistry; introduction to quantum mechanics and spectroscopy. This course is recommended for students in life and health science programs that involve a small amount of chemistry.', 'CHM222H1,  CHMB20H3,  JCP221H5/  CHM221H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('CHM222H1', 'Introduction to Physical Chemistry', '24L/12T', 'Topics: introductory thermodynamics, first and second law and applications; chemical equilibrium. The course is intended for students who will be following the majority of chemistry specialist programs (Biological Chemistry specialist students are highly recommended to take  CHM220H1).', 'CHM220H1,  CHMB20H3,  CHM221H5,  JCP221H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["PHY131H1", "PHY132H1"]}, {"operator": "AND", "items": ["PHY151H1", "PHY152H1"]}]}]}'::jsonb),
    ('CHM223H1', 'Physical Chemistry: The Molecular Viewpoint', '24L/12T', 'CHM223H1 introduces key concepts and mathematical approaches that underly fundamental quantum mechanical models of atoms and molecules. Connections are drawn between these microscopic models and macroscopic properties of systems in physical chemistry—both how experimental observations shape the chosen structure of the models, and how these models can now successfully predict and interpret the results of experiments.', 'CHMB21H3', 5, '{"operator": "OR", "items": ["CHM220H1", "CHM222H1", "MSE202H1"]}'::jsonb),
    ('CHM228H1', 'Mathematical Methods for Chemical Sciences', '36L/12T', 'The use of mathematics as a language to describe chemical systems is prevalent across all fields of chemistry, such as in expressing reaction yields, assessing molecular symmetry, predicting and validating reaction mechanisms, and modeling molecular properties. This course is designed to equip Chemistry program students with the mathematical foundations needed in upper-year chemistry courses, with a particular focus on physical chemistry principles. Topics will include a brief review of common functions and coordinate systems, and will cover selected topics in complex numbers, multivariable calculus, scalar and vector algebra, matrix algebra, operators, eigenvectors and eigenvalues, differential equations, and special interest topics as time permits. The course material will be delivered within the context of chemistry concepts such as ideal gases, reaction rates, thermodynamic functions, and quantum mechanical systems. Emphasis will be placed on mastering foundational concepts and developing problem-solving strategies tailored to chemical applications.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('CHM236H1', 'Introductory Inorganic Chemistry I', '24L/12T', 'Inorganic chemistry is the chemistry of all the periodic table elements and includes the synthesis of the largest volume chemicals on Earth, the key energy-generating reactions and catalysts needed for a green planet, and compounds exploited in modern electronic and photonic devices. This is the first part (followed by  CHM237H1 and then  CHM338H1) of a two-year sequence illustrating the rich variety of structures, physical properties, and reactions of compounds of the elements across and down the periodic table. It includes fundamentals of bonding, symmetry, and acid-base/ redox reactions of molecular compounds and transition metal complexes and applications of this chemistry in the world.  CHM236H1 is recommended for students interested in broadly learning about chemistry across the periodic table.', 'CHM231H5,  CHM238Y1,  CHMB31H3', 5, '{"operator": "OR", "items": ["CHM151Y1", {"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}]}'::jsonb),
    ('CHM237H1', 'Introductory Inorganic Chemistry II', '24L/6T/48P', 'This course is a continuation from  CHM236H1 which further studies the chemistry of the elements across the periodic table. It will cover topics that include the periodic properties of the elements, the structures, bonding and properties of main group compounds and transition metal complexes, inorganic solid-state materials, and solid-state chemistry with applications in advanced technologies. A strong emphasis on developing laboratory techniques and communication skills is made through the practical component of the course.  CHM236H1 is strongly recommended for students exploring experimental synthetic chemistry as part of their degree program. (Lab Materials Fee: $39)', 'CHM231H5,  CHM238Y1,  CHMB31H3', 5, '{"operator": "AND", "items": ["CHM236H1"]}'::jsonb),
    ('CHM247H1', 'Introductory Organic Chemistry II', '36L/12T/22P', 'Reactions of organic compounds. Principles of mechanism, synthesis, and spectroscopy, continuing from  CHM136H1. This course is recommended for students in life and health science programs that involve a small amount of chemistry. Students who will be including a substantial amount of chemistry in their degree (including those following a chemistry major program) are strongly encouraged to take  CHM249H1. (Lab Materials Fee: $26).', 'CHM249H1,  CHM243H5,  CHMB42H3', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}'::jsonb),
    ('CHM249H1', 'Organic Chemistry', '36L/52P', 'An introductory course in organic chemistry, based around the themes of structure, bonding, reaction mechanism, and synthesis. Reactions are discussed with a view to understanding mechanisms and how they are useful in the multi-step synthesis of medicinally and industrially important compounds. An introduction to the spectroscopy of organic molecules is also given, as well as a discussion of topics relating to the biological behaviour of organic molecules and medicinal chemistry. Students are also introduced to green chemistry approaches from an experimental perspective. This course continues from  CHM151Y1 or  CHM136H1 and is designed for students enrolled in any chemistry specialist or major program. (Lab Materials Fee: $39).', 'CHM247H1,  CHM243H5,  CHMB42H3', 5, '{"operator": "OR", "items": ["CHM151Y1", {"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}]}'::jsonb),
    ('CHM295H1', 'Research Experience in Chemistry', '12L/48P', 'A course-based undergraduate research experience (CURE) that will introduce students to experimental research in chemistry from a physical science perspective, involving measurement, use of scientific instruments, and data analysis. Students will collaborate in teams to acquire research skills by carrying out laboratory work on a specific project that is defined by various chemistry departmental research groups. The topics will cover a range of research areas; however the approach will include aspects of physical chemistry such as spectroscopy, thermodynamics, nanotechnology, properties of materials, and reaction kinetics. Training in the use of instruments and data acquisition and analysis will be provided. (Lab Materials Fee: $39).', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["PHY131H1", "PHY132H1"]}, {"operator": "AND", "items": ["PHY151H1", "PHY152H1"]}]}]}'::jsonb),
    ('CHM299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CHM299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CHM310H1', 'Environmental Fate and Toxicity of Organic Contaminants', '24L/12T', 'Organic chemical contaminants surround us in our everyday lives (e.g. in medications, personal care products, flame retardants, refrigerants) and because of this, they are present in the environment and in ourselves. In this course we will explore the fate of chemicals in the environment as a whole, as well as in the body, to understand how chemicals can be designed to mitigate the risks associated with their use and unintended release. Specific topics will include environmental partitioning; environmentally-relevant transformation processes; the chemistry and effects of redox-active species; and the toxicity/detoxification of electrophilic species in the body. Skills in big data analysis and environmental modeling will be developed through an introduction to the R programming language at the beginner level.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('CHM317H1', 'Introduction to Instrumental Methods of Analysis', '24L/52P', 'Scope of instrumental analytical chemistry; Fourier transform IR absorption spectroscopy; molecular luminescence; emission spectroscopy; mass spectrometry; sensors; gas and high performance liquid chromatography; instrument design principles and applications in industry and the environment. (Lab Materials Fee: $39).', 'CHM391H5,  CHMC11H3,  CHMC16H3', 5, '{"operator": "AND", "items": ["CHM217H1", {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('CHM326H1', 'Introductory Quantum Mechanics and Spectroscopy', '24L/12T', 'This course introduces the postulates of quantum mechanics to develop the fundamental framework of quantum theory. A number of exactly soluble problems are treated in detail as examples. Perturbation theory is introduced in the context of understanding many body problems. Various applications to chemical bonding and molecular spectroscopy are covered in detail.', 'JCP321H5,  PHY356H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}, "CHM223H1", {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1"]}]}'::jsonb),
    ('CHM327H1', 'Experimental Physical Chemistry', '12L/52P', 'Students are introduced to physical chemistry laboratory work in a project-based approach in which they develop, design, and implement projects that address fundamental and applied questions in physical chemistry. The course also involves class material related to working as an experimental physical chemist. (Lab materials fee: $39).', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM220H1", "CHM222H1", "MSE202H1"]}, "CHM223H1"]}'::jsonb),
    ('CHM328H1', 'Modern Physical Chemistry', '24L/12T', 'This course explores the microscopic description of macroscopic phenomena in chemistry. Statistical mechanics is introduced as the bridge between the microscopic and macroscopic views, and applied to a variety of chemical problems including reaction dynamics. More advanced topics in thermodynamics are introduced and discussed as required.', 'JCP322H5,  CHMC20H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}, "CHM223H1", {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1"]}]}'::jsonb),
    ('CHM338H1', 'Intermediate Inorganic Chemistry', '24L/52P', 'Further study of the structures, physical properties, and reactions of transition metals. Introductions to spectroscopy, structural analysis, reaction mechanisms, d-block organometallic compounds, applications of metal, and main group compounds in catalysis. The weekly laboratory explores advanced synthetic and spectroscopic techniques including air- and moisture-sensitive chemistry and multinuclear NMR spectroscopy, with a strong emphasis on developing scientific communication skills. (Lab Materials Fee: $39).', 'CHM331H5', 5, '{"operator": "AND", "items": ["CHM236H1", "CHM237H1"]}'::jsonb),
    ('CHM342H1', 'Modern Organic Synthesis', '24L/12T', 'An overview of the preparation of various classes of organic compounds. Strategies and tactics of synthetic organic chemistry using examples from natural products and pharmaceuticals. C-C bond formation, functional group reactivity, structure, stereochemistry and selectivity.', 'CHM345H5', 5, '{"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}'::jsonb),
    ('CHM343H1', 'Organic Synthesis Techniques', '24L/52P', 'This laboratory course showcases modern organic synthesis techniques and introduces chemical research principles. It provides excellent preparation for a  CHM499Y1 project in organic chemistry. Associated classes teach theory and problem-solving approaches from a practical perspective and through industrial case studies. Green chemistry decision-making is a central theme of both the class and laboratory components. (Lab Materials Fee: $39).', 'CHM393H5', 5, '{"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}'::jsonb),
    ('CHM347H1', 'Organic Chemistry of Biological Compounds', '24L/12T', 'An organic chemical approach to the structure and reactions of major classes of biological molecules: carbohydrates, amino acids, peptides and proteins, phosphates, lipids, heterocycles, vitamins, nucleotides, and polynucleotides. This is achieved through studies of advanced stereochemistry, chemical modification, reactions, and synthesis. In addition to classes and reading from texts, there will be opportunities for independent written assignments on several of the topics.', 'CHM347H5,  CHMC47H3', 5, '{"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}'::jsonb),
    ('CHM348H1', 'Organic Reaction Mechanisms', '24L/26P', 'Principles and methods of analyzing and predicting organic chemical reactivity: advanced stereochemistry, conformational analysis, molecular orbitals, reaction kinetics, isotope effects, linear free energy relationships, orbital transformations, systematization of mechanisms. The laboratory section is used to illustrate the operation of the principles, including examples of data acquisition for mechanistic analysis and theoretical computations. Regular original reports on methods and outcomes are an important part of the laboratory. (Lab Materials Fee: $26).', 'CHM341H5,  CHMC41H3', 5, '{"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}'::jsonb),
    ('CHM355H1', 'Introduction to Inorganic and Polymer Materials Chemistry', '24L', 'Fashioned to illustrate how inorganic and polymer materials chemistry can be rationally used to synthesize superconductors, metals, semiconductors, ceramics, elastomers, thermoplastics, thermosets and polymer liquid crystals, with properties that can be tailored for applications in a range of advanced technologies. Coverage is fairly broad and is organized to crosscut many aspects of the field.', 'CHM325H1,  CHM426H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}, "CHM236H1", "CHM237H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}'::jsonb),
    ('CHM379H1', 'Biomolecular Chemistry', '24L/52P', 'This course provides an opportunity to learn core techniques in biological chemistry in a small group laboratory setting. It provides excellent preparation for a  CHM499Y1 project in biological chemistry or related areas. Classes will discuss the theory behind the techniques and highlight how they are used in modern biological chemistry research and practice. Note:  CHM379H1 can be used as the biochemistry lab requirement for students completing double majors in chemistry and biochemistry. (Lab Materials Fee: $39).', 'BCH370H1,  CHM371H5', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}, "CHM347H1", "BCH210H1"]}'::jsonb),
    ('CHM395Y1', 'Research Project in Chemistry', '180P', 'An independent research project conducted under the direction of a tenure stream or teaching stream faculty member in the Department of Chemistry or a closely-affiliated department. Applications are due to the Associate Chair Undergraduate during March (for Summer Session projects) and during July (for Fall/Winter Session projects): the application form is available at the Department of Chemistry website. Not eligible for CR/NCR option.', null, 5, '{"operator": "AND", "items": [{"credits": 2.0, "department": "CHM"}]}'::jsonb),
    ('CHM396Y0', 'Research Topic Abroad', null, 'Course credit for research or field studies abroad under the supervision of a faculty member. Not eligible for CR/NCR option.', null, 5, '{"operator": "AND", "items": [{"credits": 8.5, "department": null}, {"credits": 1.5, "department": "CHM"}]}'::jsonb),
    ('CHM397H0', 'Research Abroad in Chemistry', null, 'Independent research project in Chemistry under the supervision by a faculty member in an approved partner institution. This unique opportunity to conduct a lab-based research project is open to students in any Chemistry programs. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('CHM398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CHM398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CHM399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CHM410H1', 'Analytical Environmental Chemistry', '24L/44P', 'An analytical theory, instrumental, and methodology course focused on the measurement of pollutants in soil, water, air, and biological tissues and the determination of physical/chemical properties including vapour pressure, degradation rates, partitioning. Lab experiments involve application of theory. (Lab Materials Fee: $39).', null, 5, '{"operator": "AND", "items": ["CHM217H1", {"operator": "OR", "items": ["CHM210H1", "CHM310H1"]}]}'::jsonb),
    ('CHM414H1', 'Biosensors and Chemical Sensors', '24L', 'The development, design, and operation of biosensors and chemical sensors, including: biosensor technology, transducer theory and operation, device design and fabrication, surface modification and methods of surface analysis, flow injection analysis and chemometrics.', null, 5, '{"operator": "OR", "items": ["CHM217H1", "CHM220H1", "CHM222H1"]}'::jsonb),
    ('CHM415H1', 'Topics in Atmospheric Chemistry', '24L', 'Building upon the introductory understanding of atmospheric chemistry provided in  CHM210H1, this course develops a quantitative description of chemical processes in the atmosphere. Modern research topics in the field are discussed, such as aerosol chemistry and formation mechanisms, tropospheric organic chemistry, the chemistry of climate including cloud formation and geoengineering, biosphere-atmosphere interactions, and the chemistry of remote environments. Mathematical models of atmospheric chemistry are developed; reading is from the scientific literature; class discussion is emphasized.', null, 5, '{"operator": "AND", "items": ["CHM210H1"]}'::jsonb),
    ('CHM416H1', 'Separation Science', '24L', 'This course provides theoretical and practical background useful for engaging in cutting-edge chemical separations in chemistry, biology, medicine, engineering, research, and industry. The course covers general separations concepts and principles, with an emphasis on liquid chromatography and its various modes, including partition chromatography, ion chromatography, enantiomer chromatography, size exclusion chromatography, and affinity chromatography. Other topics include materials and instrumentation, gas chromatography, supercritical fluid chromatography, electrophoresis and related techniques, and a host of miscellaneous separation (e.g., TLC, FFF, CF) and extraction (e.g., LLE, SPE, SPME) modalities. Classes are supplemented with online/virtual laboratory exercises.', null, 5, '{"operator": "AND", "items": ["CHM317H1"]}'::jsonb),
    ('CHM417H1', 'Laboratory Instrumentation', '24L/12P', 'This course provides an introduction to building and using optics- and electronics-based instrumentation for laboratory research, as well as for implementing custom software control. Class topics include passive electronic components, diodes and transistors, operational amplifiers, analogue-to-digital conversion, light sources and detectors, reflectors, refractors, polarizers, diffractors, and many others. Classes are supplemented by laboratories in which students work in teams to build fluorescent detection systems for chromatography over the course of several weeks. (Lab Materials Fee: $26).', null, 5, null::jsonb),
    ('CHM423H1', 'Applications of Quantum Mechanics', '24L', 'Applications of time independent and time dependent perturbation theory to atomic and molecular problems, selection of topics from WKB approximation and the classical limit; the interaction of light with matter; elementary atomic scattering theory; molecular bonding.', null, 5, '{"operator": "AND", "items": ["CHM326H1"]}'::jsonb),
    ('CHM427H1', 'Statistical Mechanics', '24L', 'Ensemble theory in statistical mechanics. Applications, including imperfect gases and liquid theories. Introduction to non-equilibrium problems.', null, 5, '{"operator": "AND", "items": ["CHM326H1", "CHM328H1"]}'::jsonb),
    ('CHM432H1', 'Organometallic Chemistry and Catalysis', '24L', 'Structure, bonding, and reactions of organometallic compounds, with emphasis on basic mechanisms, and industrial processes. Addition, metalation, elimination, important catalytic cycles, electrophilic, and nucleophilic reactions are considered on a mechanistic basis. Topics on modern organometallic chemistry and catalysis are covered.', null, 5, '{"operator": "AND", "items": ["CHM338H1"]}'::jsonb),
    ('CHM437H1', 'Bioinorganic Chemistry', '24L', 'This course examines the use of metals in biology. Topics include naturally occurring and medicinal ligands; transport, uptake and control of concentration of metal ions; and physical methods of characterization of metal binding sites. The roles of metal ions in nature are discussed, including as structural and signaling elements in proteins, nucleic acids and DNA-binding complexes and proteins; as Lewis-acid centres in enzymes; as carriers of electrons, atoms and groups in redox proteins and enzymes; and as sources of biominerals; as radiopharmaceuticals.', 'CHM333H5,  CHMD69H3', 5, '{"operator": "AND", "items": ["CHM236H1", "CHM237H1"]}'::jsonb),
    ('CHM440H1', 'The Synthesis of Modern Pharmaceutical Agents', '24L', 'This course provides an overview of reactions and synthetic strategies that are being used at different stages of the drug development process. Using representative examples from the literature, we will concentrate on synthesis of complex heterocyclic compounds.', null, 5, '{"operator": "AND", "items": ["CHM342H1"]}'::jsonb),
    ('CHM441H1', 'Spectroscopic Analysis in Organic Chemistry', '24L/20P', 'Structure and stereochemistry determination using modern spectroscopic techniques. Several techniques are discussed but particular emphasis is given to NMR (1H and 13C NMR) and mass spectrometry. The approach taken emphasizes applications of these spectroscopic methods to organic problems. Students are trained to run their own spectra (IR, UV, NMR, GC-MS). (Lab Materials Fee: $26).', null, 5, '{"operator": "AND", "items": ["CHM249H1", "CHM343H1"]}'::jsonb),
    ('CHM443H1', 'Physical Organic Chemistry', '24L', 'Noncovalent binding forces, solutions, and molecular recognition. Electronic structure theory and computational techniques. Reaction mechanisms: experimental probes and reactive intermediates, including carbenes and radicals. Photophysics and photochemistry of organic compounds.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}, "CHM348H1"]}'::jsonb),
    ('CHM447H1', 'Bio-organic Chemistry', '24L', 'Mechanisms in biochemical systems: Examples of biological catalysis are considered in terms of chemical mechanisms and their extensions, overcoming barriers catalytic groups in active sites, stereochemical applications, energy transfer, kinetic patterns, inhibitors, drug design, cofactors, ribozymes, and proteosomes. Related current issues are noted and discussed. The format includes class material integrated with student discussions.', null, 5, '{"operator": "AND", "items": ["CHM347H1", "CHM348H1"]}'::jsonb),
    ('CHM455H1', 'Advanced Materials Chemistry', '24L', 'A comprehensive investigation of synthetic methods for preparing diverse classes of inorganic materials with properties intentionally tailored for a particular use. Begins with a primer on solid-state materials and electronic band description of solids followed by a survey of archetypical solids that have had a dramatic influence on the materials world, some new developments in materials chemistry and a look at perceived future developments in materials research and technology. Strategies for synthesizing many different classes of materials with intentionally designed structures and compositions, textures and morphologies are then explored in detail emphasizing how to control the relations between structure and property of materials and ultimately function and utility. A number of contemporary issues in materials research are critically evaluated to appreciate recent highlights in the field of materials chemistry - an emerging sub-discipline of chemistry.', 'CHM434H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM325H1", "CHM355H1"]}, "CHM338H1"]}'::jsonb),
    ('CHM456H1', 'Organic Materials Chemistry', '24L', 'This course covers design, synthesis, characterization and application of organic materials. Emphasis is placed on classic examples of organic materials including semiconducting polymers, molecular devices, self-assembled systems, and bioconjugates, as well as recent advances from the literature.', 'CHM446H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}, {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}'::jsonb),
    ('CHM457H1', 'Polymer Chemistry', '24L/12T', 'Scope of polymer chemistry. Classification of polymers. Synthesis and characterization. Polymers in solution. Thermodynamics of polymer solutions and blends, Flory-Huggins theory. Polymers in the solid state. Crystalline and amorphous polymers. Glass transition and melting temperature. Mechanical properties. Polymers as advanced materials.', 'CHM426H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}, {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}'::jsonb),
    ('CHM458H1', 'Soft Materials for Life, Energy, and the Environment', '24L', 'In the framework of a dry lab, students will analyze and interpret characterization data, extending their existing knowledge of chemical fundamentals and experimental techniques to polymeric systems. Through a combination of classes, dynamic group collaborations, and self-paced assignments, students will actively engage with peers to understand course materials (including published literature), explore how polymer innovations are commercialized, and develop a toolkit for leveraging instrumentation to investigate hypotheses in research.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM247H1", "CHM249H1", "MSE245H1"]}, {"operator": "OR", "items": ["CHM220H1", "CHM222H1", "CHM223H1", "APS110H1"]}]}'::jsonb),
    ('CHM479H1', 'Biological Chemistry', '24L', 'An in depth examination of biological systems at the molecular level. Several complex, multi-component molecular machines with a central role in life will be examined. For each system studied, the focus will be on understanding the chemical mechanisms that underlie the biological activities, and how these processes fit into a cellular context.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, "CHM347H1"]}'::jsonb),
    ('CHM499Y1', 'Introduction to Chemistry Research', '240P/16S', 'An experimental or theoretical research problem under the supervision of a tenure-stream or teaching stream faculty member in the Department of Chemistry or a closely-affiliated department. Five mandatory 90-minute professional development workshops cover aspects of academic writing, poster presentations, reading chemical literature, job applications/interviews, and science communication. Applications for enrolment should be made to the Departmental Undergraduate Office in the preceding Winter Session: the application form is available at the Department of Chemistry website. Only admitted students must contact faculty to discuss available research projects. Projects are typically offered in the areas of environmental, analytical, physical/theoretical, inorganic, materials/polymers, organic and biological chemistry. Not eligible for CR/NCR option.', 'CHM489Y5,  CHMD90Y3,  MSE498Y1,  PHC489Y1', 5, null::jsonb),
    ('CIN105Y1', 'Introduction to Film Study', '24L/24T/72P', 'Introduction to film form (including style and narration), different types of films, and popular approaches to the study of cinema. Topics include: narrative cinema, documentary, avant-garde, genre, authorship, ideology, and representation.', 'ENGB70H3,  ENGB75H3,  ENGB76H3,  CIN101H5', 1, null::jsonb),
    ('CIN196H1', 'Story Worlds and the Cinema', '24P/24S', 'Films create story worlds, imaginary environments in which characters live and act, and where events, large and small, transpire. Some story worlds are elaborate, fanciful constructs (think of Disney''s animated films). Others stay close to reality (think of "docudramas"). But across the spectrum, all of them are framed by and provided with rules of time and space, of believable or impossible. This course offers an examination of selected story worlds from several periods of film history. Emphasis falls on the expansive story worlds of contemporary corporately-run media-franchise "universes," like the cross-media "DC Universe." Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('CIN197H1', 'School Daze', '24P/24S', 'This first-year foundation course is a survey of sound film (with a brief selection of silent shorts) on the topic of how popular cinemas have represented going to school. Looking at one film and one scholarly text a week, the course will offer an introduction to the close reading of film texts, reading and writing film criticism, and the fundamentals of film history. By engaging with only one film/reading per week, the course emphasizes depth over breadth. Texts for the course may include excerpts from Corrigan''s A Short Guide to Writing About Film, Sturken and Cartwright''s Practices of Looking, Staiger''s Interpreting Films, and Prince''s Movies and Meaning, along with selected criticism on the movies screened. Those films may include Zero for Conduct, Aparajito, Tom Brown''s School Days, Tea and Sympathy, If, Rock and Roll High School, Mean Girls, School Daze, Blackboard Jungle, or Lady Bird. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('CIN201Y1', 'Film Cultures I: Art and Industry', '24L/24T/72P', 'Examines the practices, theories, and debates surrounding the emergence of cinema through to the development of studio system filmmaking in the first half of the 20th Century. Topics include: film''s relation to the other arts, formalist and realist traditions, technological innovations, audiences and reception, and cultural industries.', null, 2, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN210H1', 'Horror Film', '12L/12T/36P', 'Horror film as a genre, focusing on three types of international horror: the un-dead, body horror, and the supernatural. The genre''s popular appeal, affective power, unique means of producing pleasure, and current global resurgence will be emphasized. Topics include: the aesthetics of gore and violence, technologies of fear, J-Horror, new French extremity, cult fandom and paracinema, and media convergence.', null, 1, null::jsonb),
    ('CIN211H1', 'Science Fiction Film', '12T/36P', 'This course is the study of science fiction films in their cultural and political contexts and the genre''s narrative and conceptual components. The goal of the course is to familiarize students with science fiction films as popular genre texts, emphasizing the period between 1950 and the present.', null, 1, null::jsonb),
    ('CIN212H1', 'Cinema and Sensation I: Action/Spectacle', '12L/12T/36P', 'Action movies cement the dominance of commercial cinema, and they largely define the contemporary era of the blockbuster and CGI effects. This course examines the narrative modes and the extremes that action scenes reach, and it explores the commercial and social function of the genre. The course also traces Action''s historic reach and global diversity to include its significant precursors and transnational forms that Action cinema takes on.', null, 1, null::jsonb),
    ('CIN213H1', 'Cinema and Sensation II: Sex', '12L/12T/36P', 'Erotic images and sounds have long featured in filmic pleasure and, for just as long, excited controversy. This course examines how sex is articulated on screen and how its regulation suggests broader themes and ideas. Topics include: obscenity laws and the history of film censorship, the eroticized aspects of conventional movies, art cinema, and "adult" erotic films.', null, 1, null::jsonb),
    ('CIN214H1', 'New Media Forms', '36L/12T', 'Introduction to the study of new and contemporary media forms, with a focus on aesthetic and moving-image media. Students will learn key concepts in digital media studies through close examination of historical and contemporary examples from art, cinema, video, and games. Course readings draw on interdisciplinary critical models from cinema studies, cultural studies, art history, and digital media studies.', null, 1, null::jsonb),
    ('CIN215H1', 'Fantasy Film', '12L/12T/36P', 'This course examines the development of the Fantasy imagination in cinema from the start of film production (i.e., Georges Méliès) through the classical era (i.e., Wizard of Oz) to the contemporary proliferation of Fantasy cinema (i.e., Lord of the Rings, Snow White and the Huntsman). Course includes study of Asian, European, and South American Fantasy films.', null, 1, null::jsonb),
    ('CIN216H1', 'Crime Film Traditions', '12L/12T/36P', 'Originating in the mid-19th century from journalistic accounts and detective stories, crime fiction has emerged as one of the dominant popular genres in the 20th century across a variety of media and platforms, from true crime dime novels to radio dramas, from hard-boiled literature to prestige television series. Rejuvenated in the 21st century by the consolidation of gaming culture and the rise of podcasting, crime narratives have expanded to transmediality, stretching the boundaries between fiction and documentary practices. In this context, the culturally porous and generically elastic crime film had remained one of the most enduring cinematic expressions of sociopolitical anxieties related to class, gender, race, and ethnicity. This course examines a selection of crime film traditions across various geographical areas and historical periods, investigating the resilience of this form from the silent period to the present day.', null, 1, null::jsonb),
    ('CIN220H1', 'Special Topics in Cinematic Genres and Modes', '12L/12T/36P', 'Course on special topics in cinematic genres and modes. Topics vary each year.', null, 1, null::jsonb),
    ('CIN230H1', 'The Business of Film', '36L/12T', 'Examines cinema as a commercial enterprise, emphasizing production, distribution, and exhibition and the political economy of North American film culture.  This is a Breadth Category 3 course but has been specially-designed to fulfill the Quantitative Reasoning requirement for Cinema Studies Specialists and Majors.', null, 3, null::jsonb),
    ('CIN240H1', 'Special Topics in Cinema Studies', '12L/12T/36P', 'Course on special topics in Cinema Studies. Topics vary each year.', null, 3, null::jsonb),
    ('CIN250Y1', 'Directors: Four Studies in Film Authorship', '48L/48P', 'This course takes four selected directors'' films and examines them analytically and interpretively. The purpose of the course is to apply and test the auteur theory in the context of concepts of film style and film conventions.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN260H1', 'Selected Topics in Cinema Studies', '12L/12T/36P', 'Course on selected topics in Cinema Studies. Past topics include: "New Media."', null, 1, null::jsonb),
    ('CIN270Y1', 'American Popular Film Since 1970', '48L/24T/48P', 'The examination of popular American cinema through its social, political, and commercial practices, and through the study of selected popular films from the 1970s to the present.', null, 3, null::jsonb),
    ('CIN301Y1', 'Film Cultures II: Politics and Global Media', '24L/24T/72S', 'Examines film theory and practice from the 1950s onward, and the impact of media change on earlier film cultures and aesthetics. Topics include: New Wave cinemas, the politicization of theory, spectatorship, counter-cinemas, transnational film and "Global Hollywood", and media theory from the analog to the digital.', null, 2, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN310Y1', 'Avant-Garde and Experimental Film', '48L/72P', 'Avant-garde films, both canonical and marginal, are examined mainly in the context of modern art and poetry from the 1920s through the 1990s. Films include works from Europe, North America, and Japan. Art contexts range from Cubism, Dada, and Surrealism in the 1920s to Neo-Dada, Abstract Expressionism, Pop, and Postmodernism.', 'ENGD91H3,  CIN402H5', 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN312Y1', 'Documentary Film', '48L/48P', 'Critical and historical survey of documentary practice, including cinema verité, ethnographic experiments, and various hybrid forms, with emphasis on the rhetorical, aesthetic, and political dimensions of the "art of record." Topics include: the filmmaker/subject/audience nexus; historiography, hagiography, and performance; and how emerging technology and new media platforms, evinced in the rise of documentary-based webdocs, i-docs, and webgames, affect the actual production and style of linear documentary, as well as impact earlier models of documentary exhibition, distribution, and viewer engagement alike.', 'ENGD94H3', 3, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN314Y1', 'Genre, Narrative and Narration in Film', '48L/72P', 'Study of theoretical-analytical models of film genres, narrative form, and narration. Structuralist, cognitive-neoformalist, and historiographical approaches will be developed. Genres to be studied include: Westerns, musicals, crime films, biography films, gothic and fantastic films, and art cinema.', null, 2, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN315H1', 'Sound and Animation', '24L/24P', 'This course aims to unsettle the privileging of the visual and of live action cinema in film and media studies. The founding impetus of the class is to counter the marginalization of two intertwined issues – animation and sound – in cinema studies. This course takes seriously the suggestion of various scholars that animation is central rather than peripheral to film history and the rise of digital media.  The course aims to give students a working knowledge of key concepts at the intersection of animation, sound, and music, while also surveying a range of historical, national, and transnational contexts. The class considers feature-length titles from Hollywood and Japan as major nodes in the global circulation of cartoons and anime; at the same time, it de-centers these major players by also exploring short, experimental, and independent animation work in a transnational vein. This eclecticism is paralleled by a variety of approaches to sound and animation covered in the class, from more theoretical, philosophical, or formalist discourses to perspectives that foreground history and ideology, and considerations grounded in the materiality of media, production contexts, or industrial circulation. Throughout, the class is attuned to the cultural and political work that animated sound films do in negotiating dynamics of race, gender and sexuality.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN320H1', 'Special Topics in Genre and Modes', '24L/24P', 'Courses in special topics designed for Specialists and Majors in Cinema Studies. Past topics include: "Contemporary Screen Comedy," and "Eco-cinema: The Nature of Film."', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN321H1', 'Special Topics in Genre and Modes II', '24L/24P', 'Courses in special topics designed for Specialists and Majors in Cinema Studies.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN322H1', 'Cult Cinema', '24L/24P', 'This course examines "cult" and "exploitation" cinema. It examines the growing popularity of cult/exploitation films as an emerging cinematic subculture that valorizes disreputable or "trash" cinema. A number of sub-genres within exploitation film, including teen films, educational/instructional films, sexploitation, and Blaxploitation, will be explored. The social politics of appropriating texts through ironic reading strategies will also be considered.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN330Y1', 'Feminist Approaches to Cinema', '48L/48P', 'Gender politics of feminist film culture since the 1970s. Topics include: apparatus theory and its legacy, models of spectatorship, feminist historiography, the cinematic (re)production of identity, the relationship between social movements and cinema, "postfeminism."', null, 2, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN332Y1', 'Screening Race', '48L/48P', 'How race functions in cinema. Topics include: the foundational role of racial inscription and its expansion beyond the black/white paradigm, visual ethnography, ''the primitive,'' and Orientalism, indigenous media, the ''Black Atlantic'' and Diaspora, Banlieu and exilic film practice and theory, border aesthetics, race and urban space, ''post-race'', and the evolving racial imaginary.', 'FLMB80H3', 2, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN334H1', 'The Origins of the Animation Industry, 1900-1950: A Technosocial History', '24L/36P', 'An introduction to early animation, considering its vaudeville roots, industrialization, emerging aesthetics, and representational tropes. Examination of the early corpus of animation from 1900-1950, and in-depth study of the artistic, social, and cultural milieux from which animation derived.', null, 1, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN335H1', 'Animation after 1950', '24L/36P', 'This course examines the second fifty years of animation, first by marking Disney''s shifting fortunes, then broadening the scope to take in its competitors here and abroad. The global nature of postwar animation has been an odd amalgam of competition and cooperation, of private and public funding, and of film, television, and eventually webcasting, and we will explore some of the changes the form has gone through in the past fifty years or so. Since this is a study of art and of commerce, and of high and low culture, we will view our limited history through the lenses of aesthetics, cultural practices, business decisions, and sometimes political struggle.', null, 1, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN336H1', 'Queer Film and Media', '48L', 'This course focuses on queer film, television, and/or digital media. Approaches may include cultural, historical, analytical, critical, and theoretical methods. This course may focus on the representation of queer people in film in media, or film and/or media made by queer people, or both.', null, 1, '{"operator": "OR", "items": ["CIN105Y1", "SDS255H1", "SDS256H1", "SDS279H1", "SDS355H1"]}'::jsonb),
    ('CIN337H1', 'Black Cinema', '24L/24P', 'This course explores the cultural, aesthetic, technological, and political category of “Black cinema.” Across the diaspora, Black cinema is an artistic praxis that utilizes techniques like improvisation and collaboration in order to make and remake the cinematic archive. The films and filmmakers in this category intervene in cinematic histories by responding to exclusionary narratives, technologies, and critical discourse by imagining alternative stories, spaces, and temporalities. Thus, these films help articulate both the pervasiveness of anti-blackness in our visual culture and help us understand the difference (film) aesthetics can make (Chun, 2019). Our goal is to 1) develop a critical language to discuss Black cinema (its techniques, its aims, and its political contexts) and 2) articulate research questions, methods, and arguments that consider what is happening inside and outside the frame in these films.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN338H1', 'Environmental Media', '24L/24P', 'This course is interested in exploring the many relationships between media and the environment. We not only analyze the representations of environmentality in film, photography, video games, and digital media, but also the material entanglements of media technologies and infrastructures with environment—broadly defined. Adopting conceptual approaches in elemental, infrastructural, and architectural media studies, we seek to uncover and politicize media’s troubled relationship with environmentality.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN339H1', 'Adult Film Histories', '24L/24P', 'From the birth of cinema and the legal emergence of “hardcore” to the rise of the internet, adult ﬁlm covers a broad span of periods, genres, geographies, venues, and technical formats: stag and grindhouse ﬁlms, peepshows, sexploitation ﬁlms, avant-garde cinema, “Golden Age” pornography, video, animation, adult theatres, and digital contexts. This course oﬀers a critical and historical survey of adult ﬁlms in social, legal, technical, and political contexts of production, consumption, and circulation. The course balances global and U.S. perspectives with attention to entanglements of race, class, gender, sexuality, feminism, and labor. Course content augmented by guest lectures from the adult industry.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN340H1', 'Special Topics in Cinema as Social and Cultural Practice', '24L/24P', 'Courses in special topics designed for Specialists and Majors in Cinema Studies. Past topics include: "History of Cinematography," and "Everyday Life in the Digital Age."', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN341H1', 'Special Topics in Cinema as Social and Cultural Practice II', '24L/24P', 'Courses in special topics designed for Specialists and Majors in Cinema Studies.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN349H1', 'Screenwriting', '24S', 'Students will develop screenwriting skills under the guidance of a renowned Canadian screenwriter through a combination of writing workshops and individual consultations. Like the course, the appointment of the Universal Screenwriter-in-Residence occurs biannually.  Prospective students must submit an application form that will be found at Cinema Studies Institute Undergraduate Forms and provide a creative writing sample to the Cinema Studies Undergraduate Office by email to cinema.studies@utoronto.ca by April 30. A screenplay (or excerpt) is preferred, but a submission that the students feel best expresses their talent is also acceptable. The course instructor and/or Undergraduate Coordinator will assess student potential based on the writing samples to determine student eligibility to enrol in the course. Enrolment priority will be given to upper year Cinema Studies program students.', 'VIC276H1,  CRE276H1', 1, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1", {"credits": 2.0, "department": "CIN"}]}'::jsonb),
    ('CIN352H1', 'Issues in Film Authorship I', '24L/24P', 'Advanced study of issues in film authorship through intensive examination of one or more major filmmakers.', 'ENGD52H3,  CIN206H5', 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN353H1', 'Issues in Film Authorship II', '24L/24P', 'Advanced study of issues in film authorship through intensive examination of one or more major filmmakers.', 'ENGD52H3,  CIN206H5', 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN360H1', 'Special Topics in Theory and Criticism', '24L/24P', 'Courses in special topics designed for Specialists and Majors in Cinema Studies. Past topics include: "Cinema and Intermediality."', null, 2, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN361H1', 'Special Topics in Theory and Criticism II', '24L/24P', 'Courses in special topics designed for Specialists and Majors in Cinema Studies.', null, 2, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN362H1', 'Animals and Cinema', '24L/24P', 'This course explores cinema’s century-long fascination with animals. Its investigations are organized around three central questions. First, what does cinema teach us about animals (why and how we look at animals on film, how we represent and understand animals through film, and what lessons we hope to gain from animals on film)? Second, what do animal films reveal or teach us about the cinema? Third, what are the aesthetic, theoretical, and ethical stakes of such encounters between animals and cinema?', null, 2, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN363H1', 'Ecocinema: The Nature of Film', '24L/24P', 'This course takes a broad approach to the growing field – sometimes termed “ecocinema” or “film ecology” – devoted to cinema’s relationship to the natural environment. We will consider that relationship through a combination of historical, textual, and theoretical analysis.', null, 1, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN364H1', 'Theories of Media', '48L', 'In-depth history of humanistic theories of media and mediation, with a focus on aesthetics. Authors discussed may include Karl Marx, Walter Benjamin, Sigmund Freud, Marshall McLuhan, Friedrich Kittler, Donna Haraway, Bernard Stiegler, Katherine Hayles, and others. Includes substantial discussion of contemporary problems and authors in digital media studies and media theory. Includes extensive consideration of aesthetic forms, including animation, cinema, television, installation art, video games, net.art, and others.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN365H1', 'Nonfiction Video Practice', '24L/24P', 'This course is designed to introduce students to the basics of creative video production, with an emphasis on documentary and nonfiction film and video. Students will be introduced to the theory and practice of documentary filmmaking, including the creative, ethical, conceptual, and practical dimensions of artistic moving-image production. This is a hands-on course that will include off-site practical workshops and in-course group critique. Students are expected to have some prior technical knowledge of video recording and video editing, as technical skill-building will fall outside the purview of this course. We will explore the diverse approaches adopted by nonfiction filmmakers and video artists in order to consider what constitutes a cinematic practice. Students will work on creative assignments individually and in groups, coming up with conceptual ideas, creative treatments, and artistic methods for translating their ideas and questions into non-fiction moving image media.', null, 1, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN366H1', 'Durable Empires and Medias of Mass Culture', '24L/24P', 'Taking a deliberately broad view of “empire” to include formations of power under colonialism, nationalism, neoliberalism, and more, we seek to understand how visible and invisible structures of power define our world through cinematic and mediated forms. In particular, we are interested in how hegemony (and resistance) articulates with medias of mass culture. How do mass media such as cinema, television, the internet, and big data represent, disseminate, intercept, and/or resist imperial formations?', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN369H1', 'Critical Writing on Film', '48L', 'The practice of film criticism: studies of examples of journalistic and scholarly critical writing, practical sessions of process writing, and collaborative editing. Course includes regular film screenings. This course is offered biannually. Prospective students must submit an application form that will be found at Cinema Studies Institute Undergraduate Forms and provide a brief (one to two paragraphs) explanation of why they would like to take  CIN369H1 to the Cinema Studies Undergraduate Office by email to cinema.studies@utoronto.ca by April 30. The course instructor and/or Undergraduate Coordinator will assess the applications to determine student eligibility to enrol in the course: prerequisites, program of study, and experience. Enrolment priority will be given to upper year Cinema Studies program students.', 'ENGB71H3', 1, '{"operator": "AND", "items": ["CIN105Y1", {"credits": 1.0, "department": "CIN"}]}'::jsonb),
    ('CIN370H1', 'Canadian Cinemas', '24L/24P', 'History and diversity of Canadian and Québécois cinemas. Analyses of film and critical frameworks examine how co-productions, multiculturalism, and post-national arguments are re-shaping the production and reception contexts of national cinema. Annual emphasis will be placed on one of the following topics: the emergence of the feature film, Québécois cinema, documentary, or experimental cinema.', 'FCS391H1', 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN371H1', '(New) Media Aesthetics', '48L', 'Investigates the theory and history of media technologies as sites of aesthetic investment in a wide variety of artistic practices, focusing on contemporary digital media work, including experimental cinema, gallery installation, net.art, and avant-garde videogames. One important emphasis lies in the aesthetic possibilities new (and newly inexpensive) media technologies have made available to marginalized artists, including especially women and queer artists. We will study the work of Maya Deren, John Cage, Tony Conrad, Yoko Ono, Jack Smith, Andy Warhol, Michael Snow, Marina Abramovic, Marlon Riggs, Felix Gonzales-Torres, Anna Anthropy, and others.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN372Y1', 'Contemporary World Cinema', '48L/72P', 'Major contemporary developments beyond Hollywood and European filmmaking, examining a select number of national/regional cinemas: Africa, Korea, Iran, India (Hindi cinema), and Latin America. Topics include: transnationalism, indigenization of generic and stylistic conventions, cultural contexts, distribution networks, film festivals, and reception within a global economy.', 'ENGC83H3', 3, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN374Y1', 'American Filmmaking in the Studio Era', '24L/24T/72P', 'Industrial, economic, ideological, and aesthetic dimensions of the American studio era.', null, 3, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN376Y0', 'Chinese Cinemas', null, 'Examination of Chinese films in their three post-World War II production centres: The People''s Republic of China, Taiwan, and Hong Kong. Includes study of Shanghai films of the 1930s and 1940s. Commercial, political, and aesthetic trends; international reception; major auteurs and genres (including melodrama, wuxia pian and crime films). Directors include Tsui Hark, Chen Kaige, Zang Yimou, John Woo, Wong Kar-Wai, Hou Hsiao-hsien, and Feng Xiaogang. This course is offered through the Summer Abroad program.', 'CIN376Y1', 3, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN376Y1', 'Chinese Cinemas', '48L/72P', 'Examination of Chinese films in their three post-World War II production centres: The People''s Republic of China, Taiwan, and Hong Kong. Commercial, political, and aesthetic trends; international reception; major auteurs and genres. Directors include Tsui Hark, Chen Kaige, Zang Yimou, Edward Yang, John Woo, and Wong Kar-Wai.', 'CIN376Y0', 3, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN378H1', 'Aspects of a National Cinema', '24L/24P', 'In-depth treatment of a national cinema. Past courses include: "British Cinema," "Australian and New Zealand Cinema," and "The Other Europe."', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN378Y0', 'Aspects of a National Cinema', null, 'This course offers a critical study of British film cultures, with an emphasis on British film genres, movements and cycles from the 1960s to the present day. Earlier representative works, to include the British documentary movement, will provide a foundation for a comparative study of contemporary British cinema. Major and minor film cultures will be studied in their institutional, social, and cultural contexts to include: the long standing tradition of British realism; the Free Cinema Movement; the “New Wave;” “Swinging London;” “Thatcherite” cinema, including its heritage, art cinema, Brit-grit and Black British iterations; in addition to the recent “lad boy” underclass cycle that reconfigures the traditional conceptualization of British cinema as strictly oppositional “realism or tinsel.” Debates pertinent to the way in which British films and relate to a shifting sense of national identity, towards examining the “Englishness” of British national cinema, will be highlighted. This course is offered through the Summer Abroad program.', null, 1, null::jsonb),
    ('CIN379H1', 'Hungarian Cinema', '24L/24P', 'Examines historical trends, influential filmmakers, and social and cultural factors influencing the development of Hungarian cinema, assessing its impact within the context of Eastern Europe and internationally.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN380H1', 'Special Topics in History and Nation', '24P/24S', 'Courses in special topics designed for Specialists and Majors in Cinema Studies.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN381H1', 'Special Topics in History and Nation II', '24L/24P', 'Courses in special topics designed for Specialists and Majors in Cinema Studies.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN381Y1', 'Special Topics in History and Nation', '48P/48S', 'Courses in special topics designed for Specialists and Majors in Cinema Studies.', null, 1, '{"operator": "AND", "items": ["CIN105Y1"]}'::jsonb),
    ('CIN410H1', 'Advanced Study in Genre and Modes', '24P/24S', 'Consideration of the status of a selected film genre or mode from historical and theoretical perspectives. Past seminars include: “Film Comedy,” “Melodrama,” “Film Noir,” “The End in Cinema,” and “The Musical.” Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN411H1', 'Advanced Study in Genre and Modes', '24P/24S', 'Consideration of the status of a selected film genre or mode from historical and theoretical perspectives. Past seminars include: “Film Comedy,” “Melodrama,” “Film Noir,” “The End in Cinema,” and “The Musical.” Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN412H1', 'Advanced Study in Genre and Modes', '24P/24S', 'Consideration of the status of a selected film genre or mode from historical and theoretical perspectives. Past seminars include: “Film Comedy,” “Melodrama,” “Film Noir,” “The End in Cinema,” and “The Musical.” Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN420H1', 'Advanced Studies in Cinema', '24P/24S', 'Seminars in special topics designed for advanced Specialist and Major students in Cinema Studies. Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN430H1', 'Advanced Study in Cinema as Social and Cultural Practice', '24P/24S', 'Consideration of cinema and its social relations. Past seminars include: “American Independent Film,” “Children in the Movies,” “Sub-Saharan African Cinema,” “International Film Festivals,” “Interactive Documentary,” “Graphic!," "The Revolution Will/Will Not Be Televised," "Social Problem Films," and "Programming and Curation." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN431H1', 'Advanced Study in Cinema as Social and Cultural Practice', '24P/24S', 'Consideration of cinema and its social relations. Past seminars include: “American Independent Film,” “Children in the Movies,” “Sub-Saharan African Cinema,” “International Film Festivals,” “Interactive Documentary,” “Graphic!," "The Revolution Will/Will Not Be Televised," "Social Problem Films," and "Programming and Curation." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN432H1', 'Advanced Study in Cinema as Social and Cultural Practice', '24P/24S', 'Consideration of cinema and its social relations. Past seminars include: “American Independent Film,” “Children in the Movies,” “Sub-Saharan African Cinema,” “International Film Festivals,” “Interactive Documentary,” “Graphic!," "The Revolution Will/Will Not Be Televised," "Social Problem Films," and "Programming and Curation." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN433Y1', 'Sensory Ecologies: Theory and Praxis in Environmental Media Studies', '48P/48S', 'Practitioners of environmental filmmaking struggle with a fundamental challenge: how to represent the dimensionality, and immersivity of the so-called natural world within the flat space and linear temporalities of the cinematic medium. These challenges resonate with larger questions about loss, extinction, and degradation; one cannot capture what is now disappeared, elusive, or destroyed. What then, should the role of media be amid a period of environmental ruination? This experiential learning course seeks to investigate these questions, and more. Through a combination of praxis and theory, students will collaborate with community partners on a series of applied learning outcomes. Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": ["CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN440H1', 'Advanced Studies in Cinema', '24P/24S', 'Seminars in special topics designed for advanced Specialist and Major students in Cinema Studies. Past seminars include: "Experiential Learning." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN450H1', 'Advanced Study in Theory and Criticism', '24P/24S', 'Advanced study of select approaches to film theory and criticism. Past seminars include: “Corporeality and the Cinema,” “The Cinematic City: Urban Spaces in Film,” “Sound and Music in Film,” “Expanded Cinema,” “Digital Cinema,” and "Cinema and Architecture: Scenes, Screens, Studios." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN451H1', 'Advanced Study in Theory and Criticism', '24P/24S', 'Advanced study of select approaches to film theory and criticism. Past seminars include: “Corporeality and the Cinema,” “The Cinematic City: Urban Spaces in Film,” “Sound and Music in Film,” “Expanded Cinema,” “Digital Cinema,” and "Cinema and Architecture: Scenes, Screens, Studios." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN452H1', 'Advanced Study in Theory and Criticism', '24P/24S', 'Advanced study of select approaches to film theory and criticism. Past seminars include: “Corporeality and the Cinema,” “The Cinematic City: Urban Spaces in Film,” “Sound and Music in Film,” “Expanded Cinema,” “Digital Cinema,” and "Cinema and Architecture: Scenes, Screens, Studios." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN460H1', 'Advanced Studies in Cinema', '24P/24S', 'Seminars in special topics designed for advanced Specialist and Major students in Cinema Studies. Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN461H1', 'Advanced Study in Cinema and Media Practice', '24L/24P', 'This seminar uses research creation, critical making, digital humanities, videographic criticism, or other practice-based methods to the humanistic study of cinema and moving-image media, at an advanced level. Students will pursue advanced research projects grounded in these approaches. Topics and methods vary by semester and instructor. This seminar is designed for advanced Specialist and Major students in Cinema Studies, but it does not presume prior practice-based knowledge. Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in the Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN470H1', 'Advanced Study in History and Nation', '24P/24S', 'Seminars in historiography and questions of national cinema. Past seminars include: “Film Historiography,” “Early Cinema,” “Reviewing Hollywood Classicism,” “Women Pioneers,” “Local Film Cultures: Toronto Sites and Scenes,” and "Debating Transnational Cinema." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN471H1', 'Advanced Study in History and Nation', '24P/24S', 'Seminars in historiography and questions of national cinema. Past seminars include: “Film Historiography,” “Early Cinema,” “Reviewing Hollywood Classicism,” “Women Pioneers,” “Local Film Cultures: Toronto Sites and Scenes,” and "Debating Transnational Cinema." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
    ('CIN472H1', 'Advanced Study in History and Nation', '24P/24S', 'Seminars in historiography and questions of national cinema. Past seminars include: “Film Historiography,” “Early Cinema,” “Reviewing Hollywood Classicism,” “Women Pioneers,” “Local Film Cultures: Toronto Sites and Scenes,” and "Debating Transnational Cinema." Pre-enrolment balloting for 400-Level seminars will start in late May to early June, opening roughly five weeks before the July enrolment period begins. More information on balloting procedures, the balloting form and the submission deadline can be found in Cinema Studies Undergraduate Forms.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1"]}'::jsonb),
