    ('CIN490Y1', 'Independent Studies in Cinema', null, 'Independent research projects devised by students and supervised by Cinema Studies faculty. Open to advanced Specialist and Major students in the Program. Submit applications to the Cinema Studies Undergraduate Office prior to requesting enrolment: Fall term courses, June 1/ Winter term courses, November 1/ Summer term courses, April 1. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1", "CIN301Y1"]}'::jsonb),
    ('CIN491H1', 'Independent Studies in Cinema', null, 'Independent research projects devised by students and supervised by Cinema Studies faculty. Open to advanced Specialist and Major students in the Program. Submit applications to the Cinema Studies Undergraduate Office prior to requesting enrolment: Fall term courses, June 1/ Winter term courses, November 1/ Summer term courses, April 1. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1", "CIN301Y1"]}'::jsonb),
    ('CIN492H1', 'Independent Studies in Cinema', null, 'Independent research projects devised by students and supervised by Cinema Studies faculty. Open to advanced Specialist and Major students in the Program. Submit applications to the Cinema Studies Undergraduate Office prior to requesting enrolment: Fall term courses, June 1/ Winter term courses, November 1/ Summer term courses, April 1. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "CIN105Y1", "CIN201Y1", "CIN301Y1"]}'::jsonb),
    ('CJH332H1', 'Cellular and Molecular Neurobiology of the Synapse', '36L', 'Examination of all aspects of the synapse in both the peripheral and central nervous systems of invertebrates and vertebrates. Topics include: neuroplasticity, synapse formation, synaptic transmission, synaptic modulation, and the molecular biological basis of neurodegenerative disorders.', 'CSB332H1', 4, '{"operator": "OR", "items": ["BIO271H1", "PSL300H1"]}'::jsonb),
    ('CJS200H1', 'Introduction to Jewish Thought', '24L', 'A balanced presentation of the multifaceted approach to the discipline by treating Jewish religion and thought.  The course introduces students not only to a chronological and thematic overview of the subject, but also to different methodological approaches.', null, 2, null::jsonb),
    ('CJS201H1', 'Introduction to Jewish Cultures', '24S', 'General introduction to history, literatures and cultures of Jewish people from antiquity to contemporary. A balanced presentation of multi-disciplinary approaches and multi-methodological approaches to Jewish studies, with a special emphasis on Jewish cultural studies and Jewish secularity.', null, 1, null::jsonb),
    ('CJS205H1', 'People of the Books: The Classics of Jewish Literature', '24L', 'This course introduces some of the most influential and evocative books of the Jewish tradition. Students will explore how these books reflect central themes of Jewish history and questions about Judaism, Jewish life, and Jewish identity. Possible texts include excerpts from the Bible, Midrash, Talmud, Zohar and Lurianic kabbalah, Maimonides'' Mishneh Torah and responsa, the poetry and trickster tales of the Takhkemoni, the autobiographies of Leon of Modena and Solomon Maimon, the travelogues of Haim Azulai and Hayyim Habshush, and the tales of Rabbi Nachman of Bratslav. This course will delve into the historical contexts of each of the books and analyze both how they reflect the concerns of the particular communities that produced them and how they helped to shape future Jewish communities worldwide. Through close reading and discussion, participants will gain insight into the Jewish literary heritage. All readings will be given in English.', null, 3, null::jsonb),
    ('CJS207H1', 'The Jewish Life Cycle', '24L', 'This course introduces the events and rituals that demarcate key moments in Jewish lives including birth, coming-of-age, marriage, and death. Through close textual analysis, we will explore the historical development of Jewish life cycle rituals and how they sometimes shifted in meaning over time. We will explore these rituals as they developed among Jewish communities living in both the Christian and Islamic worlds. Special attention will be paid to how these rituals reflect attitudes towards gender and how they have been shaped in response to the presence of the majority non-Jewish culture, so as to adapt and adopt attractive ideas and respond to the threats and temptations the majority culture posed. By the end of the course, students will have developed a rich understanding of the diversity within Jewish traditions and the complex interplay between ritual and interpersonal religious law, and between individual, familial and communal forms of religious practice.', null, 3, null::jsonb),
    ('CJS220H1', 'The Holocaust in Fiction', '24S', 'The course examines literary works written in different languages, in ghettos and concentration camps during the Holocaust, as well as those reflecting on the genocide in its aftermath. We focus on literature as a means of engaging with the unimaginable and on the cross analysis of eye-witness and memory writing.', null, 1, null::jsonb),
    ('CJS230H1', 'God, Nation, and Self Transformed: The Secularization of the Jewish Experience', '24S', 'The course provides a theoretical background to the issue of secularization and examines the diverse attempts to define on a secular basis the Jew, the Jewish nation, and the Jewish God since the breakdown of traditional Jewish society. A variety of Jewish secularisms are examined in a larger, non-Jewish context.', null, 2, null::jsonb),
    ('CJS290H1', 'Topics in Jewish Studies', '24L/24T', 'An examination of issues in Jewish Studies. Content in any given year depends on instructor.', null, null, null::jsonb),
    ('CJS301H1', 'Community', '24L', 'Ethno-religious groups like Jewry or the Jews are not merely aggregates of individuals but rather collectives whose members are bound to each other in a common historical identity, life, and fate. To understand any such group, we must therefore understand what binds these people together into a community, why the burdens and benefits or responsibilities and resources of the community are distributed among its members as they are, and both how and how well internal conflicts are managed. This course considers the ways in which the Jewish community -- in its local and global guises -- has reflected upon and dealt with these issues in classical and contemporary contexts.', null, 2, null::jsonb),
    ('CJS320H1', 'Jews in the Modern World', '24L', 'Jews of all sorts today are the product of historical processes that have changed the place of religion in their lives, their intellectual and moral outlook, their political standing and aspirations, their social relations and opportunities, and their means and modes of culture expression. In this course, we will try to understand the forces and counterforces as well as the decisions and reactions that determine ways of being Jews in the modern world.', null, 2, null::jsonb),
    ('CJS325H1', 'Authority in Judaism', '24L', 'Why should Jews obey God''s commands? Does Judaism understand the relation of God''s rule over His people to the sovereign''s rule over his? Why and to what extent do Jews respect the decisions of rabbis, and how do the rabbis enforce their decision when their power to coerce compliance is limited? What force do prophetic criticisms of the people''s religious and moral failings have? All of these are question of authority discussed in Judaism until today, and we will explore them together in this course.', null, 2, null::jsonb),
    ('CJS330H1', 'Who''s a Jew? Theory, Myth, and Practice', '24L', 'This course introduces students to the host of core concepts in terms of which Jewish identity has been and continues to be defined and debated. Topics include: the difference between insiders and outsiders; collective vs individual identity; the nature of the bond between group members; identification across time, space, and disagreements; social and gendered hierarchies; joining and leaving the group; the identities of outsiders.', 'CJS290H1 (Topics in Jewish Studies: Who is a Jew?), offered in Fall 2014 and Fall 2015', 2, null::jsonb),
    ('CJS331H1', 'Encounters between Jewish and Modern Thought', '24L', 'A detailed exploration of how Jewish thought develops in relationship to key figures or moments in modern European philosophy (e.g., Spinoza, Kant, Hegel, Kierkegaard, Marx, Nietzsche, Heidegger). The particular focus varies from year to year.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CJS340H1', 'Mizrahim in Israel: History, Politics, and Culture', '24L', 'What is the significance of the designation “Mizrahi” in Israel today? Does it refer to people who share a common geographical and ethnic origin or does it indicate a shared worldview that draws upon Middle Eastern Arabic culture? What are its relations with other terms, such as “Sephardi,” “Oriental,” or “Levantine”? What kind of political membership does it entail? Does it possess a certain cultural, religious, or political vocabulary? And, ultimately, does the diasporic concept of “Mizrahiyut” (mizrahiness) undermine national homogeneity or rather facilitate and enable its enforcement?', 'CJS390H1 (Special Topics in Jewish Studies: Mizrahim in Israel: History, Politics, and Culture), offered in Summer 2017', 3, null::jsonb),
    ('CJS383H1', 'Jews and Power', '24L', 'This course will explore the relationship of Jews to political power. Among the themes to be covered are: How has the relationship of the Jewish community to political authority changed over time? What is the Jewish conception of political authority? How did Jews protect their communal and individual rights in the absence of sovereignty? How did the dynamics of antisemitism, philosemitism, and anti-Jewish violence change over time? How did Zionism and the revival of Jewish sovereignty change the position of Jews in the political order? What are the political and moral dilemmas posed by statehood? And what are the implications of Jewish sovereignty for Jews in the Diaspora?', 'POL383H1', 3, '{"operator": "OR", "items": ["POL101Y1", "CJS200H1", "CJS201H1"]}'::jsonb),
    ('CJS389H1', 'Jewish Secularism and Messianic Thought: From Spinoza to Derrida', '24S', 'This course examines the critical role that Messianic thought plays in the emergence of modern Jewish secular thought. A study of the secular dimension of Messianism in the writings of Jewish philosophers, from Spinoza to Derrida, leading to the larger question of its place in the project of Jewish modernity.', null, 2, null::jsonb),
    ('CJS390H1', 'Special Topics in Jewish Studies', '24L', 'An examination of issues in Jewish Studies. Content in any given year depends on instructor.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CJS391H1', 'Special Topics in Jewish Studies', '24L', 'An examination of issues in Jewish Studies. Content in any given year depends on instructor.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CJS392H1', 'Special Topics in Jewish Studies', '24L', 'An examination of issues in Jewish Studies. Content in any given year depends on instructor.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CJS396H1', 'Independent Study', null, 'A scholarly project on an approved topic supervised by a faculty affiliated with the Centre for Jewish Studies. For details, please visit the ATCJS webpage on Independent Studies Courses. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CJS200H1", "CJS201H1"]}]}'::jsonb),
    ('CJS400H1', 'Research Seminar in Jewish Studies', '24S', 'An interdisciplinary seminar in which Jewish Studies topics are explored intensively, culminating in a major research paper by each student. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CJS200H1", "CJS201H1"]}]}'::jsonb),
    ('CJS401H1', 'Identity & Conflict', '24L', 'A well-known saying "two Jews, three opinions" captures succinctly just how ubiquitous conflicts and disagreements are in Jewish life. These contestations are indeed not only common but also deep: they run all the way down to very foundations of Jewish identity, to questions of who belongs to and who should be excluded from the community. This course looks at some historical and current conflicts that have fundamentally divided Jew from Jew as well as various responses to such conflicts from within the Jewish tradition, asking why some conflicts are managed successfully while others aren''t and how the answer to that question might be applicable within the groups to which we each belong. Not eligible for CR/NCR option.', 'CJS401Y1', 2, '{"operator": "OR", "items": ["CJS200H1", {"operator": "AND", "items": ["CJS201H1", {"credits": 1.0, "department": null}]}]}'::jsonb),
    ('CJS440H1', 'The Arab Jew: A History of a Concept', '24L', 'This course invites students to explore the debates around the term “Arab Jews.” A cultural, historical, and historiographical designation, the term encompasses a range of experiences for Arabic-speaking Jews. These Jews lived in diverse cultural worlds across the Middle East and North Africa, where they developed deep and enduring relationships with non-Jews, and were instrumental in shaping local, regional and national cultures and politics. By engaging with the term “Arab Jews” in its various incarnations, the course offers new perspectives on questions of Zionism and nationalism, colonialism and geography, religion and secularization, as well as historiography and memory.', 'CJS491H1 (Advanced Topics in Jewish Studies: The Arab Jew: A History of a Concept), offered in Winter 2017', 1, null::jsonb),
    ('CJS444H1', 'Topics in the Study of Antisemitism', '24L', 'This seminar explores in depth one of the many theoretical or methodological issues that confront scholars of antisemitism. Possible topics include: definitions of antisemitism and their purposes; philosemitism and its conceptual and real connection with antisemitism; Jewish self-hatred; contextualist vs eternalist accounts of antisemitism; classic and contemporary theories of antisemitism.', null, 2, null::jsonb),
    ('CJS490H1', 'Advanced Topics in Jewish Studies', '24S', 'An in-depth investigation of topics in Jewish Studies. Content in any given year depends on instructor.', null, null, null::jsonb),
    ('CJS491H1', 'Advanced Topics in Jewish Studies', '24S', 'An in-depth investigation of topics in Jewish Studies. Content in any given year depends on instructor.', null, null, null::jsonb),
    ('CJS498Y1', 'Independent Study', null, 'A scholarly project on an approved topic supervised by a faculty affiliated with the Centre for Jewish Studies. For details, please visit the ATCJS webpage on Independent Studies Courses. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CJS200H1", "CJS201H1"]}]}'::jsonb),
    ('CJS499H1', 'Independent Study', null, 'A scholarly project on an approved topic supervised by a faculty affiliated with the Centre for Jewish Studies. For details, please visit the ATCJS webpage on Independent Studies Courses. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CJS200H1", "CJS201H1"]}]}'::jsonb),
    ('CLA160H1', 'Introduction to Classical Studies', '36L/10T', 'An introduction to major themes in the development of Greek and Roman civilization, literature and culture.', null, 1, null::jsonb),
    ('CLA170H1', 'Ancient Texts, Modern Worlds', '36L/10T', 'An introduction to Greek and Latin literature and culture which highlights the theoretical issues involved in the translation and reception of ancient texts. It introduces key works of literature, questions what it means to talk about an "original" text, asks what makes for an "accurate" translation, and sharpens awareness of linguistic issues even for students without Latin and Greek.', null, 1, null::jsonb),
    ('CLA195H1', 'Julius Caesar', '24S', 'Gaius Julius Caesar (100 – 44 BC) was a writer, an orator, a reformer, and a builder, as well as a general, a conqueror, an explorer, and a dictator. After his death, he was even worshipped as a god with a temple in the very heart of Rome. According to his critics, both ancient and modern, he was also a megalomaniac, an enemy of the state, a war criminal, and a tyrant. Only a very few individuals have left such an extensive and controversial mark on the history of the ancient world. We shall consider as many aspects of his life and his legacy as we can, from his conquest of Gaul to his decision to plunge Rome into a horrific civil war, from his love-affair with Queen Cleopatra of Egypt to his brutal assassination on the Ides of March. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('CLA196H1', 'Unhappy Families', '24S', 'Unhappy families appear throughout Greco-Roman literature and culture. Spectacular Tragic Houses were filled with several generations of disasters. These inspired a variety of poets to retell select moments in their histories. But even the comic household can mobilize hatred, suspicion, and other ugly feelings to humorous effect. Conflict between domineering fathers and the rest of the household was a staple of rhetorical training. And in many homes we can see the misery of slaves, members who are also not members of the family. This course will survey a variety of intimate disasters. We will explore norms and ideals as well as the sense that the same are fragile, contradictory, or even impossible. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('CLA197H1', 'Inventing the Ancient Mediterranean: Roman Technology', '24S', 'Two thousand years ago Roman hydraulic engineers designed aqueducts and provided hundreds of cities in the Mediterranean region with a richer water supply than any nation could boast before the late 1800s. Ever more sophisticated ships transported goods from harbour to harbour and Roman experts on construction built the Colosseum and other amphitheatres, as well as countless temples, theatres, roads, bridges, and even high-rise apartment buildings, which in some cases survive to this very day. What was the secret of Roman civilization, and what did this level of technology mean for the empire''s inhabitants? This course presents for discussion the many achievements of centuries of Roman presence on three continents around the Mediterranean Sea, while bringing into the equation also the issue of standard of living and the ecological costs. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('CLA198H1', 'Homer''s Odyssey down through Time', '24S', 'This course will survey creative works inspired by Homer''s Odyssey. First we will read through the Odyssey, contextualizing the Homeric epic within the larger story of the Trojan War and the subsequent heroic return in the "Epic Cycle." Then we will study various "receptions" of the Odyssey, ancient and modern. Ancient works will include the satyr play Cyclops by Euripides and portrayals of a love-sick Cyclops in Theocritus and Ovid. In True Story Lucian calls Odysseus a liar but rivals his travel tale with episodes placed on the moon and inside a whale. Modern works include Atwood''s Penelopiad, Walcott''s stage version of the Odyssey, and the film "O Brother, Where Art Thou?" Themes will include travel literature, truth and lying, localization of the wanderings of Odysseus, culture clash, and the definition of home. All this material, various in date, media, and fidelity to their Homeric source, will provide us with a well-rounded sense of how the Odyssey has been re-imagined over the ages. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('CLA199H1', 'The “Decline and Fall” of the Roman Empire', '24S', 'After a high water mark of territorial reach and economic success in the middle of the 2nd century CE, the Roman Empire eventually disintegrated. How? Why? When? In this course, we will consider some of the historical features that may have contributed to its political collapse, and we will consider some modern scholarly analyses from Edward Gibbon (late 18th century) to the present. But we will also investigate "decline and fall" as a narrative trope. Why is this story arc always with us? Who decides what qualifies as "decline"? Is the "fall" of some systems necessarily a bad thing? Among the topics to be considered in the context of the Later Roman Empire are several of relevance in the modern world, not least: climate change, disease, human migration, religious difference, and economic inequality. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('CLA201H1', 'Latin & Greek in Scientific Terminology', '36L', 'The study of technical and scientific terms derived from Latin and Greek: word elements, formation, analysis. The course is designed to give students in any field of specialization a better grasp of the derivation and basic meaning of English words derived from Latin and Greek elements.', null, 2, null::jsonb),
    ('CLA203H1', 'Science in Antiquity', '36L', 'The first scientific traditions in the classical Mediterranean and the Near East, with emphasis on Greek science. Discussions of early physical science, biology, mathematics, and astronomy, and their place in ancient life and thought, based on primary sources in translation. Designed for students in both the sciences and humanities.', null, 2, null::jsonb),
    ('CLA204H1', 'Introduction to Classical Mythology', '36L', 'A survey of the myths and legends of ancient Greece (and their extension to Rome) with some consideration of their role in ancient and modern literature and art.', null, 2, null::jsonb),
    ('CLA208H1', 'Socrates and His World', '36L', 'Already in antiquity, Socrates was viewed as a watershed in philosophical history, and a reference-point for everything that came after him. This course explores the evidence for his beliefs and methods and the context in which he lived and worked, and it introduces a lively circle of interlocutors and pupils going far beyond the most famous, Plato and Xenophon.', null, 2, null::jsonb),
    ('CLA209H1', 'Magic, Religion, and Science', '36L', 'A study of the overlapping and contested categories of "magic", "religion", and "science" in ancient Greek and Roman thought and practice.', null, 2, null::jsonb),
    ('CLA210H1', 'Greek and Roman Archaeology', '36L', 'A survey of the practices and theory of archaeology in the Classical Mediterranean, from the Greek Bronze Age through the Roman Empire. This course introduces students to the archaeological record of the Greco-Roman past, as well as the means by which we access it. Students will develop essential skills to recognize and analyze ancient material culture in preparation for upper level classes, or for fieldwork. No previous knowledge of the discipline is required.', null, 3, null::jsonb),
    ('CLA215H1', 'Classical Warfare', '36L', 'An introduction to the military history of ancient Greece and Rome from the 8th century BCE to the 7th century CE, with an emphasis on the political, social and economic implications of warfare and military institutions.', null, 3, null::jsonb),
    ('CLA217H1', 'Marginal Identities in the Ancient Mediterranean', '36L', 'An exploration of the groups and individuals who could be considered "marginal" in Greek and Roman antiquity. Includes discussion of ancient ideas about race, ethnicity, social status, economic class, gender, sexuality, and disability.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLA219H1', 'Women in Antiquity', '36L', 'A survey of the position of women in ancient Greece and Rome, with focus on women''s sexuality and socialization; their economic, religious, and political roles; and their creative production in the arts.', null, 3, null::jsonb),
    ('CLA222H1', 'Sex, Death, and Poetry', '36L', 'A study of the themes of sex and death and the connection between them in the poetry of ancient Greece and Rome. Readings will be drawn from Greek and Roman lyric, epic, tragedy, and other genres.', null, 1, null::jsonb),
    ('CLA223H1', 'Literature and Empire', '36L', 'A study of the relation between literature and empire in ancient Greece and Rome. The course covers a variety of genres and historical moments, examining how literature can support or challenge imperial power.', null, 1, null::jsonb),
    ('CLA224H1', 'Letters from the Past', '36L', 'A study of letters and letter writing in Greek and Roman Antiquity. Students will be introduced to ancient theories of epistolography and a wide variety of texts, including letters by famous historical figures, philosophical letters, poetic letters, and fictional letters in prose.', null, 1, null::jsonb),
    ('CLA230H1', 'Introduction to Greek History', '36L', 'A historical survey of the most significant features in the development of the civilization and states of ancient Greece from the Bronze Age to the second century B.C.E.', null, 3, null::jsonb),
    ('CLA231H1', 'Introduction to Roman History', '36L', 'A historical survey of the most significant features in the development of the civilization and state of ancient Rome from the mythical beginnings to the fourth century C.E.', null, 3, null::jsonb),
    ('CLA236H1', 'Greek and Roman Epic', '36L', 'A study of one or more of the epic poems of Greek and Roman antiquity (e. g. The Iliad and Odyssey of Homer and the Aeneid of Virgil).', null, 1, null::jsonb),
    ('CLA260H1', 'Method and Theory in Classics', '36L', 'An introduction to key issues in methodology and theory in the study of the classical world.', null, null, null::jsonb),
    ('CLA299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CLA299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CLA303H1', 'The Ancient Novel', '36S', 'An introduction to the Greek romances of love and adventure (Chariton, Longus, Heliodorus), and the more ironical and socially conscious works of the Roman writers Petronius and Apuleius.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA204H1", "CLA219H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA232H1", "CLA233H1", "CLA236H1", "CLA260H1"]}]}'::jsonb),
    ('CLA305H1', 'Theories of Myth', '36S', 'A detailed study of the major modern approaches to the analysis and interpretation of myth with specific reference to their applications to ancient Graeco-Roman myth.', null, 2, '{"operator": "AND", "items": ["CLA204H1", {"operator": "OR", "items": ["CLA160H1", "CLA170H1", "CLA260H1"]}]}'::jsonb),
    ('CLA308H1', 'Religion in the Greek World', '36S', 'A study of the religious cults and forms of worship in the ancient Greek world.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA204H1", "CLA208H1", "CLA209H1", "CLA210H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA230H1", "CLA232H1", "CLA236H1", "CLA260H1"]}]}'::jsonb),
    ('CLA310H1', 'Religion in the Roman World', '36S', 'A study of the religious cults and forms of worship in the Roman world, including the pagan cults, Judaism, and early Christianity.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA204H1", "CLA208H1", "CLA209H1", "CLA210H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA231H1", "CLA233H1", "CLA236H1", "CLA260H1"]}]}'::jsonb),
    ('CLA312H1', 'Persons and Passions', '36L', 'Ancient Greek and Roman thought about the emotions and the relationship that individuals have, or ought to have, with them. Primary sources in translation drawn from ancient literary, medical and philosophical texts.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA208H1", "CLA209H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA230H1", "CLA231H1", "CLA232H1", "CLA233H1", "CLA260H1", "PHL200Y1"]}]}'::jsonb),
    ('CLA314H1', 'Slavery in the Ancient Mediterranean World', '36S', 'A study of slavery and slave systems in ancient Greek and Roman societies.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA215H1", "CLA217H1", "CLA219H1", "CLA230H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA315H1', 'Insider-Outsiders: Being Greek in the Roman Empire', '36L', 'This course looks at Greek culture in the Roman imperial context. Topics include the Second Sophistic; the creation of canons and the idea of the "Classics"; alterity; the rise of Christianity; cultural loss and nostalgia; the fiction of Greece as a site of cultural capital and prestige. Authors including Pausanias, Philostratus, Plutarch, Aristides, Galen, and Lucian are read in translation.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA222H1", "CLA223H1", "CLA224H1", "CLA230H1", "CLA231H1", "CLA232H1", "CLA233H1", "CLA260H1"]}]}'::jsonb),
    ('CLA317H1', 'Greek and Roman Colonialism', '36L', 'An exploration of the motivations and consequences of colonial movements and foundations throughout classical antiquity, and the role of race and ethnicity in ancient structures of colonial power. Includes consideration of their influence on later colonial and imperial projects and reactions to them.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA217H1", "CLA230H1", "CLA231H1", "CLA232H1", "CLA233H1", "CLA260H1"]}]}'::jsonb),
    ('CLA319H1', 'Sexuality and Gender in Classical Literature', '36S', 'Detailed study of the representation of sexuality and gender in Greek and/or Roman literary texts from one or more genres.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA219H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA232H1", "CLA233H1", "CLA260H1"]}]}'::jsonb),
    ('CLA321H1', 'Sport and Festival', '36S', 'An examination of various aspects of athletic competition in the ancient Greco-Roman world, employing literary and archaeological evidence.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA230H1", "CLA231H1", "CLA232H1", "CLA233H1", "CLA236H1", "CLA260H1"]}]}'::jsonb),
    ('CLA322H1', 'Classical Reception', '36S', 'Modern reception of the classical world in a variety of media, such as art, literature, music, popular culture, etc.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA204H1", "CLA219H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA230H1", "CLA231H1", "CLA232H1", "CLA233H1", "CLA236H1", "CLA260H1"]}]}'::jsonb),
    ('CLA323H1', 'Ancient Philosophy and Literature', '36S', 'A study of some of the ways in which ancient Greek and Roman philosophy was itself a literary endeavour, and its relations to other kinds of ancient literature.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA203H1", "CLA204H1", "CLA208H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA232H1", "CLA233H1", "CLA236H1", "CLA260H1"]}]}'::jsonb),
    ('CLA336H1', 'Law in Ancient Greek and Roman Society', '36S', 'A study of legal sources and systems in ancient Greek and/or Roman states with particular attention to social and historical context.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA215H1", "CLA219H1", "CLA230H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA362H1', 'Early Greece', '36S', 'The Greek world from the second millennium B.C.E. to the emergence of the polis', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA230H1", "CLA260H1"]}]}'::jsonb),
    ('CLA363H1', 'Archaic and Classical Greece', '36S', 'The Greek world from the eighth to the fourth centuries B.C.E., with an emphasis on political events and development.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA230H1", "CLA260H1"]}]}'::jsonb),
    ('CLA364H1', 'The Hellenistic World', '36S', 'The Greek world in the age of Alexander the Great and his successors (336 B.C.E. to 31 B.C.E.)', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA230H1", "CLA260H1"]}]}'::jsonb),
    ('CLA367H1', 'The Roman Republic', '36S', 'The Roman world from 510 B.C.E. to 44 B.C.E.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA368H1', 'Augustus and the Julio-Claudians', '36S', 'The Roman world in the age of Augustus and his dynasty (44 B.C.E. to 68 C.E.)', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA369H1', 'The Roman Empire', '36S', 'The Roman world from 68 C.E. to 378 C.E.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA372H1', 'The Economic History of the Classical World', '36S', 'The structure and performance of economies in the Greek and/or Roman worlds, and their modern interpretation.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA230H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA373H1', 'The Environment in the Greco-Roman World', '36S', 'An exploration of the ecology and environment of the ancient Mediterranean basin in classical antiquity.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA230H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA378H1', 'Late Antiquity', '36S', 'The history and culture of the Greco-Roman world during the fourth through seventh centuries C.E., with particular emphasis on the decline of the Roman state and emergence of Christianity.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA382H1', 'Tragedy', '36S', 'The study of classical tragedy as a literary genre, dramatic production, and social institution, with analysis of representative plays.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA204H1", "CLA219H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA230H1", "CLA232H1", "CLA236H1", "CLA260H1"]}]}'::jsonb),
    ('CLA383H1', 'Comedy', '36S', 'The origin and development of Greek and Roman comedy, based on a study of representative plays.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA219H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA230H1", "CLA231H1", "CLA232H1", "CLA233H1", "CLA236H1", "CLA260H1"]}]}'::jsonb),
    ('CLA387H1', 'Spectacle in the Roman World', '36S', 'The role in Roman society and culture of public spectacles, including the chariot-races, the gladiatorial games, executions, and triumphal processions.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA231H1", "CLA233H1", "CLA260H1"]}]}'::jsonb),
    ('CLA388H1', 'Classical Antiquity and the Cinema', '36S', 'A study of the representation of ancient Greece and/ or Rome in cinema.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA219H1", "CLA222H1", "CLA223H1", "CLA224H1", "CLA232H1", "CLA233H1", "CLA260H1", "CIN105Y1"]}]}'::jsonb),
    ('CLA389H1', 'Classical Spaces: Sites and Monuments', '36S', 'A close study of one or more sites in the ancient world and the cultural significance of the site(s) in question.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CLA160H1", "CLA170H1"]}, {"operator": "OR", "items": ["CLA210H1", "CLA230H1", "CLA231H1", "CLA260H1"]}]}'::jsonb),
    ('CLA392H1', 'Topics in the study of Classical Culture and Society', '36S', 'Topics vary from year to year.', null, 1, '{"operator": "AND", "items": ["CLA160H1", {"operator": "OR", "items": ["CLA210H1", "CLA219H1", "CLA230H1", "CLA231H1", "CLA232H1", "CLA233H1", "CLA260H1"]}]}'::jsonb),
    ('CLA398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CLA398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
