    ('CLA399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
