    ('CLA402H1', 'Advanced Seminar in Greek Civilization', '36S', 'An advanced research seminar devoted to critical issues relating to Greek civilization. Course requirements include a research essay. Topics vary from year to year.', 'CLA403H1', null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": "CLA"}]}'::jsonb),
    ('CLA403H1', 'Advanced Seminar in Roman Civilization', '36S', 'An advanced research seminar devoted to critical issues relating to Roman civilization. Course requirements include a research essay. Topics vary from year to year.', 'CLA402H1', null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": "CLA"}]}'::jsonb),
    ('CLT110H1', 'Celtic Mythology and Saga', '24L', 'The medieval Celtic nations were home to one of the richest imaginative literary traditions of Western Europe. This course will introduce students to the literature from medieval Ireland and Wales that portrayed both the adventures of the Celtic gods and goddesses, and heroic ''saga'', by which is meant the exploits of Ireland''s and Britain''s prehistoric heroes. The course will also trace continuities in the storytelling of medieval Ireland and Wales with the culture of the Continental Celts of Antiquity, and will include examination of the role of literacy and the advent of Christianity on the islands'' native mythologies. The course assumes no prior familiarity with Celtic literature and history and all texts will be read in English translation.', 'CLT250H1,  SMC250Y1,  SMC250H1', 2, null::jsonb),
    ('CLT141Y1', 'Introduction to the Irish Language', '48L/24T', 'This course in Modern Irish Language is designed for learners with no prior knowledge of the language. The course is intended to introduce students to and provide practice in the four language skills: listening, speaking, reading and writing.', 'SMC141Y1', 1, null::jsonb),
    ('CLT240H1', 'The Celts in the Ancient and Medieval World', '24L', 'An introduction to the culture and literature of the Celtic peoples in pre-history and in the Middle Ages.', 'SMC240Y1,  SMC240H1', 1, null::jsonb),
    ('CLT241H1', 'The Celts in the Modern World', '24L', 'An introduction to the culture and literature of the modern Celtic nations from 1600 to the present.', 'SMC240Y1,  SMC241H1', 1, null::jsonb),
    ('CLT242Y1', 'An Introduction to Scottish Gaelic', '48L/24T', 'An introduction to Scottish Gaelic language and culture. Students will master fundamentals of reading, writing, and the basics of grammar and will begin to speak Gaelic. Proverbs, poetry, songs and folktales introduce students to the language, literature and folklore of Gaelic Scotland and immigrant North America. No prior knowledge of the language is required.', 'SMC242Y1', 1, null::jsonb),
    ('CLT243Y1', 'Modern Welsh', '48L/24T', 'An introductory course intended to provide a basic speaking and reading knowledge of Modern Welsh. Open to students with no prior experience of Welsh.', 'SMC243Y1', 1, null::jsonb),
    ('CLT244H1', 'Lowland Scots Language and Literature', '24L/12T', 'An introduction to Lowland Scots language and literature. Students will acquire fundamentals of reading, writing, grammar and spoken Scots. Poetry, songs and folktales introduce students to the language, literature and folklore of the Scots language, from the Renaissance poets through to Burns, MacDiarmid and modern artists. No prior knowledge of the language is required.', null, 1, null::jsonb),
    ('CLT251H1', 'Intermediate Irish Language I', '24L/12T', 'This course builds on  CLT141Y1 Introduction to the Irish Language. It will provide further expansion of the four language skills: listening, speaking, reading and writing.', 'SMC251H1', 1, '{"operator": "AND", "items": ["CLT141Y1"]}'::jsonb),
    ('CLT252H1', 'Intermediate Irish Language II', '24L/12T', 'This course is a continuation of  CLT251H1 Intermediate Irish Language I. It will provide further expansion of language skills. We will examine literary texts, both prose and poetry.', 'SMC252H1', 1, '{"operator": "AND", "items": ["CLT251H1"]}'::jsonb),
    ('CLT331H1', 'Advanced Irish Language I', '24L/12T', 'An advanced course in the Irish language, this builds on the speaking, listening, reading and writing competencies developed in  CLT251H1 and  CLT252H1 (Intermediate Irish Language I and II).', 'SMC333H1 (Special Topics in Celtic Studies I: Advanced Irish Language), offered in Fall 2018,  SMC331H1', 1, '{"operator": "AND", "items": ["CLT251H1", "CLT252H1"]}'::jsonb),
    ('CLT332H1', 'Advanced Irish Language II', '24L/12T', 'An advanced course in the Irish language, this builds on the speaking, listening, reading and writing competencies developed in  CLT331H1 (Advanced Irish Language I).', 'SMC333H1 (Special Topics in Celtic Studies I: Advanced Irish Language), offered in Fall 2018,  SMC332H1', 1, '{"operator": "AND", "items": ["CLT331H1"]}'::jsonb),
    ('CLT333H1', 'Special Topics in Celtic Studies I', '24S', 'Various topics are taken up each year, the content of which depends on the instructor. Students should check the college web site for details.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT336H1', 'Sport in Ireland', '24L', 'Sport in Ireland is a course designed to investigate the role sport has had since the inception of the Irish Free State in 1922 up until the present day. The course aims to explore the position of sport at a regional level in Ireland as well as the differences existing between certain sporting organizations at a regional and national level. The course will also determine sport''s contribution to the identity of Ireland in its first one hundred years as a nation state.', 'CLT333H1 (Special Topics in Celtic Studies I: Sport in Ireland), offered in Fall 2022', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT337H1', 'Early Celtic History 450-1000', '24L', 'The history of the insular Celtic nation groups from the post-Roman period to the end of the first millennium, the course will trace settlement history and social organization, the making of Celtic nations, the process of Christianization, the impact of the Vikings, and the rise of paramount kings.', 'SMC337H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT338H1', 'The Celtic Nations in the Later Middle Ages 1000-1550', '24L', 'Later medieval development of Ireland, Scotland and Wales: development of kingship, trade and urban settlement, arrival and colonizing patterns of the Normans, role of English administration and aggression, resurgence of native elites, development of frontier zones, beginning of the more complete English conquest of Ireland and Wales', 'SMC338H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT339H1', 'Northern Ireland:  The Troubles 1968-1998', '24L', 'This course examines the conflict between Protestants and Catholics in Northern Ireland between the civil rights movement of 1968 and the peace settlement of 1998, with special reference to colonial legacies, ethno-religious hostilities, loyalist and nationalist ideologies, guerrilla warfare, state security and civil liberty, and the peace process.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT340H1', 'Ireland Transformed, 1948-2020', '24L', 'In 1948, Ireland was a rural, socially conservative, deeply religious and economically impoverished country. Today, it is an urban, socially progressive, secular and wealthy society – and one that is experiencing new sets of problems. This course examines how and why these changes came about, the nature of contemporary Ireland, and the challenges that lie ahead.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT341H1', 'Global Irish Diaspora', '24L', 'Over 70 million people in the world can claim Irish descent. Since the 17th century, Irish people have voluntarily migrated and have been forcibly transported to a variety of global destinations. This course explores the "push and pull" factors that prompted these migrations and focuses on the diasporic communities created by Irish Catholics and Protestants in Great Britain, Canada, the United States, Continental Europe, the Caribbean, Argentina, South Africa, India, Australia, and New Zealand.', 'SMC341H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT345H1', 'Writing Ireland', '24L', 'This course looks at some of the major literary figures of Ireland in the twentieth and twenty-first centuries, writing in both Irish and English. Authors examined may include W. B. Yeats, Patrick Pearse, Nuala Ní Dhomhnaill, Seán Ó Riordáin, Seamus Heaney and Claire Keegan. Through a close reading of poetry, prose and critical texts, students will examine how Ireland''s past, present and future are variously figured in its greatest modern literature. All Irish-language works will be read in English translation.', 'SMC345H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT346H1', 'Celtic Folklore', '24L', 'This course examines the relationship between folklore and national identity in Ireland, Scotland and Wales, with special emphasis on storytelling traditions.', 'SMC346H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT347H1', 'Traditional Music in Ireland and Scotland', '24L', 'From Medieval harp playing to the emergence of reels and jigs during the eighteenth century, this course explores the changes and continuities in traditional music, and its place in contemporary culture.', 'SMC347H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT348H1', 'Early Modern Ireland', '24L', 'This course focuses on Irish history from the early seventeenth century to the Great Famine of the mid nineteenth century. Topics include the Ulster plantation, Catholic resistance, the Penal Laws, the United Irishmen, the Act of Union, Catholic Emancipation and the Famine.', 'SMC348H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT350H1', 'Celtic Spirituality', '24L', 'The religious culture of the early and mediaeval Celtic Church as manifested in the material and written record, and its significance for contemporary religious movements. Texts studied include the Patrician dossier, early monastic Rules and Liturgies, selected hagiographical, homiletic, devotional and lyric texts.', 'SMC350H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT353H1', 'The Scottish Witch-Hunt in its European Contexts', '24L', 'This course will explore various aspects of witchcraft accusations in Scotland and place them within the European context. A major focus of the course will be exploring the questions that historians have raised about the European witch-hunts and how this has influenced the historiography of the Scottish witch-hunts. The course will also involve several different kinds of primary sources and include discussions of their value and limitations.', null, 1, null::jsonb),
    ('CLT374H1', 'The Celtic Book', '24L', 'A study of the production of manuscripts, books and tracts that played a crucial role in the historical evolution of a national culture or cultures in the Celtic world.', 'SMC374H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT378H1', 'Ireland Since the Famine', '24L', 'This course examines the relationship between nationalism and unionism in post-Famine Ireland, with particular emphasis on the debates over Home Rule, the Irish Revolution and Civil War of 1916-23, the effects of partition, and the Troubles in Northern Ireland.', 'SMC378H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CLT395Y1', 'Independent Study in Celtic Studies', null, 'A research project chosen by the student in consultation with a faculty supervisor and approved by the Program Coordinator. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Not eligible for CR/NCR option.', 'CLT396H1', null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 1.0, "department": "CLT"}]}'::jsonb),
    ('CLT396H1', 'Independent Study in Celtic Studies', null, 'A research project chosen by the student in consultation with a faculty supervisor and approved by the Program Coordinator. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Not eligible for CR/NCR option.', 'CLT395Y1', null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 1.0, "department": "CLT"}]}'::jsonb),
    ('CLT411H1', 'Advanced Topics in Celtic Studies I', '24S', 'Various topics are taken up each year, the content of which depends on the instructor. Students should check the St. Michael''s College website for details.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CLT413H1', 'The Irish in Canada', '24S', 'This course explores the history of Irish migration and settlement in Canada with a special emphasis on political, social, economic and religious themes.', 'SMC413H1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CLT418H1', 'Romantic Scotland', '24L', 'This course provides an in-depth exploration of the origins and development of Romantic constructions of Scotland – its history, culture, language, and landscape – in literature, theatre, music, historiography, and art. The course will focus in particular on the Romantic movement in Scotland and its relationship to European Romanticism and nationalism. It will also explore the enduring legacy of that movement in more contemporary representations of Scottish identity (both within and outside of its national borders) in the arts and in political discourse. Offered in alternate years.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CLT420H1', 'Ireland, Race and Empires', '24S', 'This course examines the extent to which the Irish can be understood as a colonized and racialized people, and the degree to which they participated in the colonization and racialization of Blacks and Indigenous peoples in the British and American empires. It encompasses debates about whether the Irish were victims of genocidal policies during the Famine, and their role in what one historian calls the “casual genocide” of imperial expansion. It also discusses the character and limitations of anti-colonialism in Irish nationalist discourse, and attitudes of racialized minorities and Indigenous peoples towards the Irish. This course is jointly offered with the graduate course, HIS1441H.', 'CLT411H1 ("Ireland, Race & Empires", offered in Fall 2022)', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CLT440H1', 'Middle Welsh', '24L', 'Middle Welsh, the native Celtic language of medieval Wales, was for centuries the language in which the Welsh celebrated their medieval princes and ancestral heroes, was the medium for the preservation of native British legend and Welsh law, and was the vehicle for the earliest narratives of Arthur. Students will be introduced to reading and translating Middle Welsh, and by the course''s end will have read one complete text of Middle Welsh literature in the original. Students will learn Welsh specifically but will also learn the characteristic linguistic features of a Celtic language. No prior knowledge of Welsh or any other Celtic language is assumed.', 'SMC440Y1,  SMC440H1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CLT441H1', 'Introduction to Old Irish', '24L', 'This course will introduce students to Old Irish, the language of Western Europe''s earliest vernacular literature. The course will focus on bringing students to a reading knowledge of Classical Old Irish, drawing on the most recent teaching aids and incorporating translation exercises and prepared reading passages from the early literature. The course will also teach the linguistic vocabulary for describing a Celtic language. No prior knowledge of Irish is assumed.', 'SMC441Y1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CLT451Y1', 'Senior Essay in Celtic Studies', null, 'A scholarly project chosen by the student in consultation with a faculty supervisor and approved by the Program Coordinator. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "CLT"}]}'::jsonb),
    ('COG250Y1', 'Introduction to Cognitive Science', '78L', 'An introduction to the problems, theories and research [strategies central to the interdisciplinary field focusing on the nature and organization of the human mind and other cognitive systems. Interrelations among the philosophical, psychological, linguistic and computer science aspects of the field are emphasized.', null, 2, null::jsonb),
    ('COG260H1', 'Data, Computation, and the Mind', '24L/12P', 'How does the human mind work? We explore this question by analyzing a range of data concerning such topics as human rationality and irrationality, human memory, how objects are represented in the mind, and the relation of language and cognition. This class provides critical thinking and practical computational skills that will allow students to work with data in cognitive science and related disciplines.', null, 5, '{"operator": "OR", "items": ["CSC108H1", "CSC148H1"]}'::jsonb),
    ('COG341H1', 'Issues in Cognitive Science I: Attention, Perception, and Consciousness', '36L', 'An examination of core topics in cognitive science building on introductions in  COG250Y1. Typical topics include: perception and attention; concepts; imagery; consciousness.', null, 2, '{"operator": "AND", "items": ["COG250Y1", {"operator": "OR", "items": ["PSY270H1", "PHL342H1"]}]}'::jsonb),
    ('COG342H1', 'Issues in Cognitive Science II: Concepts, Theories of Mind, and Cognitive Evolution', '36L', 'An examination of core topics in cognitive science building on introductions in  COG250Y1. Typical topics include: concepts; theories of mind; cognitive evolution.', null, 2, '{"operator": "AND", "items": ["COG250Y1", {"operator": "OR", "items": ["PSY270H1", "PHL342H1"]}]}'::jsonb),
    ('COG343H1', 'Issues in Cognitive Science III: Computational Cognition', '24L/12P', 'An examination of core topics in cognitive science building on introductions in  COG250Y1. Typical topics include: computational models of cognition and learning, natural language processing, computer intelligence.', null, 5, '{"operator": "AND", "items": ["COG260H1", "CSC148H1", {"operator": "OR", "items": ["STA220H1", "PSY201H1"]}]}'::jsonb),
    ('COG344H1', 'Issues in Cognitive Science IV: Language and Communication', '36L', 'An examination of core topics in cognitive science building on introductions in  COG250Y1. Typical topics include: language and cognition; language acquisition; theories of meaning; pragmatics.', null, 2, '{"operator": "AND", "items": ["COG250Y1", {"operator": "OR", "items": ["LIN232H1", "LIN241H1", "JLP315H1", "JLP374H1"]}]}'::jsonb),
    ('COG345H1', 'Issues in Cognitive Science V: Cognitive Science and Society', '36L', 'An examination of core topics in cognitive science building on introductions in  COG250Y1. Topics include central moral, social, and political questions both relevant to and raised by cognitive science research.', null, 3, '{"operator": "AND", "items": ["COG250Y1", {"operator": "OR", "items": ["PSY270H1", "PHL342H1"]}]}'::jsonb),
    ('COG370H1', 'Special Topics in Cognitive Science', '24S', 'An in-depth study of selected questions in the field of Cognitive Science. Content will vary from year to year. Specific course information will be available on the Cognitive Science website at https://www.uc.utoronto.ca/cognitive-science', null, null, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('COG401H1', 'Seminar in Cognitive Science', '36S', 'Advanced treatment of cognitive science topics for arts majors. Possible topics include: concepts, consciousness, the mind-body problem, cognitive science and the arts.', 'COG402H1,  COG403H1', 2, '{"operator": "AND", "items": ["COG250Y1", "PHL342H1", {"credits": 14.0, "department": null}]}'::jsonb),
    ('COG402H1', 'Seminar in Cognitive Science', '36S', 'Advanced treatment of cognitive science topics such as neuroscientific theories of consciousness, rationality and modelling of cognitive processes.', 'COG401H1;  COG403H1', 2, '{"operator": "AND", "items": ["COG250Y1", "PSY270H1", {"credits": 14.0, "department": null}]}'::jsonb),
    ('COG403H1', 'Seminar in Cognitive Science', '36S', 'Advanced treatment of cognitive science topics, including the application of core ideas from probability theory, information theory, statistics, and machine learning to modelling human cognition and artificial intelligence.', 'COG401H1,  COG402H1', 5, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "CSC148H1", "COG250Y1", "COG260H1", {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1"]}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('COG404H1', 'Seminar in Cognitive Science', '36S', 'Advanced treatment of cognitive science topics, including language processes and language representation, productions and comprehension, language acquisition, and language and theory of mind, pragmatics, reference and context.', 'COG401H1;  COG402H1;  COG403H1', 2, '{"operator": "AND", "items": ["COG250Y1", {"operator": "OR", "items": ["JLP315H1", "JLP374H1"]}, {"operator": "OR", "items": ["LIN232H1", "LIN241H1"]}, {"credits": 14.0, "department": null}]}'::jsonb),
    ('COG415H1', 'Cognitive Science in Practice', '18L/15P', 'This course provides COG students with the opportunities to practice quantitative and qualitative evaluation and assessment methods in real world situations and juxtapose theory with practice. Placement activities will ground topics such as problem solving, logistics, decision making, etc., through practical application, individual and group / in-class critical reflection.', null, 2, '{"operator": "AND", "items": ["COG250Y1", {"operator": "OR", "items": ["COG341H1", "COG342H1"]}, "PSY370H1"]}'::jsonb),
    ('COG470H1', 'Special Topics in Cognitive Science', '24S', 'An in-depth study of selected questions in the field of Cognitive Science. Content will vary from year to year. Specific course information will be available on the Cognitive Science website at https://www.uc.utoronto.ca/cognitive-science', null, null, '{"operator": "AND", "items": [{"credits": 12.0, "department": null}]}'::jsonb),
    ('COG471H1', 'Special Topics in Cognitive Science', '24S', 'An in-depth study of selected questions in the field of Cognitive Science. Content will vary from year to year. Specific course information will be available on the Cognitive Science website at https://www.uc.utoronto.ca/cognitive-science', null, null, null::jsonb),
    ('COG497Y1', 'COG Independent Study', null, 'Advanced Independent Study. Not eligible for CR/NCR option. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Program Director. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/cognitive-science-courses.', '( COG498H1,  COG499H1)', null, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('COG498H1', 'Independent Study', null, 'Advanced Independent Study. Not eligible for CR/NCR option. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Program Director. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/cognitive-science-courses.', null, null, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('COG499H1', 'Individual Study in Cognitive Science', null, 'Advanced Independent Study. Not eligible for CR/NCR option. Students must submit an application form that includes a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Program Director. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/cognitive-science-courses.', null, null, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('CRE201H1', 'Introduction to Creativity and Society', '12L/12S', 'A course that explores the relationship between creativity and the social, political, and economic worlds in which it functions. Students acquire theoretical and methodological frameworks in Creativity Studies, historicize the conditions of creative possibility across disciplines, and explore case studies. Topics include the advent of creativity as a concept, a comparative understanding of creativity across non-western and historically marginalized cultures, analyses of how the business of innovation and professionalization of “creatives” affect the way arts and ideas develop, and a self-examination of how students'' own creative goals are shaped by the standards, structures, and practices that precede them.', null, 1, null::jsonb),
    ('CRE209H1', 'How Stories Work', '24S', 'Stories give shape and substance to the things we believe in, from scientific theories and sacred texts to literary tales and philosophical propositions. They perpetuate ideals and identities, and sustain institutions and communities. This course will take up a set of texts from the arts, sciences, religions and several other storytelling traditions, ancient and modern, considering their claims to authority and making connections between them.', 'VIC209H1', 1, null::jsonb),
    ('CRE210H1', 'Holography for 3D Visualization', '24L/36P', 'An introduction to the theory and practice of holography. Human perception & 3D visualization; fundamentals of 3D modeling; ray and wave optics; interference, diffraction, coherence; transmission and reflection holograms; colour perception; stereograms. Applications of holography in art, medicine, and technology. Computer simulation, design, and construction of holograms. This course does not require specific background or preparation in the sciences or arts. This course has a mandatory Materials Fee of $100 to cover non-reusable materials. The fee will be included on students'' ACORN invoice.', 'JOP210H1,  IVP210H1', 5, null::jsonb),
    ('CRE235H1', 'Innovation in Society', '24L', 'This course investigates innovation as it relates to emerging social, scientific, and environmental trends. Students will acquire key frameworks for understanding the evolution of innovation, the place of creativity, and the social impacts of disruption. Through case studies of innovation (such as the sharing economy and cryptocurrencies) and considering related issues (such as ethics and inclusion) students will develop approaches to understanding the societal impacts of creative disruption.', 'VIC235H1,  MUN101H1,  MUN102H1', 3, null::jsonb),
    ('CRE247H1', 'Creativity in the Sciences', '24S', 'This course explores definitions of “creativity” and compares its significance in science to creativity in arts, business or engineering. By studying major developments in the history of science as well as psychological and neuroscientific studies, we will consider factors that enable creativity; creativity in fundamental science and at various stages of a project; the randomness or predictability of scientific discoveries; disciplinary and interdisciplinary work; the evaluation of discoveries; and attempts to predict the future of scientific creativity.', null, 2, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('CRE269H1', 'Creative Practice: Speculative Fiction', '24S', 'This practice-based course provides the opportunity to study and produce creative works of speculative fiction in a workshop-style seminar. In addition to fiction, this course examines multimedia works in film and television, music, animation, and the arts while providing extensive grounding in contemporary artistic contexts of publication and production. Genres studied and produced may include cyberpunk, eco-fiction, contemporary fairytale and fable, horror, historical fiction, and dystopia and utopia.', 'CRE282H1 (Emerging Genres in Creative Writing) offered in Fall 2022, 2023, and 2024.', 1, null::jsonb),
    ('CRE270H1', 'Listening: A Critical History', '24S', 'Surveying scenarios for public and private musical listening, from historical contexts to the present, this course explores critical questions about how we listen, including the relationship between musical genres and listening situations, the definition of music vs. noise, the influence of spectatorship, and the impact of changing technologies. Students discuss the changing aesthetics and ideologies of musical listening, considering ways in which listening shapes our understanding of the social and our awareness of communities.', 'VIC270H1', 1, null::jsonb),
    ('CRE271H1', 'Reading the Wild', '24S', 'In light of the environmental crisis, this seminar surveys a wide range of oral and written literature in order to discover how our approach to nature has changed over the centuries, what gains and losses have attended modernity, and what older cultures can teach us as we seek to preserve threatened ecosystems. This course has a mandatory Materials Fee of $10 to cover non-reusable materials. The fee will be included on students'' ACORN invoice.', 'VIC271H1', 1, null::jsonb),
    ('CRE272H1', 'Song, Lyrics, and Songwriting', '24S', 'A course exploring song and lyrics in various musical genres, with a review of major developments in the repertoire. Topics addressed could include the ethics of borrowed forms, instrumentation and collaboration, commercial songwriting standards and practices, major aspects of music industries, and reception. Students will have the opportunity to create compositions, and pursue projects related to aspects of the field. Musical ability and training are not required.', null, 1, null::jsonb),
    ('CRE273H1', 'The Body: An Exercise', '24S', 'This course will sketch the vital role or the drama of the human body, aspects of its performance, comedy, tragedy and death, through selected parts of history, in life and as reflected in “art.”', 'VIC273H1', 1, null::jsonb),
    ('CRE275H1', 'Creative Writing: Short Fiction', '24S', 'This course is for aspiring fiction writers who wish to deepen their craft. Each seminar will feature a lecture on technical issues such as plot and characterization, as well as an analysis of a short story by a classic writer. Students will write their own stories, with editorial input from the instructor.', 'VIC275H1,  ENG389H1', 1, null::jsonb),
    ('CRE276H1', 'Writing for the Stage and Screen', '24L', 'A creative writing course for students interested in an introduction to writing for theatre and film. Seminars will focus on technical issues including plot, characterization, dramatic structure, dialogue, image-based storytelling, and aspects of dramaturgy. Seminars may also include analyses of notable plays and screenplays across a variety of genres. Students will write their own scripts, with editorial input from the instructor.', 'VIC276H1,  CIN349H1', 1, null::jsonb),
    ('CRE279H1', 'Creative Non-Fiction', '24S', 'This course examines the forms, style, aims, and ethics of non-fictional forms such as documentary writing, journalism, and life-writing. It combines the study of examples from contemporary media with exercises in writing non-fictional prose.', 'VIC279H1,  ENG387H1', 1, null::jsonb),
    ('CRE280H1', 'Creative Writing: Poetry', '24S', 'A workshop course (with a literature component) in writing poetry. Designed for those with a serious ambition to be writers as evinced in work they are already doing. The literature component emphasizes multicultural dimensions of contemporary writing in English.', 'VIC280H1,  ENG388H1', 1, null::jsonb),
    ('CRE281H1', 'Popular Music, Technology, and the Human', '24S', 'This course explores ways in which popular music, sound and sound technologies have influenced our understanding of the recent human condition. Drawing on a variety of theoretical perspectives, we consider the musical uses of technology as both a material culture and a set of distinctly innovative practices that can create powerful transformations of consciousness, meaning and value.', 'VIC281H1', 1, null::jsonb),
    ('CRE282H1', 'Emerging Genres in Creative Writing', '24S', 'A workshop-based seminar on creative writing in an emerging field. Specific genres may include flash fiction, autofiction, interactive fiction, slam poetry, the graphic novel, or the podcast. Focus in any given year to be determined by the instructor and advertised on the Victoria College academic programs website: https://vic.utoronto.ca/academic-programs/special-topics-courses/cre282h', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE335H1', 'Creativity and Collaboration in Social Enterprise', '24L', 'The course reflects critically on the role of a wide range of new enterprises and entrepreneurs in driving innovation and dynamism. Whether social enterprises, start-ups, community-based organizations, or for-profits, a variety of organizational forms are approaching thorny societal challenges such as driving economic inclusion or combating climate change. Students will explore how the public, private and community sectors can work together to develop creative, ethical and effective approaches to tackling ‘wicked’ problems.', 'VIC335H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE345H1', 'Evidence Based Approaches to Creativity', '24S', 'The seminar course pursues two goals. First, it provides an introduction to the latest scientific findings concerning creativity, by drawing on a broad range of scientific disciplines, such as psychology, neurobiology, sociology, anthropology, and education science. The topics include creative personality, the process of creation, as well as the sociocultural context of creativity. Second, it investigates various techniques that can help us learn to be more creative. This will involve discussions on how to choose one’s domain and field, be intrinsically motivated, how to collaborate, and how to brainstorm productively. Students will be given an opportunity to apply these techniques to specific fields of their choosing.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE349H1', 'Special Topics in Creativity', '24S', 'Topics vary from year to year depending upon instructor. Please see the Victoria College website for specific details about this year’s offerings: https://vic.utoronto.ca/academic-programs/special-topics-courses/cre349h.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE350Y1', 'Creative Writing', '48S', 'A workshop course (with a literature component) in writing fiction and poetry. Designed for those with a serious ambition to be writers as evinced in work they are already doing. Does not offer instruction for beginning writers. Presupposes perfect and sophisticated written language skills. The Literature component emphasizes multicultural dimensions of contemporary writing in English. Admission by application.', 'VIC350Y1', 1, null::jsonb),
    ('CRE353H1', 'Creativity and Altered Consciousness', '24S', 'This course provides the opportunity to study the relationship between creativity and altered states of consciousness through historical, cultural, and psychological perspectives. Focusing on the connection between artistic production and abnormal or extraordinary forms of perception, it grounds creativity as both a biological human capacity and a historically and culturally contingent category. Potential topics may include artistic activity in dialogue with intoxication and addiction, religion and spirituality, meditation and wellness, sports and physical exertion, dreams and liminal states, mental and physical illness, and technologically mediated consciousness.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE370H1', 'Music and the Imagination', '24S', 'This course explores how music creatively reflects and inspires our sense of self, place and community through readings, close listening, case studies, and creative responses. We consider various sites of musical imagination, and the genres that intersect with them. Course discussion addresses how music participates in the social life of creativity, imagination and fantasy, and what these roles mean for music’s significance in society and culture. No prior experience in music composition required.', 'VIC370H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE371H1', 'Documenting Reality', '24S', 'This seminar course explores methods of capturing, representing, and constructing reality through documentary media. Emphases will include opportunities and challenges brought by technical developments in the digital era, and the history and evolution of documentary work in print and/or photography. Students consider methods and innovations of major practitioners; ethical issues such as privacy, subjectivity, and objectivity; and partisanship and the effects of artificial intelligence and other automatic tools.', 'VIC371H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE372H1', 'Reviewing, Reception, and Reading Communities', '24S', 'While readers and audiences often are considered to be cultural "consumers," this course will consider reception as an active, creative, and often collaborative activity, by examining formal and informal practices of reviewing and response that may include fan/fanfic cultures, book clubs, community and nation-wide reading programs, and award competitions. Such contexts of reception will be considered along with their social, economic, and ethical implications.', 'VIC372H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE373H1', 'Archives and the Art of Memory', '24S', 'What is an Archive? What kind of history and culture does it Preserve? Or does it bury things forever? Who gets to be an archivist and who gets to tell the story? How can an archive preserve the stories of marginalized people? Can voices from the archive be brought back to life? In the context of a series of readings, presentations and projects the course focuses on case studies of government-housed and sponsored archives, family archives, archives of cultural institutions, grassroot archival initiatives, and of course digital archives. Each student will have an opportunity to produce an artistic project based on an archival research or create their own imaginary archive.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRE374H1', 'Cultural Encounters: Identity and Transformation in the Arts', '24S', 'This course focuses on specific scenes of cultural cross-pollination and on how these encounters are reflected in the arts. Areas of investigation might include the Harlem Renaissance, French Surrealism in the Caribbean, Bollywood / Hollywood, Indigenous Hip-Hop, or contemporary Toronto as a convergence of creative energy. How have artists from marginalized communities taken up and adapted modes of expression for their own creative purposes? How can new forms of artistic representation contest and undermine systemic social and political inequalities? This course focuses on liberating aesthetic innovations that respond to historically embedded cultural encounters.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CRE375H1', 'Histories of Creativity', '24S', 'This course provides an opportunity for in-depth study of the way creativity and innovation were practiced in earlier periods, in order to explore creativity as a historically and culturally contingent category and provide a comparative grounding for contemporary concepts of creativity. Historical case studies will range from Classical antiquity to the nineteenth century and may include topics such as how new forms and ideas emerge in the arts, architecture, and design; innovation in scientific knowledge and its representation; practices of improvisation in theatre and other artforms; the evolution of new genres and media.', null, 1, null::jsonb),
    ('CRE449H1', 'Special Topics in Creativity', '24S', 'Topics vary from year to year depending upon instructor. Please see the Victoria College website for specific details about this year’s offerings: https://vic.utoronto.ca/academic-programs/special-topics-courses/cre449h.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CRE470H1', 'Soundscapes', '24S', 'This course surveys the growth of the field of Acoustic Ecology and the aesthetic, political, and ethical questions it engages. Students learn about creative and musical practices associated with this new attention to sound, and they gain experience with the practice of field recording and sonic-environmental sampling. The course culminates with a final Soundscape composition or creative mapping project. No previous experience in sound recording or composition required.', 'VIC470H1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CRE479H1', 'Fiction: A Master Class', '24S', 'A workshop course in writing fiction. Designed for those with a serious ambition to be writers as evinced in work they are already doing. Does not offer instruction for beginning writers. Admission by application.', 'VIC479Y1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('CRE479Y1', 'The Novel: A Master Class', '48S', 'Advanced young writers in this fourth-year seminar work to produce a short novel appropriate for submission to an agent or a publisher. The class does not offer instruction for beginning writers. It is intended for serious writers interested in learning about writing novels at a professional level. Admission by application.', 'VIC479Y1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('CRE480H1', 'Poetry: A Master Class', '24S', 'A workshop course in writing poetry. Designed for those with a serious ambition to be writers as evinced in work they are already doing. Does not offer instruction for beginning writers. Presupposes perfect and sophisticated written language skills. Admission by application.', 'VIC480H1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": "CRE"}]}'::jsonb),
    ('CRI100H1', 'True Crime? The Myths and Realities of Media Depictions of Crime and Justice', '24L/12T', 'The course will explore how crime and criminal justice institutions (the police, the courts and corrections) are depicted in the news, movies, television and on social media. The course will focus on how these depictions impact both public opinion and politics. The course will also examine how media depictions and public perceptions of crime and justice often differ dramatically from the empirical evidence produced by Criminological and Social Legal research.', null, 3, null::jsonb),
    ('CRI205H1', 'Introduction to Criminology', '24L/12T', 'An introduction to the study of crime and criminal behaviour. The concept of crime, the process of law formation, and the academic domain of criminology. Theories of crime causation, methodologies used by criminologists, and the complex relationship between crime, the media and modern politics.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRI210H1', 'Criminal Justice', '24L/12T', 'An introduction to the Canadian criminal justice system. The institutions established by government to respond to crime and control it; how they operate, and the larger function they serve; including the role of the police, the trial process, courts and juries, sentencing, imprisonment and community corrections.', null, 3, '{"operator": "AND", "items": ["CRI205H1"]}'::jsonb),
    ('CRI215H1', 'Introduction to Sociolegal Studies', '24L/12T', 'The course covers several major issues that will help prepare students for advanced courses in the criminology major: the meaning of law, the production of laws and legal institutions, law in action, comparative legal traditions, and the methodology of sociolegal studies.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRI225H1', 'Criminal Law', '24L/12T', 'The main principles and themes of Canadian criminal law; legal definitions of crime, requirements of a criminal act (actus reus), criminal intention (mens rea), causation and defences. The origins, goals and functioning of criminal law, and limits on the power of the state to criminalize behaviour.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CRI299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CRI299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CRI300H1', 'Theories of Criminal Justice', '36L', 'A survey of the evolution of normative theories of criminal justice, which examines how major theorists from the Enlightenment to the contemporary period have understood the normative justification for criminal prohibition and punishment. Although the course focuses on western political philosophy and social science, there will also be some attention to theories of criminal justice in selected non-western traditions.', null, 3, '{"operator": "OR", "items": [{"operator": "AND", "items": ["CRI205H1", "CRI225H1"]}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('CRI322H1', 'Inequality and Criminal Justice', '36L', 'This course examines the intersections between social inequality and the criminal justice system in Canada and internationally. The course explores how factors such as race, ethnicity, gender, sexual orientation and religion influence perceptions of and experiences with crime and criminal justice.', 'CRI391H1 (Topics in Criminology and Sociolegal Studies: Inequality and Criminal Justice) offered in Winter 2018, Summer 2018, Summer 2019, Winter 2020,  SOC322H5', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "SOC212H1"]}]}'::jsonb),
    ('CRI335H1', 'Policing', '36L', 'A theoretical framework is developed to examine the nature of policing, its structure and function. Attention is given to the history of policing as a global form of social practice. We examine the perspectives of both “the police” and “the policed”, as well as the objectives, domains, strategies, and authority of contemporary policing, including decision-making, organizational culture, and accountability.', null, 3, '{"operator": "OR", "items": ["CRI210H1", "CRI215H1"]}'::jsonb),
    ('CRI340H1', 'Punishment: Theory and Practice', '36L', 'The study of punishment from historical and philosophical perspectives, with a focus on contemporary Canadian policy issues. Topics covered include penal theory, prisons and non-carceral forms of punishment, and the goals of penal reform.', null, 3, '{"operator": "AND", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}'::jsonb),
    ('CRI343H1', 'Comparative Criminal Justice', '36L', 'Criminal justice issues outside Canada, based on a variety of international and historical studies. The evolution of criminal justice systems in Western Europe, including the English adversarial and continental European inquisitorial approaches. A comparison of policing, criminal procedure, forms of punishment, and crime rates in the contemporary world.', null, 3, '{"operator": "AND", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}'::jsonb),
    ('CRI345H1', 'History of Criminal Justice', '36L', 'The course offers a historical perspective on the development of the legal doctrines, professions and institutions that define criminal justice in Canada and the broader common law world today. Topics include the shift from medieval trial by ordeal and torture to the modern reliance on expert witnesses and forensic science; the emergence of the adversarial trial; the growth of the legal profession; the birth of policing; the rise of the penitentiary; and the changing fortunes of the death penalty. The course focuses primarily on the period from the eighteenth century to the present. Students will be introduced to historical debates and ways of thinking and writing about law and crime. We will explore how culture, politics, economics and social life are essential to how we understand the foundational elements of criminal justice, including concepts of truth, guilt, legitimacy, fairness and violence.', 'CRI392H1 (Topics in Criminology and Sociolegal Studies: History of Criminal Justice in the Common Law World) offered in Winter 2018, Winter 2019, Winter 2020', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI215H1", "CRI210H1", "SOC212H1", "SOC313H1", "HIS268H1"]}]}'::jsonb),
    ('CRI350H1', 'Understanding Criminological Research', '36L', 'An introduction to social science research methods used by criminologists and to the statistical analysis of criminological data. An understanding of the strengths and weaknesses of published criminological research is developed. Specific technical issues related to sampling, measurement, and data analysis are taught in the context of examining ways of answering research questions.', 'SOC200H1,  SOC200Y1', 3, '{"operator": "AND", "items": ["CRI205H1", "CRI210H1"]}'::jsonb),
    ('CRI364H1', 'Indigenous Peoples & Criminal Justice', '36L', 'An introduction to issues affecting Indigenous peoples in the Canadian criminal justice system identified by Indigenous scholars, activists and allies. Topics include: effects of colonization, legal discrimination and disenfranchisement, Treaties and land claims, criminalization, Indigenous activism, and the Truth and Reconciliation Commission.', 'CRI394H1 Topics: Indigenous Peoples & Criminal Justice taken in 20171', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI215H1", "CRI225H1"]}]}'::jsonb),
    ('CRI365H1', 'Crime and Mind', '36L', 'Legal, psychological and sociological understandings of issues in the criminal justice system, through a consideration of topics including: criminal intent, the Not Criminally Responsible on Account of Mental Disorder defence, the use of battered woman syndrome as part of a self-defence, infanticide, issues of transcultural psychiatry, and jury screening for bias.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}]}'::jsonb),
    ('CRI370H1', 'Youth Justice', '36L', 'The course will examine what is known about offending by youths and the various purposes that have been attributed to youth justice systems. The course will focus, in large part, however, on the nature of the laws and youth justice systems that have been designed in Canada and elsewhere to respond to offending by youths.', null, 3, '{"operator": "AND", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}'::jsonb),
    ('CRI372H1', 'Regulating Citizenship', '36L', 'The course examines selected topics in the scholarly study of citizenship, including the history of citizenship, normative theories of democratic citizenship, rights and duties of citizenship, acquisition and loss of citizenship, and related issues, such as multiple citizenship, statelessness, and the international law of citizenship. Readings come from law, history, political science, and other disciplines; and cover Canada, other western societies, and developing countries. The course comprises three basic units: the normative basis and historical evolution of citizenship, including a case study of Canada, policies governing the acquisition and loss of citizenship in Canada and elsewhere, and the parameters of citizenship and lack of citizenship in the contemporary world. Students will gain an understanding of the historical evolution of forms of political membership in both western and non-western societies, the constitutive role of citizenship in creating and maintaining individual rights, and the development and contemporary regulation of Canadian citizenship in comparative international perspective.', 'CRI392H1 (Topic: Regulating Citizenship) offered in Fall 2021,  CRI394H1 (Topic: Regulating Citizenship) offered in Fall 2017, 2018, and 2019', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}]}'::jsonb),
    ('CRI380H1', 'Crime, Gender and Sex', '36L', 'Theory, research and policy related to the ways in which gender shapes criminal behaviour, the administration of criminal justice, and the criminal law. How notions of different types of masculinity and femininity are embedded in and influence both the operation of the criminal justice system as well as criminal behaviours. The regulation of gender and sexuality through the criminal law and through crime.', null, 3, '{"operator": "OR", "items": [{"operator": "AND", "items": ["CRI205H1", "CRI210H1"]}, {"operator": "AND", "items": ["SOC212H1"]}]}'::jsonb),
    ('CRI383H1', 'Immigration, Ethnicity and Crime', '36L', 'The connection between immigration and crime, the effect of immigration on crime rates, discrimination against immigrants, the representation of immigrants in crime statistics, public perception of risk and security, and criminal justice policy changes which affect immigration. We consider research conducted in North America and Europe.', null, 3, '{"operator": "OR", "items": ["CRI205H1", "SOC212H1"]}'::jsonb),
    ('CRI385H1', 'Representing Crime and Authority', '36L', 'Cultural constructions of crime, disorder, dangerousness and risk are integral parts of the criminal justice system. A critical analysis of how criminal justice personnel, the media, and academic criminologists construct their authority through symbols and images, in order to “explain” and manage crime, and how these representations are regarded in public discourse.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}]}'::jsonb),
    ('CRI386H1', 'Origins of Criminal Justice', '36L', 'Criminal justice practice, as well as political debate concerning crime and criminal justice, are often influenced by ideas that are initially developed outside the criminal justice arena. This course examines the history, current influence and efficacy of a range of such ideas, such as: the role of religious practice in rehabilitating offenders; military service and participation in sports as preventive of delinquency; the influence of environmental pollution on crime rates; the concept of the ‘problem family’; intelligence based policing and the use of management theories in criminal justice organizations. Note: The course may include an optional Service Learning component. If offered, additional information will be provided in the Faculty of Arts and Science’s timetable.', 'CRI390H1 Roots of Criminal Justice Policy taken in 20141/20151/20161.', 3, '{"operator": "AND", "items": ["CRI205H1", "CRI210H1"]}'::jsonb),
    ('CRI389Y0', 'Topics in Criminology and Sociolegal Studies Abroad', null, 'Topics in Criminology and Sociolegal Studies offered in an international setting. The content may vary from year to year.Details are posted on the Summer Abroad website.', null, 3, null::jsonb),
    ('CRI390H1', 'Topics in Criminology and Sociolegal Studies', '36L', 'The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}]}'::jsonb),
    ('CRI391H1', 'Topics in Criminology and Sociolegal Studies', '36L', 'The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}]}'::jsonb),
    ('CRI392H1', 'Topics in Criminology and Sociolegal Studies', '36L', 'The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}]}'::jsonb),
    ('CRI393H1', 'Topics in Criminology and Sociolegal Studies', '36L', 'The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}]}'::jsonb),
    ('CRI394H1', 'Topics in Criminology and Sociolegal Studies', '36L', 'The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI225H1"]}]}'::jsonb),
    ('CRI395H1', 'Independent Study', null, 'Independent study under the direction of a faculty member. It is recommended that student approaches a Criminology and Sociolegal Studies Faculty member who might willing to supervise their work in  CRI395H1. If student has found a faculty member willing to supervise their proposal, they must complete the application form with the help of their supervisor. A detailed description of the proposal is required. Enrolment is limited to students in the Criminology and Sociolegal Studies program. Students are not entitled to take more than 1.0 credit of  CRI395H1 course. Consult the program website for additional information. Not eligible for CR/NCR option.', 'CRI395Y1', 3, '{"operator": "AND", "items": ["CRI205H1", "CRI210H1", "CRI225H1", {"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI396H1', 'Research Participation', null, 'Credit course for supervised participation in a faculty research project. Offered only when a full-time appointed faculty member from the Centre for Criminology & Sociolegal Studies is willing and available to supervise. Students must contact faculty members currently teaching in the Criminology and Sociolegal Studies program to find out if there are any research participation opportunities available. Students requesting enrolment in a research participation course are advised to select an alternative course until the status of their enrolment is confirmed. Together with your supervisor, complete and submit a request for enrolment application form and the research ethics approval confirmation letter (if required). Submit the form by the beginning of the first week of the semester. Consult the program website for additional information. Not eligible for CR/NCR option.', 'CRI397Y1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CRI398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CRI398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CRI399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CRI399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CRI420H1', 'Current Issues in Criminal Law', '24S', 'An advanced seminar exploring in detail current issues in criminal law. The objective of the course is to discuss current policy and case law developments in the criminal law, and their social, political and ethical implications. The role of Parliament and the judiciary in the development of the criminal law is considered. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI422H1', 'Indigenous Law', '24S', 'Seminar course exploring Indigenous law, settler state law, and the complex interrelationship between the two in Canada. Topics include: legal sources, forms and processes; sovereignty, territory and jurisdiction; treaty relationships; Indigenous peoples in international law; Indigenous rights and the constitution; environmental use, relations and protection; and Indigenous self-determination and governance.', 'CRI490H1 Advanced Topics in Criminology: Indigenous Law taken in 20169', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["CRI205H1", "CRI210H1", "CRI215H1", "CRI225H1"]}, {"credits": 0.5, "department": "CRI"}]}'::jsonb),
    ('CRI425H1', 'The Prosecution Process', '24L', 'A critical examination of the process by which certain conduct is identified, prosecuted and punished as “crime”, and the process by which individuals become “criminals”. The evolution of the modern prosecution system, including the exercise of prosecutorial discretion, rules of evidence, socially constructed defences, disparity in sentencing, and wrongful convictions.', null, 3, '{"operator": "AND", "items": ["CRI205H1", "CRI210H1", "CRI225H1", {"credits": 0.5, "department": "CRI"}]}'::jsonb),
    ('CRI427H1', 'Organized Crime and Corruption', '24S', 'An advanced seminar exploring the history and characteristics of organized crime and corruption.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI428H1', 'Policing the City: Crime, Community and Inequality', '24S', 'An advanced seminar exploring the connection between neighbourhoods and the perpetuation of poverty, social marginalization, segregation and crime. The course may include an optional Service Learning component. Check the timetable for details.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI429H1', 'Youth Culture, Racialization and Crime in the Global Context', '24S', 'An advanced seminar exploring youth culture and its possible connection to criminality from an international perspective.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI431H1', 'Mental Health, Morality & Legal Controls', '24S', 'A critical exploration of contemporary debates in criminology, and legal and moral philosophy concerning the diagnostic and criminal justice labeling of mental disorders such as psychopathy and paedophilia, and their representation in popular culture.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI435H1', 'Advanced Seminar in Policing', '24S', 'This course will explore policing in a comparative and historical context. Issues to be covered include the following: the maintenance of law and order before police forces; development of police forces in continental Europe and the English-speaking world; structure and function of national police forces around the world today; the role of political and secret police forces; and contemporary debates on the mission and regulation of the police in contemporary North America including issues such as police-community relations, private policing, and counter-terrorism.', 'CRI3130H1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI450H1', 'Advanced Research/Reading', null, 'A supervised individual or group project under the direction of a faculty member from the Centre for Criminology & Sociolegal Studies. Offered only when a full-time appointed faculty member from the Centre for Criminology & Sociolegal Studies is willing and available to supervise. Students must contact Faculty members currently teaching in the Criminology and Sociolegal Studies program to find out if there are any individual or group project opportunities available. Students requesting enrolment in a research participation course are advised to select an alternative course until the status of their enrolment is confirmed. Together with your supervisor, complete and submit a request for enrolment application form and the research ethics approval confirmation letter (if required). Submit the form by the beginning of the first week of the semester. Form is available on the Program Office website. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"credits": 1.5, "department": "CRI"}]}'::jsonb),
    ('CRI480H1', 'Interpersonal Violence', '24S', 'The meaning, purposes and sources of interpersonal violence, including an examination of debates over defining and documenting violence, and a review of the research on the relationships between illegitimate, interpersonal violence and state-approved or state-initiated violence. Cultural, social and individual correlates of interpersonal violence; the violence of the law; and how violence is justified and denied.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI482H1', 'Security Governance', '24S', 'The course will examine selected topics in security governance. Complementing university courses on public or state policing, which emphasize the role of the state in maintaining public order, we will examine how security is jointly produced through the interactions of state, commercial, civil society, and individual actors. Topics to be covered include the following: the public police and theories of security governance, private and privatized policing, plural policing and other non-state sources of public order, and private ownership of weapons. Students should gain an understanding of the myriad ways in which the state and other actors interact to create, maintain, and reshape public order.', 'CRI491H1 (Topic: Security Governance) offered in Fall 2021,  CRI492H1 (Topic: Security Governance) offered in Fall 2022', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI487H1', 'Law, Space, and the City', '24S', 'An introduction to interdisciplinary studies of law and space, this course covers a broad range of topics, from work on empire and colonialism by legal historians and indigenous scholars to studies of national spaces, urban spaces, and bodily spaces. Some background in either legal studies or cultural geography is desirable. Open to students in law, geography, anthropology, women/gender studies, and sociology, though permission of the instructor is required.', 'CRI3256H (when offered as a joint course)', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI490H1', 'Advanced Topics in Criminology and Sociolegal Studies', '24S', 'The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI491H1', 'Advanced Topics in Criminology and Sociolegal Studies', '24S', 'Topics vary from year to year. The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI492H1', 'Advanced Topics in Criminology and Sociolegal Studies', '24S', 'The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI493H1', 'Advanced Topics in Criminology and Sociolegal Studies', '24S', 'Topics vary from year to year. The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI494H1', 'Advanced Topics in Criminology and Sociolegal Studies', '24S', 'Topics vary from year to year. The objective of the course is to explore emerging issues in Criminology, and their social, legal, ethical and political implications.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CRI"}]}'::jsonb),
    ('CRI498H1', 'Intensive Course', null, 'Content in any given year depends on instructor. Intensive courses are offered by distinguished visitors from around the world. Students in their 4th year are strongly encouraged to take advantage of this unique opportunity to study with one or more outstanding visiting international scholars that the Centre for Criminology & Sociolegal Studies brings from time to time. The intensive course usually runs for approximately 3-4 weeks.', null, 3, null::jsonb),
    ('CSB195H1', 'Computational Biology Foundations', '24L/12T', 'Our understanding of life is built from observation, abstraction, modeling, and comparison. In this First Year Foundations course we explore how these activities are based on concepts of chance and choice, of organization and dispersion, of cooperation and conflict, and how these ideas inform domains such as statistics, computer science, bioinformatics, molecular biology, physiology and ecology. Through this, we build a broad framework of relationships and connections that will make students'' engagement with specialized courses throughout the sciences all the more meaningful. This course''s focus on best practices of structuring project work, using tools and resources, and documentation, will be valuable preparation for all subsequent courses. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('CSB196H1', 'Genes, Genomes and Us', '24L', 'With the completion of the human genome sequence, we now have access to more information than ever before about our genetic make-up. This course addresses topics such as what are genes, how are they identified and how does knowledge about genes impact society. Students will learn basic concepts in genetics. Using this conceptual foundation, the significance of genomic research for understanding human biology, and the social consequences that may result from it, will be discussed. Evaluation is based on class discussions, homework, oral presentation and written assignments. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('CSB197H1', 'Human Viruses', '24L', 'This course allows students to broaden their knowledge about the most important human viruses and prions. In essence, what viruses are, what they do, what are the diseases caused by viruses and how they are transmitted, etc., and what can be done about them (vaccines, antiviral treatments, etc.). Viruses cause many diseases ranging from a benign rash to severe hemorrhages and death. Each student will select a specific topic in Virology and write an essay and present a seminar for the rest of the class. Major "hot" problems in Virology from pandemics to controversial vaccines will also be discussed. Two tests covering all materials presented by all the students'' seminars will be conducted. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('CSB198H1', 'Cell and Molecular Biology in the News', '24L', 'The pace of knowledge creation in the fields of cell and molecular biology has greatly increased in the 21st century and with it, the need for greater scientific literacy. In this course, we will teach students to find reliable sources of information in order to understand the basic concepts underlying the research reported in these media releases, with the ultimate aim of critically evaluating these reports. Through exploration of various media articles in cell and molecular biology (with an emphasis on humans), students will be able to apply what they have learned to current events, as well as relevant issues in their lives and society as a whole. Students will be assessed through short-written assignments, class discussions, an oral presentation, and a final project where they will get the opportunity to explore the research behind a media article of their choice. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('CSB199H1', 'Biotechnology and Society', '24L', 'From the manipulation of genes of plants for improved food production through to human tissue engineering and stem cell research, biotechnology is increasingly playing a major role in our world. Society, however, is often challenged by the rapid advances in our knowledge in these areas, and how to best apply these technologies in a manner that is socially responsible and economically viable. In this seminar course, students will research and describe various applications of biotechnology using information obtained from reputable sources, and lead discussions on the benefits and concerns that arise from this research. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('CSB201H1', 'Molecular Biology, Biotechnology and You', '24L/12T', 'An online course intended to provide non-science students with an understanding of basic concepts in molecular biology and genetics, with particular emphasis on humans. Students will work online in groups on problem sets. The course will end with an introduction to biotechnology, including an opportunity for students to use their new knowledge to explore a real, multi-dimensional problem (e.g., cancer). Lectures will be delivered via the web and mandatory tutorials will require live webinar participation. The final exam will require attendance on the St. George campus. This course does not count towards CSB programs.', 'BIO130H1,  BIO230H1,  BIO255H1', 4, null::jsonb),
    ('CSB202H1', 'Further Exploration in Biotechnology', '24L/12T', 'Provides non-science students with an additional opportunity to explore biotechnology and its applications in agriculture, the environment, and human health including: genetically modified organisms, drug discovery and aging. Most lectures are viewed online before class and students work in groups during class on problem sets and case studies designed to stimulate further learning, enhance evidence-based reasoning, and promote reflection on the role of biotechnology in society. This course does not count towards CSB programs.  CSB201H1 is not a prerequisite for this course.', 'BIO230H1,  BIO255H1', 4, null::jsonb),
    ('CSB280H1', 'Data Science for Cell and Systems Biology', '24L/12T', 'The abundance of raw data in biological sciences continues to grow year after year. The skills required to navigate and thrive in this field are no longer confined to the laboratory bench as experimental results go beyond simple analyses. This course will introduce basic tools used in the analysis of big data such as dimensional reduction, visualization, and machine learning. Students will get practical experience writing code to analyze example datasets.', 'STA272H1,  STA302H1', 4, null::jsonb),
    ('CSB299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSB299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSB325H1', 'Endocrine Physiology', '24L/9T', 'The regulation of physiological processes by hormones and other signalling molecules in non-human chordates. An integrated genes-to-environment approach is used to examine aspects of hormonal evolution, physiological information flow, behaviour and neuroendocrinology, and xenobiotic endocrine disruptors.  Students will have the opportunity to research areas of their own interest via group interaction in a series of tutorial sessions.', null, 4, '{"operator": "AND", "items": ["BIO270H1", "BIO271H1"]}'::jsonb),
    ('CSB327H1', 'Extracellular Matrix Dynamics and Associated Pathologies', '36L', 'Examines the expression, structure and function of the four major classes of ECM macromolecules: collagen, proteoglycans, non-collagenous structural proteins and glycoproteins. In addition to forming elaborate networks that give tissues and organs their unique architectural design and biomechanical properties, ECM molecules act as potent regulators of all cellular activities. Emphasis is placed on the morphoregulatory contribution(s) of ECM molecules to normal and pathological development.', null, 4, '{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}'::jsonb),
    ('CSB328H1', 'Animal Developmental Biology', '24L/24P', 'Basic concepts in developmental biology. Early development of invertebrates and vertebrates will be discussed with emphasis on experimental and molecular analysis of developmental mechanisms. Tutorials focus on the experimental analysis of embryonic development and regeneration, and discuss primary literature of selected topics in developmental biology. (Lab Materials Fee: approximately $27). A lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these (approximate cost is $27).', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('CSB329H1', 'Stem Cell Biology: Developmental Models and Cell-based Therapeutics', '24L/12T', 'Stem cells provide the basis for cellular diversity in multicellular organisms and have enormous therapeutic potential in regenerative medicine. The course will introduce students to the differences and similarities between stem cells from different organisms, their roles throughout development and therapeutic potential.', null, 4, '{"operator": "AND", "items": ["BIO230H1"]}'::jsonb),
    ('CSB330H1', 'Techniques in Molecular and Cell Biology', '8L/52P', 'Laboratory course on molecular and cell biology research techniques used to study genes and proteins. Topics include plasmid cloning, PCR, bioinformatics, gene expression analyses, protein-protein interactions, and protein subcellular localization. (Lab Materials Fee: $53). A lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these (approximate cost is $27).', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('CSB331H1', 'Advanced Cell Biology', '36L', 'The development of multicellular organisms is dependent on complex cell-cell and cell-matrix dynamics. The course examines the molecules and mechanisms involved and how they act in concert to regulate distinct developmental and physiological events. Emphasis is placed on the experimental approaches and technology used to study the molecular interactions and dynamics that alter structure-function relationships in cells and organisms.', null, 4, '{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}'::jsonb),
    ('CSB334H1', 'Methods and Analysis in Behavioral Neuroscience', '24L/12T', 'The scale and complexity of biological data are fast expanding as biotechnology develops. How are we going to process and interpret large-scale data? Using example-based approaches in the context of behavioural neuroscience (e.g., sleep, movement, learning, decision-making), this course aims to bridge biology and computational analysis techniques. Through lectures and hands-on sessions, students will learn about modern methodology in neuroscience (e.g., electrophysiology, optogenetics, calcium imaging) and how to analyze neural data sets. Students will be introduced to programming in MATLAB tailored for neuroscience, signal processing, image processing, statistical analysis, and machine learning techniques. By developing practical skills through various neural data types (e.g., EEG, EMG, Ca2+ Imaging), this course equips students with the skills to handle neural data, basic computational approaches in neuroscience, and a quantitative understanding of brain functionality.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["BIO270H1", "BIO271H1"]}, {"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}]}, "MAT136H1"]}'::jsonb),
    ('CSB340H1', 'Plant Development', '24L', 'Plant developmental genetics at the molecular, cellular and organismal level, generation and use of genomic resources in plant model organisms. Questions address the genetic dissection of plant embryo and meristem development, plant stem cell specification and tissue patterning. Genomic approaches applicable to plant biotechnology are also covered.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('CSB343H1', 'Animal Energetics', '24L', 'Animal structure and function, at all levels from molecule to whole animal, are dependent on energy. This course describes how the supply, consumption, transformation, exchange and storage of energy can facilitate, constrain and limit animal function. Emphasis is placed on systems level physiological function and whole animal performance.', null, 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BIO270H1", "BIO271H1"]}, {"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}]}'::jsonb),
    ('CSB345H1', 'Introductory Biology of Sleep', '24L/12T', 'This course will cover fundamental theories on the regulation, evolution, and function of sleep-wake states – how and why animals sleep. Sleep is a behavioural state that occurs in all vertebrates and it has also been identified in several species of invertebrates. In these animals, sleep is associated with profound changes in physiological function at the molecular, cellular and system levels. Furthermore, sleep has marked implications for the neurobiology of behaviour and the evolution of organisms because of the impact it has on cognitive function, memory consolidation, and overall health. The course will be integrative and comparative, linking together concepts from all levels of biological organization (molecular to whole organism) and drawing examples from a variety of different animals.', null, 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BIO270H1", "BIO271H1"]}, {"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}]}'::jsonb),
    ('CSB346H1', 'Neurobiology of Respiration', '24L/12T', 'This course examines how the central and peripheral nervous system controls breathing in mammals. Topics include how the brain generates rhythmic breathing movements, how sleep impacts breathing control and how abnormal breathing contributes to disorders such as sleep apnea.', null, 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BIO270H1", "BIO271H1"]}, {"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}]}'::jsonb),
    ('CSB348H1', 'Laboratory in Comparative Animal Physiology', '48P', 'Laboratory exercises will include traditional and guided inquiry approaches to investigate and gain an understanding of the regulation of physiological systems in vertebrates and invertebrates. Students will experience the nature of physiological investigation while being exposed to a range of the current experimental approaches animal physiologists use to design, test and evaluate hypotheses, and communicate their findings. This course will emphasize the fundamental characteristics humans share with all animal life and the physiological adaptations that have permitted species to exploit alternative environmental niches. This course requires participation and includes group work, written assignments, and oral presentations. (Lab Materials Fee: $53). Lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these items (approximate cost is $27).', 'PSL372H1', 4, '{"operator": "AND", "items": ["BIO230H1"]}'::jsonb),
    ('CSB349H1', 'Eukaryotic Gene Expression', '30L/18T', 'Genome structure and the regulation of gene expression in eukaryotic cells. Topics include transcription, gene silencing and regulation, expression profiling, non-coding RNAs, and translational control. Tutorials emphasize problem based learning exercises that relate to recent advances in the broad field of eukaryotic gene expression.', 'MGY311Y1,  MGY420H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('CSB350H1', 'Laboratory in Molecular Plant Biology', '24L/36P', 'Laboratory methods used in plant molecular biology research. Topics include vector construction, plant transformations, PCR, DNA blots, high-throughput screens, genetic mapping, and bioinformatic analyses. (Lab Materials Fee: $53). Lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these items (approximate cost is $27).', null, 4, '{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}'::jsonb),
    ('CSB352H1', 'Bioinformatic Methods', '6L/18P', 'Use of available programs for analyzing biological data. This is an introductory course with a strong emphasis on hands-on methods. Some theory is introduced, but the main focus is on using extant bioinformatics tools to analyze data and generate biological hypotheses.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('CSB353H1', 'Plant-Microorganism Interactions and Plant Immunity', '24L', 'Plants have co-evolved with microbes ever since their first appearance on land, resulting in sophisticated strategies of pathogenicity, symbiosis, commensalisms and mutualism by microorganisms. This course presents an overview of the strategies by both plant hosts and microorganisms for their survival.  The lecture content includes the basic concepts of plant-microbe interactions and plant immunity as well as signal transduction in plant immunity.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}'::jsonb),
    ('CSB360H1', 'Genetic Foundation of Molecular Biology', '24L', 'This course provides in depth foundational knowledge underlying molecular biology technologies. It focuses on how genetic principles were applied to develop the most commonly used molecular biology techniques today. Students will expand their genetic knowledge from introductory level genetic courses. This course does not involve explaining the basics of molecular biology such as replication, recombination, translation or gene expression. By contrast, this course expects that students already understand these concepts in detail and now apply this understanding towards how they were used to develop experimental technologies. For example, how are transformation, mutagenesis, plasmid construction, and gene expression systems used to design molecular experiments.', 'MGY340H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, "CSB349H1"]}'::jsonb),
    ('CSB397Y0', 'Research Abroad in Cell & Systems Biology', null, 'An independent research project conducted in molecular biology, cell biology, developmental biology, neurobiology, physiology or systems biology. Whole organism, cell culture, in vitro or in silico studies are acceptable. The laboratory research is conducted by the student and supervised by a faculty member at an approved partner university. An information session is held each fall, and an application and interview process is required. The research is typically conducted from May to August. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1", "BIO271H1"]}]}'::jsonb),
    ('CSB398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSB399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSB399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSB426H1', 'Physiology of Stress and Reproduction', '12L/24S', 'Students will gain an integrated understanding of how organismal and cellular stress affects the process of reproduction. The focus will be primarily on chordates and will examine genetic, cellular, organismal, behavioural, and social levels of interaction.', null, 4, '{"operator": "AND", "items": ["CSB325H1"]}'::jsonb),
    ('CSB427H1', 'Drosophila as a Model in Cancer Research', '12L/12T/12S', 'Use of the genetic model organism Drosophila in biomedical research with specific emphasis on cancer research. Students will read, discuss and present classical papers and current literature in the field to enhance their ability to critically evaluate the primary scientific literature.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, {"operator": "OR", "items": ["CSB328H1", "CSB331H1", "CSB349H1", "MGY350H1"]}]}'::jsonb),
    ('CSB428H1', 'Cytoskeletal Networks of the Cell', '12L/12T/12S', 'The cytoskeleton is a highly dynamic protein network that links all regions and components of the cell to provide a structural framework for organizing numerous cellular activities. This course will explore the molecular regulation of the actin and microtubule cytoskeletons during cell migration and other cellular processes. Topics will include (1) an overview of key regulators of the cytoskeleton, (2) how they organize specific cellular structures, and (3) how the coordinated activities of cytoskeletal networks govern complex cellular behaviours. The format of this course is mainly journal club style presentations and student-led discussions of research papers, together with supporting background lectures. Experience with critical evaluation of research papers is emphasized.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}, {"operator": "OR", "items": ["BCH340H1", "CJH332H1", "CSB328H1", "CSB329H1", "CSB331H1", "CSB340H1", "CSB397Y0"]}]}'::jsonb),
    ('CSB429H1', 'Germ Cell Biology', '12L/12T/12S', 'This course will discuss the genetic and cell biological aspects of the development of gametes, gonads, and sex related traits in animals, including invertebrates and vertebrates.  The course consists of lectures and student seminars, and is based on the discussion of primary scientific literature.  Not recommended for students with fewer than 14.0 credits.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSB328H1", "CSB340H1", "CSB349H1", "MGY311Y1", "MGY312H1"]}]}'::jsonb),
    ('CSB430H1', 'Neurogenesis', '24L/12T', 'An examination of the molecular and cellular basis of neurogenesis in development and adult nervous systems. Experimental evidence from recent studies in selected invertebrate and vertebrate model systems will be discussed. Topics include neural stem cells, regional specialization of neurogenesis, neuronal and glial differentiation, extrinsic regulation of neurogenesis, adult neurogenesis, and the evolution of neurogenesis. Students are expected to have a basic knowledge of molecular genetics, developmental biology and/or neuroanatomy. Lectures will be complemented by student directed seminars that focus on specialized research studies published in leading scientific journals.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, {"operator": "OR", "items": ["CSB328H1", "CSB349H1", {"operator": "AND", "items": ["HMB200H1", "HMB320H1"]}]}]}'::jsonb),
    ('CSB431H1', 'Evolution and Development: Gastrulation', '12L/12T/12S', 'Gastrulation is used to examine the molecular and cellular mechanisms of a major morphogenetic process and its evolutionary modifications.  This course includes small group discussions and presentations.  Controversial issues presented in the lectures are debated.', null, 4, '{"operator": "AND", "items": ["CSB328H1"]}'::jsonb),
    ('CSB432H1', 'Advanced Topics in Cellular Neurophysiology', '12L/24S', 'This course examines cellular neurophysiological processes in the developing and mature nervous systems with a focus on: (1) understanding modern techniques used in neurophysiological research; and (2) interpreting the results from neurophysiological peer-reviewed manuscripts. This course is interactive and requires students to contribute actively during lectures and seminars, including conducting a group presentation.', null, 4, '{"operator": "AND", "items": ["CJH332H1"]}'::jsonb),
    ('CSB434H1', 'Introduction & Methods of Systems Neuroscience', '12L/12P/12S', 'Our brain is highly complex with billions of neurons; how do neurons work together to produce adaptive & flexible behaviors? Systems neuroscience studies this question at the systems level. Using various animal models, it aims to provide quantitative and causal links between neural circuits/networks and perception, behavior, and cognition. Through this course, you will learn about the popular animal models with simpler brains and interpret the neural mechanisms from multiple perspectives, to acquire a quantitative understanding. Particularly, this course will emphasize interdisciplinary technology, such as large-scale optical neural recording and computational tools. Knowledge gained will provide insights into understanding mental disorders and artificial intelligence.', null, 4, '{"operator": "AND", "items": ["MAT136H1", {"operator": "OR", "items": ["BIO271H1", "CJH332H1", "PSL300H1"]}]}'::jsonb),
    ('CSB435H1', 'Regulatory Networks and Systems in Molecular Biology', '24L/12T', 'After a review of the basic mechanisms of gene regulation and signaling, this course will expose students to several technological and methodological tools for systematically dissecting regulatory networks and systems. Emphasis is on extracting global insight from genome-scale molecular biology datasets. Students will participate in class discussions of research papers, solve systems biology problems using the R statistical software and write an independent paper.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('CSB445H1', 'Sleep Biology in Health and Disease', '3L/33S', 'This course covers theories in why and how we sleep. It will focus on the biological functions of sleep, how the brain generates different sleep states and how a breakdown in sleep mechanisms contribute to sleep disorders like insomnia, sleep walking and narcolepsy. This course emphasizes student participation in seminar discussion and debates.', null, 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BIO270H1", "BIO271H1"]}, {"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}]}'::jsonb),
    ('CSB447H1', 'Living Without Oxygen: Microbes to Mammals', '18L/18S', 'In-depth examination of the unique cellular adaptations of different organisms and tissues to survival in low oxygen environments.  Cellular, physiological and biochemical strategies, and systemic and whole organism responses will be investigated to uncover broad-ranging common strategies employed by diverse organisms to live without oxygen and in other stressful environments.', 'CSB347H1,  NUS348H0', 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BIO270H1", "BIO271H1"]}, {"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}]}'::jsonb),
    ('CSB450H1', 'Proteomics in Systems Biology', '24L', 'A discussion on current proteomic approaches to understand biological processes. The role of mass spectrometry, gel electrophoresis, protein-protein interaction and structural biology in understanding how proteins function in pathways and interaction networks will be discussed.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, "BCH210H1"]}'::jsonb),
    ('CSB451H1', 'Seminar in Plant Cell Biology', '6L/30S', 'Plants represent roughly 80% of the biomass on our planet and are essential primary producers in our ecosystems. At the cellular level, plants display some fascinating differences from other eukaryotic cells, including fragmentation of the secretory pathway, dramatic changes to cytoskeleton organization, and other adaptations to life as a pressurized cell. This course will examine and discuss examples from the primary scientific literature that highlight these distinct features of plant cells by contrasting them to animal cells. We will also discuss how these discoveries can contribute to addressing global challenges, such as developing innovative biomaterials, enhancing food security and cultivating renewable biofuels.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('CSB452H1', 'Molecular Interactions Between Plants and Microorganisms', '24L', 'This course explores the interactions between plants and both pathogenic and beneficial microorganisms at the molecular level. The course consists of two sections: 1. Plant-pathogenic microbe interactions and plant immunity and 2. Plant-beneficial microbe interactions and plant microbiome. The first section focuses on an in-depth discussion about on-going research of plant immunity against pathogenic microbes. The second section introduces the interaction of plant-beneficial microorganisms and their biotechnological usage for agriculture and food production.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('CSB453H1', 'Topics in Cell and Developmental Biology: Biology of Adherens Junctions', '12L/24S', 'Understanding how epithelial cells stick together to form tissues and organs, how they withstand mechanical forces, and how the loss of this adhesion leads to diseases such as cancer and its metastasis, are important fundamental questions in biology with significant implications for human health. Adherens junctions (AJs) are known to be dynamic plasma-membrane structures that mediate cell-cell adhesion and promote tissue integrity. In this course, we will discuss primary scientific literature to understand how AJs facilitate multicellular development and how they impact disease. Lectures will be complemented by student-led presentations of important research papers published in leading scientific journals.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSB331H1", "CSB328H1", "CSB349H1", "MGY311Y1", "BCH311H1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('CSB454H1', 'Pathogenic Effector Biology', '12L/12S', 'Microbial pathogens inject effector proteins into host cells in order to sabotage cellular systems and favor the infection process. This course explores the molecular details of how cellular systems (e.g., secretion, cytoskeleton and signaling) are manipulated by pathogenic effectors to promote the infection process, while emphasizing interesting structural and biochemical features of effector biology along the way. The course will also compare and contrast the strategies employed by plant versus animal pathogens, and how immune systems have evolved to cope with cellular hijacking by pathogenic effector molecules. The course will be based on the primary research literature and involve a combination of lectures and critical discussions of research papers.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('CSB457H1', 'Post-transcriptional Gene Regulation', '12L/24S', 'This course focuses on advances in post-transcriptional gene regulation. Topics include regulatory RNAs, RNA processing, localization, translation, and degradation. In addition to lectures covering background material, emphasis is placed on current research and involves discussion of primary literature in a round-table format.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('CSB458H1', 'Epigenetics', '36S', 'A seminar course exploring non-Mendelian phenomena in plants, fungi and animals that reveal aspects of genome organization and regulation that may provide insight into genome function and evolution.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, {"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('CSB459H1', 'Plant Molecular Biology and Biotechnology', '24L', 'This course introduces students to major features of gene expression and signal transduction in plants. Topics include strategies for generating transgenic plants and regulating gene expression, as well as the importance of signal transduction in plant growth and survival. How plants sense and respond at the molecular level to environmental stresses such as drought, salinity, cold and disease will be discussed. The application of this basic scientific information in biotechnological strategies for improving agronomic traits will also be addressed.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('CSB460H1', 'Plant Signal Transduction', '24L', 'Plant development, ecological adaptation and crop plant productivity depend on the sophisticated potential of plants to sense and compute signals to regulate their responses. An arsenal of genetic and genomic tools is employed to elucidate these plant signal transduction pathways. Examples from the original literature will be used to introduce general concepts of plant signal transduction, molecular biology and genomics and their application in understanding and influencing plant growth and development.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('CSB471H1', 'Foundational Discoveries in Genome Biology and Bioinformatics: AlphaFold2 and its implications', '24S', 'This course is based on the critical analysis of key research articles in genome biology and bioinformatics. The format is interactive and requires students to contribute actively during class meetings. Small student groups will be assigned to present context, figures, data, methods and impact from a number of research articles during the semester. Based on the readings, small student groups will propose new genome technologies or datasets and new bioinformatics software or databases.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCB330Y1", "BCH441H1", "MGY441H1", "CSB352H1", "CSB472H1", "EHJ352H1", "MGY428H1"]}]}'::jsonb),
    ('CSB472H1', 'Computational Genomics and Bioinformatics', '24L/12T', 'Computational analyses of DNA and RNA expression data. Understanding biological databases, sequence alignment, sequence annotation, gene prediction, computational analysis of function, motif analysis, phylogenetic analysis, and gene expression profiling analysis. Applied, theoretical and statistical issues will be addressed.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}'::jsonb),
    ('CSB473H1', 'Chemical Genomics', '24L', 'This course surveys the field of Chemical Genomics, focusing on the analysis of biological problems using chemical approaches. Topics covered include chemical genetics, combinatorial chemistry and combinatorial strategies in molecular biology. Examines both the underlying biological and chemical concepts; however, the focus is primarily biological.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}'::jsonb),
    ('CSB474H1', 'Methods in Genomics and Proteomics', '48P', 'This is a hands-on, laboratory based course offered in conjunction with the Centre for the Analysis of Genome Evolution and Function (CAGEF). It will teach students how to produce and analyze data that are central to the fields of genomics and proteomics. Techniques taught include DNA and RNA extractions, PCR, Next Generation DNA library preparation and sequencing, expression profiling using RNAseq, protein extraction, 2D-gel electrophoresis and mass spectrometry.  This will be combined with associated bioinformatics analyses. (Lab Materials Fee: $53). A lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these (approximate cost is $27).', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, {"operator": "OR", "items": ["BIO255H1", "CSB330H1", "CSB350H1"]}]}'::jsonb),
    ('CSB475H1', 'Plant Metabolomics', '24L', 'This course introduces students to major features of plant metabolism. The content covers plant physiology, natural product chemistry, genetics, molecular biology, and genomics. Topics also include strategies for designing how we modulate metabolic pathways and how we utilize plants for biotechnology through metabolic engineering.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('CSB483H1', 'Seminar in Development', '24S', 'Seminars analyzing major concepts in developmental biology from quantitative, physics-based and molecular perspectives.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSB328H1", "CSB340H1"]}]}'::jsonb),
    ('CSB490H1', 'Team-Based Learning: Current Topics in Cell and Molecular Biology', '8L/16S', 'A team-based learning course with emphasis on questions in the fields of protein biochemistry, synthetic biology, and the evolution of proteins and networks of protein-protein interactions. Lectures and seminars will focus on current research topics within these fields and will provide the background knowledge for students to work in teams to explore the primary research literature, and for each team to develop a formal research proposal. For details on this year''s content, please go to the Undergraduate course section of the CSB website, http://csb.utoronto.ca.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, {"operator": "OR", "items": ["CSB330H1", "CSB349H1", "CSB352H1"]}]}'::jsonb),
    ('CSB491H1', 'Team-Based Research: Research in Cell and Molecular Biology', '60P', 'CSB491H1 is a plant molecular biology lab that builds on molecular biology and biochemistry skills acquired in  CSB350H1 or  CSB330H1. After an initial training lab section, students will work in teams to develop a research project which they will conduct in the second half of the course. They will develop laboratory and teamwork skills that are desirable for them to function in a research laboratory and in the workplace. The course will integrate current molecular biology techniques, including designing and characterizing mutants made with CRISPR/Cas9. (Lab Materials Fee: $53). Lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these items (approximate cost is $27).', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSB330H1", "CSB350H1"]}]}'::jsonb),
    ('CSB492H1', 'Advanced Topics in Cell and Systems Biology', '24L', 'This advanced course covers topics in cell and systems biology at all levels of biological organization.  Students learn about the wide array of state-of-the-art molecular, genomic, proteomic, cell biological, imaging, physiological and computational tools and methods that researchers use to study the behaviour of cells.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSB325H1", "CSB349H1"]}]}'::jsonb),
    ('CSB497H1', 'Independent Research in Cell and Systems Biology I', null, 'An original research project (a literature review alone is not sufficient) requiring the prior consent of a member of the Department to supervise the project. The topic is to be mutually agreed upon by the student and supervisor. They must arrange the time, place, and provision of any materials and submit to the Undergraduate Office a signed form of agreement outlining details prior to being enrolled. In the Fall or Winter sessions, a commitment of 8-10 hours per week is expected for research and related course activities. If spread over both the Fall and Winter sessions, a commitment of 4-5 hours per week is expected. In the Summer Session, the number of hours doubles per week (e.g., 16-20 for F or S, or 8-10 for Y) as the length of the term is halved compared to the Fall or Winter term. Many students spend more than this amount of time as they become immersed in their project. This course is normally open only to fourth year students with adequate background in Cell and Systems Biology. Course requirements include a final report, and either an oral presentation (Summer and Fall sessions) or a poster presentation (Winter session). Two workshops on scientific research are scheduled and highly recommended. Details for enrollment are available at the Undergraduate course section of the CSB website, http://csb.utoronto.ca. Maximum of 2.0 credits allowed among  CSB497H1,  CSB498Y1 and  CSB499Y1. (Lab Materials Fee: approximately $27). Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('CSB498Y1', 'Independent Research in Cell and Systems Biology I', null, 'An original research project (a literature review alone is not sufficient) requiring the prior consent of a member of the Department to supervise the project. The topic is to be mutually agreed upon by the student and supervisor. They must arrange the time, place, and provision of any materials and submit to the Undergraduate Office a signed form of agreement outlining details prior to being enrolled. In the Fall/Winter session, a commitment of 8-10 hours per week is expected for research and related course activities. In the Summer session, the number of hours doubles (16-20 per week) as the length of the term is halved. This course is normally open only to fourth year students with adequate background in Cell and Systems Biology. Course requirements include a final report and either an oral presentation (Summer session) or a poster presentation (Fall/Winter session). Four workshops on scientific research are scheduled and highly recommended. Details for enrollment are available at the Undergraduate course section of the CSB website, http://csb.utoronto.ca. Maximum of 2.0 credits allowed among  CSB497H1,  CSB498Y1 and  CSB499Y1. (Lab Materials Fee: $53). Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('CSB499Y1', 'Independent Research in Cell and Systems Biology II', null, 'Allows students to do a second independent project. Operates in the same manner as  CSB497H1/  CSB498Y1. Maximum of 2.0 credits allowed among  CSB497H1,  CSB498Y1 and  CSB499Y1.  Students who have completed both  CSB497H1 and  CSB498Y1 are excluded from taking  CSB499Y1. (Lab Materials Fee: $53). Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSB497H1", "CSB498Y1"]}]}'::jsonb),
    ('CSC104H1', 'Computational Thinking', '24L/12T', 'Humans have solved problems for millennia on computing devices by representing data as diverse numbers, text, images, sound and genomes, and then transforming the data. A gentle introduction to designing programs (recipes) for systematically solving problems that crop up in diverse domains such as science, literature, and graphics. Social and intellectual issues raised by computing. Algorithms, hardware, software, operating systems, the limits of computation. Note: you may not take this course concurrently with any Computer Science course, but you may take  CSC108H1/ CSC148H1 after  CSC104H1.', 'JCC250H1; Any CSC course except  CSC196H1,  CSC197H1,  CSC199H1, AP, IB, CAPE or GCE Transfer Credits.', 5, null::jsonb),
    ('CSC108H1', 'Introduction to Computer Programming', '36L', 'Programming in a language such as Python. Elementary data types, lists, maps. Program structure: control flow, functions, classes, objects, methods. Algorithms and problem solving. Searching, sorting, and complexity. Unit testing. Floating-point numbers and numerical computation. No prior programming experience required.NOTE: You may take  CSC148H1 after  CSC108H1. You may not take  CSC108H1 in the same term as, or after taking, any of  CSC110Y1/  CSC111H1/  CSC120H1/  CSC148H1.', 'CSC110Y1,  CSC111H1,  CSC120H1,  CSC121H1,  CSC148H1,  CSC108H5,  CSC148H5,  CSCA08H3,  CSCA20H3,  CSCA48H3', 5, null::jsonb),
    ('CSC110Y1', 'Foundations of Computer Science I', '72L/24T', 'An introduction to the field of computer science combining the tools and techniques of programming (using the Python programming language) with rigorous mathematical analysis and reasoning. Topics include: data representations; program control flow (conditionals, loops, exceptions, functions); mathematical logic and formal proof; representation of floating-point numbers and numerical computation; algorithms and running time analysis; software engineering principles (formal specification and design, testing and verification). Prior programming experience is not required to succeed in this course. This course is restricted to students in the first year Computer Science admission stream, and is only offered in the Fall term. Other students planning to pursue studies in computer science should enrol in  CSC108H1,  CSC148H1, and  CSC165H1/ CSC240H1.', 'CSC108H1,  CSC148H1,  CSC165H1', 5, null::jsonb),
    ('CSC111H1', 'Foundations of Computer Science II', '36L/24T', 'A continuation of  CSC110Y1 to extend principles of programming and mathematical analysis to further topics in computer science. Topics include: object-oriented programming (design principles, encapsulation, composition and inheritance); binary representation of numbers; recursion and mathematical induction; abstract data types and data structures (stacks, queues, linked lists, trees, graphs); the limitations of computation. This course is restricted to students in the first year Computer Science admission stream, and is only offered in the Winter term. Other students planning to pursue studies in computer science should enrol in  CSC108H1,  CSC148H1, and  CSC165H1/ CSC240H1.', 'CSC108H1,  CSC148H1,  CSC165H1', 5, '{"operator": "AND", "items": ["CSC110Y1"]}'::jsonb),
    ('CSC148H1', 'Introduction to Computer Science', '36L/24P', 'Abstract data types and data structures for implementing them. Linked data structures. Encapsulation and information-hiding. Object-oriented programming. Specifications. Analyzing the efficiency of programs. Recursion. This course assumes programming experience as provided by  CSC108H1. Students who already have this background may consult the Computer Science Undergraduate Office for advice about skipping  CSC108H1. Practical (P) sections consist of supervised work in the computing laboratory. These sections are offered when facilities are available, and attendance is required. Note: Students may request to move from  CSC148H1 to  CSC108H1 after the last day to add classes and before a deadline set by the course instructors, if space is available in  CSC108H1 at the time of the request.', 'CSC111H1,  CSC207H1,  CSC148H5,  CSC207H5,  CSCA48H3,  CSCB07H3', 5, '{"operator": "AND", "items": ["CSC108H1"]}'::jsonb),
    ('CSC165H1', 'Mathematical Expression and Reasoning for Computer Science', '36L/12T', 'Introduction to abstraction and rigour. Informal introduction to logical notation and reasoning. Understanding, using and developing precise expressions of mathematical ideas, including definitions and theorems. Structuring proofs to improve presentation and comprehension. General problem-solving techniques. Representation of floating-point numbers. Running time analysis of iterative programs. Formal definition of Big-Oh. Diagonalization, the Halting Problem, and some reductions. Unified approaches to programming and theoretical problems.', 'CSC111H1,  CSC236H1,  CSC240H1,  MAT102H5,  CSC236H5,  CSCA67H3,  MATA67H3,  CSCB36H3', 5, null::jsonb),
    ('CSC194H1', 'Impactful Video Game Design', '24S', 'An introduction to the fundamental design and development principles for digital games, and their potential for real-world impact and social betterment. Topics include game design history & social issues, narrative and gameplay elements, human-computer interaction and project management. Strong focus on how design elements affect player engagement and learning. This course requires students to create a game as part of the course, with practical assignments and a final project that reflect industry milestones. No programming is required for this course. Please note that not all CSC first-year seminars will be offered in a given year; please check the Timetable for current offerings. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('CSC196H1', 'Great Ideas in Computing', '36L', 'We will pursue the general (and very debatable) theme of GREAT IDEAS in COMPUTING (including some surprising algorithms). The ambitious goal is to try to identify some of the great ideas that have significantly influenced the field and have helped to make computing so pervasive. We will concentrate on mathematical, algorithmic and software ideas with the understanding that the importance and usefulness of these ideas depends upon (and often parallels) the remarkable ideas and progress in computing and communications hardware. As we will see, many of the great ideas were against the "prevailing opinion". The list of topics we shall discuss will depend to some degree on the background and interests of the class. Please note that not all CSC first-year seminars will be offered in a given year; please check the Timetable for current offerings. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('CSC197H1', 'Big Data and Privacy', '24S', 'The rapid advance of technology has brought remarkable changes to how we conduct our daily lives, from how we communicate, consume news and data, and purchase goods. As we increase our online activity, so too do we increase the amount of personal data that we''re sharing, often without realizing it. The questions of exactly what data is being collected, who is collecting and accessing this data, and how this data is being used, have significant implications for both individuals and our larger social and political institutions. Organized by a wide variety of case studies drawn from current events, we''ll study how personal data can be collected and tracked, how personal and social factors may influence our own decisions about whether and how much to share our data, and what broader political and legal tools are used to either protect or subvert individual privacy. Please note that not all CSC first-year seminars will be offered in a given year; please check the Timetable for current offerings. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('CSC199H1', 'Intelligence, Artificial and Human', '36S', 'What is human intelligence? How close are we to replicating it? How productive/reductive is the brain-computer analogy? What ethical challenges are posed by AI on workers, society, and the environment? Can we put a hold on "progress"? Is Silicon Valley the seat of a new techno-religion? What can they teach us about today''s research priorities? What insight (or inspiration) can we get from works of science fiction about the future of human-AI interaction? Through reading discussion, written assignment, and workshops, this seminar will present students with the opportunity to integrate their computer science interests with philosophy, history, and literature. There is an equivalent course offered by St. Michael''s College. Students may take one or the other but not both. Please note that not all CSC first-year seminars will be offered in a given year; please check the Timetable for current offerings. Restricted to first-year students. Not eligible for CR/NCR option.', 'SMC199H1 (Intelligence, Artificial and Human)', 3, null::jsonb),
    ('CSC207H1', 'Software Design', '24L/24T', 'An introduction to software design and development concepts, methods, and tools using a statically-typed object-oriented programming language such as Java. Topics from: version control, unit testing, refactoring, object-oriented design and development, design patterns, advanced IDE usage, regular expressions, and reflection.', 'CSC207H5,  CSCB07H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC148H1", "CSC148H5", "CSCA48H3", "CSC111H1"]}]}'::jsonb),
    ('CSC209H1', 'Software Tools and Systems Programming', '24L/12T', 'Software techniques in a Unix-style environment, using scripting languages and a machine-oriented programming language (typically C). What goes on in the operating system when programs are executed. Core topics: creating and using software tools, pipes and filters, file processing, shell programming, processes, system calls, signals, basic network programming.', 'CSC372H1,  CSC369H1,  CSC469H1,  CSC209H5,  CSC369H5,  CSC469H5,  CSCB09H3,  CSCC69H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC207H1", "CSC207H5", "CSCB07H3"]}]}'::jsonb),
    ('CSC236H1', 'Introduction to the Theory of Computation', '24L/12T', 'The application of logic and proof techniques to Computer Science. Mathematical induction; correctness proofs for iterative and recursive algorithms; recurrence equations and their solutions; introduction to automata and formal languages. This course assumes university-level experience with proof techniques and algorithmic complexity as provided by  CSC165H1. Very strong students who already have this experience (e.g. successful completion of  MAT157Y1) may consult the undergraduate office about proceeding directly into  CSC236H1 or  CSC240H1.', 'CSC240H1,  CSC236H5,  CSCB36H3', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC148H1", "CSC148H5", "CSCA48H3"]}, {"operator": "OR", "items": ["CSC165H1", "MAT102H5", "CSCA67H3", "MATA67H3"]}]}, "CSC111H1"]}'::jsonb),
    ('CSC240H1', 'Enriched Introduction to the Theory of Computation', '24L/12T', 'The rigorous application of logic and proof techniques to Computer Science. Propositional and predicate logic; mathematical induction and other basic proof techniques; correctness proofs for iterative and recursive algorithms; recurrence equations and their solutions (including the Master Theorem); introduction to automata and formal languages. This course covers the same topics as  CSC236H1, together with selected material from  CSC165H1, but at a faster pace, in greater depth and with more rigour, and with more challenging assignments. Greater emphasis will be placed on proofs and theoretical analysis. Certain topics briefly mentioned in  CSC165H1 or  CSC236H1 may be covered in more detail in this course, and some additional topics may also be covered.', 'CSC236H1,  CSC263H1/  CSC265H1,  CSC236H5,  CSC263H5,  CSCB36H3,  CSCB63H3', 5, '{"operator": "OR", "items": ["CSC110Y1", "CSC165H1"]}'::jsonb),
    ('CSC258H1', 'Computer Organization', '36L/36P', 'Computer structures, machine languages, instruction execution, addressing techniques, and digital representation of data. Computer system organization, memory storage devices, and microprogramming. Block diagram circuit realizations of memory, control and arithmetic functions. There are a number of laboratory periods in which students conduct experiments with digital logic circuits.', 'CSC258H5,  CSCB58H3', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC148H1", "CSC148H5", "CSCA48H3"]}, {"operator": "OR", "items": ["CSC165H1", "CSC240H1", "MAT102H5", "MATA67H3", "CSCA67H3"]}]}, "CSC111H1"]}'::jsonb),
    ('CSC263H1', 'Data Structures and Analysis', '24L/12T', 'Algorithm analysis: worst-case, average-case, and amortized complexity. Expected worst-case complexity, randomized quicksort and selection. Standard abstract data types, such as graphs, dictionaries, priority queues, and disjoint sets. A variety of data structures for implementing these abstract data types, such as balanced search trees, hashing, heaps, and disjoint forests. Design and comparison of data structures. Introduction to lower bounds.', 'CSC265H1,  CSC263H5,  CSCB63H3, MIE245H1', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC236H1", "CSC240H1", "CSC236H5", "CSCB36H3"]}, {"operator": "OR", "items": ["STA237H1", "STA247H1", "STA255H1", "STA257H1", "STAB57H3", "STAB52H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["APS105H1", "APS106H1", "ESC180H1"]}, {"operator": "OR", "items": ["ECE302H1", "STA286H1", "CHE223H1", "CME263H1", "MIE231H1", "MIE236H1", "MSE238H1", "ECE286H1"]}]}]}'::jsonb),
    ('CSC265H1', 'Enriched Data Structures and Analysis', '24L/12T', 'This course covers the same topics as  CSC263H1, but at a faster pace, in greater depth and with more rigour, and with more challenging assignments. Greater emphasis will be placed on proofs, theoretical analysis, and creative problem-solving. Certain topics briefly mentioned in  CSC263H1 may be covered in more detail in this course, and some additional topics may also be covered.', 'CSC263H1,  CSC263H5,  CSCB63H3', 5, '{"operator": "OR", "items": ["CSC240H1", {"operator": "AND", "items": [{"operator": "OR", "items": ["CSC236H1", "CSC236H5", "CSCB36H3"]}, {"operator": "OR", "items": ["MAT377H1", "STA237H1", "STA247H1", "STA255H1", "STA257H1"]}]}]}'::jsonb),
    ('CSC271H1', 'Computational Principles and Methods for Data Science', '24L/12T', 'Computational tools and methods are a cornerstone of the data scientist''s toolbox, useful in a variety of applications and disciplines. This course builds on introductory data science and computer programming skills to equip students with several of these tools and methods. Computational methods for gathering and storing data via web APIs or web scraping or other formats; data pre-processing methods useful in data science algorithms; using version control and other tools to implement reproducible data science workflows; using web tools to communicate data science results and build data science products; creating, distributing, and accessing open-source data science software libraries. This course assumes prerequisite experience in computer programming, but does not require any additional knowledge or prior experience with any of the tools or methods covered.', 'CSC207H1/  ECO225H1', 5, '{"operator": "OR", "items": ["CSC108H1", "CSC110Y1", "CSC148H1"]}'::jsonb),
    ('CSC299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSC299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSC300H1', 'Computers and Society', '24L/12T', 'This course offers a concise introduction to ethics in computing, distilled from the ethical and social discussions carried on by today''s academic and popular commentators. This course covers a wide range of topics within this area including the philosophical framework for analyzing computer ethics; the impact of computer technology on security, privacy and intellectual property, digital divide, and gender and racial discrimination; the ethical tensions with Artificial Intelligence around future of work and humanity, the emerging role of online social media over voice, inclusion, and democracy; and the environmental consequences of computing.', 'CSC300H5,  CSCD03H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": "CSC"}]}'::jsonb),
    ('CSC301H1', 'Introduction to Software Engineering', '24L/12T', 'An introduction to agile development methods appropriate for medium-sized teams and rapidly-moving projects. Basic software development infrastructure; requirements elicitation and tracking; estimation and prioritization; teamwork skills; basic modeling; design patterns and refactoring; discussion of ethical issues, and professional responsibility.', 'CSC301H5,  CSCC01H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}, {"operator": "OR", "items": ["CSC263H1", "CSC265H1", "CSC263H5", "CSCB63H3"]}]}'::jsonb),
    ('CSC302H1', 'Engineering Large Software Systems', '24L/12T', 'An introduction to the theory and practice of large-scale software system design, development, and deployment. Project management; advanced UML; reverse engineering; requirements inspection; verification and validation; software architecture; performance modelling and analysis.', 'CSCD01H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": ["CSC301H1", "CSC301H5", "CSCC01H3"]}'::jsonb),
    ('CSC303H1', 'Social and Information Networks', '24L/12T', 'A course on how networks underlie the social, technological, and natural worlds, with an emphasis on developing intuitions for broadly applicable concepts in network analysis. Topics include: introductions to graph theory, network concepts, and game theory; social networks; information networks; the aggregate behaviour of markets and crowds; network dynamics; information diffusion; popular concepts such as "six degrees of separation," the "friendship paradox," and the "wisdom of crowds."', 'CSCC46H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC263H1", "CSC265H1", "CSC263H5", "CSCB63H3"]}, {"operator": "OR", "items": ["STA247H1", "STA255H1", "STA257H1", "ECO227Y1", "STA237H1", "STAB52H3", "STAB57H3"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}]}'::jsonb),
    ('CSC304H1', 'Algorithmic Game Theory and Mechanism Design', '24L/12P', 'A mathematical and computational introduction to game theory and mechanism design. Analysis of equilibria in games and computation of price of anarchy. Design and analysis mechanisms with monetary transfers (such as auctions). Design and analysis of mechanisms without monetary transfers (such as voting and matching). This course is intended for economics, mathematics, and computer science students.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["STA247H1", "STA255H1", "STA257H1", "STA237H1", "PSY201H1", "ECO227Y1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('CSC308H1', 'Technology Leadership', '36L', 'An exploration of the core aspects of leadership within the context of the software-oriented industry and academic research sectors. Topics include corporate mission, vision, and stakeholder roles in the technology sector; strategic planning; competitive technology market analysis; decision-making; a practical awareness of financial documents; contract negotiation; equity and financing in technology business growth; business-to-business (B2B) and business-to-consumer (B2C) software markets; principles of effective communication and influence in a corporate setting; professional development strategies for a software-oriented career; crafting an impactful elevator pitch; understanding of employment rights. The approach ensures that graduates are well-prepared to step into leadership roles and navigate the complexities of the tech industry and of academic research. Students must be enrolled in the Focus in Technology Leadership to enrol in this course.', null, 3, '{"operator": "AND", "items": ["CSC207H1"]}'::jsonb),
    ('CSC309H1', 'Programming on the Web', '24L/12T', 'An introduction to software development on the web. Concepts underlying the development of programs that operate on the web; survey of technological alternatives; greater depth on some technologies. Operational concepts of the internet and the web, static client content, dynamic client content, dynamically served content, n-tiered architectures, web development processes, and security on the web.', 'CSC309H5,  CSCC09H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/ 400-level CSC/ ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["ESC180H1", "ESC190H1", {"operator": "AND", "items": ["APS105H1", "ECE244H1"]}]}]}]}'::jsonb),
    ('CSC310H1', 'Information Theory', '24L/12T', 'Measuring information. Entropy, mutual information and their meaning. Probabilistic source models and the source coding theorem. Data compression. Noisy channels and the channel coding theorem. Error correcting codes and their decoding. Applications to inference, learning, data structures and communication complexity.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC148H1", "CSC148H5", "CSCA48H3", "CSC111H1"]}, {"operator": "OR", "items": ["CSC263H1", "CSC263H5", "CSCB63H3", "CSC265H1"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}]}, {"operator": "AND", "items": ["ESC190H1", {"operator": "OR", "items": ["ECE345H1", "ECE358H1", "MIE245H1"]}, {"operator": "OR", "items": ["MAT185H1", "MAT188H1"]}]}]}'::jsonb),
    ('CSC311H1', 'Introduction to Machine Learning', '24L/12T', 'An introduction to methods for automated learning of relationships on the basis of empirical data. Classification and regression using nearest neighbour methods, decision trees, linear models, and neural networks. Clustering algorithms. Problems of overfitting and of assessing accuracy.', 'CSC411H1,  STA314H1, ECE421H1,  CSC311H5,  CSC411H5,  CSCC11H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC207H1", "CSC207H5", "CSCB07H3"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}, {"operator": "OR", "items": ["STA237H1", "STA247H1", "STA255H1", "STA257H1"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["APS105H1", "APS106H1", "ESC180H1", "CSC180H1"]}, {"operator": "OR", "items": ["MAT291H1", "MAT294H1", {"operator": "AND", "items": ["MAT186H1", "MAT187H1"]}, {"operator": "AND", "items": ["MAT194H1", "MAT195H1"]}, {"operator": "AND", "items": ["ESC194H1", "ESC195H1"]}]}, {"operator": "OR", "items": ["MAT185H1", "MAT188H1"]}, {"operator": "OR", "items": ["STA286H1", "CHE223H1", "CME263H1", "MIE231H1", "MIE236H1", "MSE238H1", "ECE286H1"]}]}]}'::jsonb),
    ('CSC316H1', 'Data Visualization: Foundations and Advanced Programming', '24L/12T', 'The amount and complexity of information produced in science, engineering, business, and everyday human activity is increasing at staggering rates. The goal of this course is to expose you to visual representation methods and techniques that increase the understanding of complex data. Good visualizations not only present a visual interpretation of data, but do so by improving comprehension, communication, and decision making. In this course you will learn how the human visual system processes and perceives images, good design practices for visualization, methods for visualization of data from a variety of fields, and programming of interactive web-based visualizations, using front-end libraries (e.g., D3 or Vega).', null, 5, '{"operator": "OR", "items": ["CSC207H1", "CSC207H5", "CSCB07H3"]}'::jsonb),
    ('CSC317H1', 'Computer Graphics', '24L/12T', 'Identification and characterization of the objects manipulated in computer graphics, the operations possible on these objects, efficient algorithms to perform these operations, and interfaces to transform one type of object to another. Display devices, display data structures and procedures, graphical input, object modelling, transformations, illumination models, primary and secondary light effects; graphics packages and systems. Students, individually or in teams, implement graphical algorithms or entire graphics systems.', 'CSC418H1,  CSCD18H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT232H5", "MAT233H5"]}, "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1", "MAT223H5", "MATA22H3"]}, {"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT291H1", "MAT292H1", "MAT294H1"]}, {"operator": "OR", "items": ["MAT185H1", "MAT188H1"]}, {"operator": "OR", "items": ["APS105H1", "ESC180H1", "CSC180H1"]}]}]}'::jsonb),
    ('CSC318H1', 'The Design of Interactive Computational Media', '24L/24T', 'User-centred design of interactive systems; methodologies, principles, and metaphors; task analysis. Interdisciplinary design; the role of graphic design, industrial design, and the behavioural sciences. Interactive hardware and software; concepts from computer graphics. Typography, layout, colour, sound, video, gesture, and usability enhancements. Classes of interactive graphical media; direct manipulation systems, extensible systems, rapid prototyping tools. Students work on projects in interdisciplinary teams.', 'CSC318H5,  CSCC10H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"credits": 0.5, "department": "CSC"}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["ESC180H1", "ESC190H1", "APS105H1", "APS106H1"]}]}]}'::jsonb),
    ('CSC320H1', 'Introduction to Visual Computing', '24L/12T', 'A first-principles introduction to the acquisition and computational processing of 2D images, aimed at students interested in computer vision, digital photography and computer graphics. The course serves as a stepping stone for tackling more advanced courses in those subjects and covers four broad themes: (1) mathematical and engineering foundations: introducing key concepts from geometry; multivariate calculus; linear algebra; image and signal processing; and human vision, (2) algorithms for low-level computer vision: image warping, morphing and stitching; image enhancement; image scissoring and inpainting; color image processing and display; face recognition; and 2D image matching, (3) implementing several such tools in Python, and (4) a first taste of vision and graphics research. Understanding how to turn algorithmic descriptions in research papers into working computer vision code—and how to evaluate its performance—will be key skills acquired in the course.', 'CSC320H5. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC263H1", "CSC265H1", "CSC263H5", "CSCB63H3"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}, {"operator": "OR", "items": ["MAT136H1", "MAT137Y1", "MAT157Y1", "MAT235Y1", "MAT237Y1", "MAT257Y1"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["ECE345H1", "ECE358H1", "MIE335H1"]}, {"operator": "OR", "items": ["MAT185H1", "MAT188H1"]}, {"operator": "OR", "items": ["MAT291H1", "MAT292H1"]}]}]}'::jsonb),
    ('CSC324H1', 'Principles of Programming Languages', '24L/12T', 'Programming principles common in modern languages; details of commonly used paradigms. The structure and meaning of code. Scope, control flow, datatypes, and parameter passing. Two non-procedural, non-object-oriented programming paradigms: functional programming (illustrated by languages such as Lisp/Scheme, ML or Haskell) and logic programming (typically illustrated in Prolog).', 'CSC324H5,  CSCC24H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": ["CSC263H1", "CSC265H1", "CSC263H5", "CSCB63H3"]}'::jsonb),
    ('CSC336H1', 'Numerical Methods', '24L/12T', 'The study of computational methods for solving problems in linear algebra, non-linear equations, and approximation. The aim is to give students a basic understanding of both floating-point arithmetic and the implementation of algorithms used to solve numerical problems, as well as a familiarity with current numerical computing environments.', 'CSC338H5,  CSCC37H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC148H1", "CSC148H5", "CSCA48H3", "CSC111H1"]}, {"operator": "OR", "items": ["MAT133Y1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT135Y1", "MAT137Y1", "MAT157Y1"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}]}'::jsonb),
    ('CSC343H1', 'Introduction to Databases', '36L', 'Introduction to database management systems. The relational data model. Relational algebra. Querying and updating databases: the query language SQL. Application programming with SQL. Integrity constraints, normal forms, and database design. Elements of database system technology: query processing, transaction management.', 'CSC343H5,  CSCC43H3,  MIE253H1,  MIE353H1. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC111H1", "CSC165H1", "MAT102H5", "CSCA67H3", "MATA67H3", "CSC240H1", {"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT135Y1", "MAT137Y1", "MAT157Y1"]}, {"operator": "OR", "items": ["CSC207H1", "CSC207H5", "CSCB07H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["ESC194H1", "ESC195H1"]}, {"operator": "AND", "items": ["MAT186H1", "MAT187H1"]}, {"operator": "AND", "items": ["MAT194H1", "MAT195H1"]}]}, {"operator": "OR", "items": ["ECE345H1", "ESC190H1"]}]}]}'::jsonb),
    ('CSC364H1', 'Foundations of Computer Security', '24L/12T', 'This course provides a comprehensive introduction to computer security, covering the foundational principles of secure systems and cryptography. It focuses on the core principles of designing secure systems, including the use of cryptography to ensure data confidentiality and integrity. Students will also learn how to approach systems from an adversarial perspective and study threat modeling to better understand and mitigate security threats. The course serves as an entry point for undergraduates interested in computer security and prepare students for advanced topics such as applied cryptography, systems security, machine learning security, and theoretical cryptography at the graduate level.', 'CSC347H5,  CSC427H5,  ECE568H1,  CSCD27H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}, {"operator": "OR", "items": ["CSC236H1", "CSC236H5", "CSCB36H3"]}]}'::jsonb),
    ('CSC367H1', 'Parallel Programming', '24L/12T', 'Introduction to aspects of parallel programming. Topics include computer instruction execution, instruction-level parallelism, memory system performance, task and data parallelism, parallel models (shared memory, message passing), synchronization, scalability and Amdahl''s law, Flynn taxonomy, vector processing and parallel computing architectures.', 'CSC367H5. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC258H1", "CSC258H5", "CSCB58H3"]}, {"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}]}'::jsonb),
    ('CSC368H1', 'Computer Architecture', '24L/12T', 'An introduction to computer architecture and how to evaluate the performance of workloads running on processor architectures. Topics include statically and dynamically scheduling instructions in a processor pipeline; speculative execution through branch prediction; hardware cache organizations, their policies, and prefetching; multi-core processors, cache coherence, and synchronization primitives. Additional topics may include other relevant architectures, such as GPUs or domain specific accelerators.', 'ECE552H1. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}, {"operator": "OR", "items": ["CSC258H1", "CSC258H5", "CSCB58H3"]}]}'::jsonb),
    ('CSC369H1', 'Operating Systems', '24L/12T', 'Principles of operating systems. The operating system as a control program and as a resource allocator. The concept of a process and concurrency problems: synchronization, mutual exclusion, deadlock. Additional topics include memory management, file systems, process scheduling, threads, and protection.', 'CSC369H5,  CSCC69H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}, {"operator": "OR", "items": ["CSC258H1", "CSC258H5", "CSCB58H3"]}]}'::jsonb),
    ('CSC373H1', 'Algorithm Design, Analysis & Complexity', '36L/12T', 'Standard algorithm design techniques: divide-and-conquer, greedy strategies, dynamic programming, linear programming, randomization, network flows, approximation algorithms. Brief introduction to NP-completeness: polynomial time reductions, examples of various NP-complete problems, self-reducibility. Additional topics may include approximation and randomized algorithms. Students will be expected to show good design principles and adequate skills at reasoning about the correctness and complexity of algorithms.', 'CSC375H1,  CSC373H5,  CSCC73H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": ["CSC263H1", "CSC265H1", "CSC263H5", "CSCB63H3"]}'::jsonb),
    ('CSC384H1', 'Introduction to Artificial Intelligence', '24L/12T', 'Theories and algorithms that capture (or approximate) some of the core elements of computational intelligence. Topics include: search; logical representations and reasoning, classical automated planning, representing and reasoning with uncertainty, learning, decision making (planning) under uncertainty. Assignments provide practical experience, in both theory and programming, of the core topics.', 'CSC384H5,  CSCD84H3,  MIE369H1. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC263H1", "CSC265H1", "CSC263H5", "CSCB63H3"]}, {"operator": "OR", "items": ["STA237H1", "STA247H1", "STA255H1", "STA257H1", "STAB57H3", "STAB52H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["ECE345H1", "ECE358H1", "MIE245H1"]}, {"operator": "OR", "items": ["ECE302H1", "STA286H1", "CHE223H1", "CME263H1", "MIE231H1", "MIE236H1", "MSE238H1", "ECE286H1"]}]}]}'::jsonb),
    ('CSC385H1', 'Microprocessor Systems', '24L/24P', 'An examination of the issues unique to embedded computing and the Internet of Things (IoT). Software techniques for programming with sensors on lightweight, low-power processors. Topics include embedded processor architectures, interrupts, scheduling for real-time systems, power consumption, and connected device characteristics. Laboratory experiments provide hands-on experience with embedded systems. A refundable deposit of $90 will be charged for the use of discovery board in lab activities.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}, {"operator": "OR", "items": ["CSC258H1", "CSC258H5", "CSCB58H3"]}]}'::jsonb),
    ('CSC396Y0', 'Designing Systems for Real World Problems', null, 'This Summer Abroad special offering provides students with an opportunity to explore new environments, which improves their ability to see their own world with increased sensitivity and germinates new design ideas. In this course, students will identify a real problem in the world and work in groups on projects addressing this problem. Students will explore their problem space and the people within that space, identify needs, constraints, and requirements, and ultimately design solutions. Their designs will be iterated by gathering feedback and conducting usability testing on the early prototypes. The course projects will culminate with development of a technological solution that addresses the identified problem. Final project presentations will take place at the end of the course. This course can be counted as 0.5 credit at the 300-level for Computer Science program completion.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"credits": 0.5, "department": "CSC"}]}'::jsonb),
    ('CSC398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSC398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSC399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CSC399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', null, null::jsonb),
    ('CSC401H1', 'Natural Language Computing', '24L/12T', 'Introduction to techniques involving natural language processing and speech in applications such as information retrieval, speech recognition and synthesis, machine translation, summarization, and dialogue. N-grams, corpus analysis, neural methods, and information theory. Python and other software.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC207H1", "CSC209H1", "CSC207H5", "CSCB07H3", "CSC209H5", "CSCB09H3"]}, {"operator": "OR", "items": ["STA237H1", "STA247H1", "STA255H1", "STA257H1", "STAB57H3", "STAB52H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["APS105H1", "APS106H1", "ESC180H1", "CSC180H1"]}, {"operator": "OR", "items": ["ECE302H1", "STA286H1", "CHE223H1", "CME263H1", "MIE231H1", "MIE236H1", "MSE238H1", "ECE286H1"]}]}]}'::jsonb),
    ('CSC404H1', 'Introduction to Video Game Design', '36L', 'Concepts and techniques for the design and development of electronic games. History, social issues, and story elements. The business of game development and game promotion. Software engineering, artificial intelligence, and graphics elements. Level and model design. Audio elements. Practical assignments leading to team implementation of a complete game. Students must submit an application to the course describing relevant interests, experience, and skills and general academic history. Application questions are set and assessed by the instructor. Applications from St. George students enroled in a Computer Science program or the Data Science Specialist program will be considered first. Applications by students from other programs with appropriate prerequisites will be considered as space permits.  Please visit https://q.utoronto.ca/courses/221753/pages/400-level-course-balloting-and-applications for application deadlines and details. A decision on your application will be confirmed approximately 2-3 weeks after the application deadline, so students should enrol in an alternate course until the results of their application are confirmed.', 'CSC404H5. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 1, '{"operator": "OR", "items": ["CSC301H1", "CSC301H5", "CSCC01H3", "CSC317H1", "CSC318H1", "CSC318H5", "CSCC10H3", "CSC384H1", "CSC384H5", "CSCD84H3", "CSC417H1", "CSC419H1"]}'::jsonb),
    ('CSC410H1', 'Software Testing and Verification', '24L/24T', 'Concepts and state-of-the-art techniques in quality assessment for software engineering; quality attributes; formal specifications and their analysis; testing, verification, and validation.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC207H1", "CSC207H5", "CSCB07H3"]}, {"operator": "OR", "items": ["CSC236H1", "CSC236H5", "CSCB36H3", "CSC240H1"]}]}'::jsonb),
    ('CSC412H1', 'Probabilistic Learning and Reasoning', '24L/12T', 'An introduction to probability as a means of representing and reasoning with uncertain knowledge. Qualitative and quantitative specification of probability distributions using probabilistic graphical models. Algorithms for inference and probabilistic reasoning with graphical models. Statistical approaches and algorithms for learning probability models from empirical data. Applications of these models in artificial intelligence and machine learning.', 'STA414H1,  STAD68H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC311H1", "STA314H1", "CSCC11H3", "CSC311H5"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["ECE421H1", "ROB313H1"]}]}]}'::jsonb),
    ('CSC413H1', 'Neural Networks and Deep Learning', '24L/12T', 'An introduction to neural networks and deep learning. Backpropagation and automatic differentiation. Architectures: convolutional networks and recurrent neural networks. Methods for improving optimization and generalization. Neural networks for unsupervised and reinforcement learning.', 'CSC321H5,  CSC413H5. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC311H1", "CSC311H5", "CSCC11H3", "STA314H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1", "MAT257Y5", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MAT233H5", "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1", "MAT223H5", "MATA23H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["ECE421H1", "ROB313H1"]}, {"operator": "OR", "items": ["MAT291H1", "MAT294H1", "AER210H1"]}, {"operator": "OR", "items": ["MAT185H1", "MAT188H1"]}]}]}'::jsonb),
    ('CSC417H1', 'Physics-Based Animation', '24L/12T', 'This course is designed to introduce students to the field of physics-based animation by exposing them to the underlying mathematical and algorithmic techniques required to understand and develop efficient numerical simulations of physical phenomena such as rigid bodies, deformable bodies and fluids. Topics covered include rigid body simulation, elasticity simulation, cloth simulation, collision detection and resolution and fluid simulation. Along the way, we will explore the underlying mathematics of ordinary differential equations, discrete time integration, finite element methods and more.Students should have a strong background in Linear Algebra and Multivariate Calculus.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}, {"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT291H1", "MAT294H1"]}, {"operator": "OR", "items": ["MAT185H1", "MAT188H1"]}, {"operator": "OR", "items": ["APS105H1", "ESC180H1", "CSC180H1"]}]}]}'::jsonb),
    ('CSC419H1', 'Geometry Processing', '24L/12T', 'Extending traditional signal processing, geometry processing interprets three-dimensional curves and surfaces as signals. Just as audio and image signal data can be filtered, denoised and decomposed spectrally, so can the geometry of a three-dimensional curve or surface. The course covers algorithms and mathematics behind fundamental operations for interpreting and manipulating geometric data. These essential tools enable: geometric modeling for computer aided design, life-like animations for computer graphics, reliable physical simulations, and robust scene representations for computer vision. Topics include: discrete curves and surfaces, curvature computation, surface reconstruction from point clouds, surface smoothing and denoising, parameterization, symmetry detection, and animation.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}, {"operator": "OR", "items": ["CSC209H1", "CSC209H5", "CSCB09H3"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["MAT291H1", "MAT294H1"]}, {"operator": "OR", "items": ["MAT185H1", "MAT188H1"]}, {"operator": "OR", "items": ["APS105H1", "ESC180H1", "CSC180H1"]}]}]}'::jsonb),
    ('CSC420H1', 'Introduction to Image Understanding', '24L/12P', 'Introduction to basic concepts in computer vision. Extraction of image features at multiple scales. Robust estimation of model parameters. Multiview geometry and reconstruction. Image motion estimation and tracking. Object recognition. Topics in scene understanding as time permits.', 'CSC420H5. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC263H1", "CSC265H1", "CSC263H5", "CSCB63H3", "ECE345H1", "ECE358H1", "MIE335H1"]}, {"operator": "OR", "items": ["CSC311H1", "STA314H1", "CSC311H5", "CSCC11H3", "ROB313H1", "ECE421H1"]}, {"operator": "OR", "items": ["CSC320H1", "CSC320H5"]}]}'::jsonb),
    ('CSC428H1', 'Human-Computer Interaction', '24L/12T', 'Understanding human behaviour as it applies to user interfaces: work activity analysis, observational techniques, questionnaire administration, and unobtrusive measures. Operating parameters of the human cognitive system, task analysis and cognitive modelling techniques and their application to designing interfaces. Interface representations and prototyping tools. Cognitive walkthroughs, usability studies and verbal protocol analysis. Case studies of specific user interfaces.', 'CSC428H5. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC318H1", "CSC318H5", "CSCC10H3"]}, {"operator": "OR", "items": ["STA237H1", "STA247H1", "STA255H1", "STA257H1", "ECE302H1", "STA286H1", "CHE223H1", "CME263H1", "MIE231H1", "MIE236H1", "MSE238H1", "ECE286H1"]}, {"operator": "OR", "items": ["CSC207H1", "APS105H1", "ESC180H1", "CSC180H1"]}]}'::jsonb),
    ('CSC436H1', 'Numerical Algorithms', '24L/12T', 'Numerical algorithms for the algebraic eigenvalue problem, approximation, integration, and the solution of ordinary differential equations. Emphasis is on the convergence, stability, and efficiency properties of the algorithms.', 'CSCD37H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": ["CSC336H1", "CSC338H5", "CSCC37H3"]}'::jsonb),
    ('CSC438H1', 'Computability and Logic', '24L/12T', 'Computable functions, Church''s thesis, unsolvable problems, recursively enumerable sets. Predicate calculus, including the completeness, compactness, and Lowenheim-Skolem theorems. Formal theories and the Gödel Incompleteness Theorem. Ordinarily offered in years alternating with  CSC448H1.', 'MAT309H1;  PHL348H1. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "OR", "items": ["CSC463H1", "CSC373H1", "CSC363H5", "CSCC63H3", "MAT247H1"]}'::jsonb),
    ('CSC443H1', 'Database System Technology', '24L/12T', 'Implementation of database management systems. Storage management, indexing, query processing, concurrency control, transaction management. Database systems on parallel and distributed architectures. Modern database applications: data mining, data warehousing, OLAP, data on the web. Object-oriented and object-relational databases.', 'CSCD43H3. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC343H1", "CSC343H5", "CSCC43H3"]}, {"operator": "OR", "items": ["CSC369H1", "CSC369H5", "CSCC69H3"]}, {"operator": "OR", "items": ["CSC373H1", "CSC373H5", "CSCC73H3"]}]}'::jsonb),
    ('CSC446H1', 'Computational Methods for Partial Differential Equations', '24L/12T', 'Finite Difference and Finite Element methods for boundary value problems including 2-point boundary value problems and 2-dimensional problems. Convergence of methods. Efficiency of the solution of linear systems. Finite difference methods for initial value problems. Consistency, stability and convergence. Method of lines. Special topics of interest among domain decomposition, multigrid, FFT solvers. Ordinarily offered in years alternating with  CSC466H1.', 'NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC336H1", "CSC338H5", "CSCC37H3"]}, {"operator": "OR", "items": ["MAT237Y1", "MAT257Y1"]}, {"operator": "OR", "items": ["APM346H1", "MAT351Y1", "MAT244H1", "MAT267H1"]}]}'::jsonb),
    ('CSC448H1', 'Formal Languages and Automata', '24L/12T', 'Regular, deterministic, context free, context sensitive, and recursively enumerable languages via generative grammars and corresponding automata (finite state machines, push down machines, and Turing machines). Topics include complexity bounds for recognition, language decision problems and operations on languages. Ordinarily offered in years alternating with  CSC438H1.', 'CSC448H5. NOTE: Students not enrolled in the Computer Science Major or Specialist program at A&S, UTM, or UTSC, or the Data Science Specialist at A&S, are limited to a maximum of 1.5 credits in 300-/400-level CSC/ECE courses.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CSC236H1", "CSC236H5", "CSCB36H3", "CSC240H1"]}, {"operator": "OR", "items": ["CSC263H1", "CSC263H5", "CSCB63H3", "CSC265H1"]}]}'::jsonb)
